# ---------------------------------------------------- 通用 IOC（威胁情报）与哈希
IOC = {"ip": set(), "domain": set(), "hash": set(), "path": set(), "keyword": set()}
IOC_INFO = []


def sha256_file(path, limit=None):
    try:
        h = hashlib.sha256()
        with open(path, "rb") as f:
            read = 0
            while True:
                chunk = f.read(262144)
                if not chunk:
                    break
                h.update(chunk)
                read += len(chunk)
                if limit and read >= limit:
                    break
        return h.hexdigest()
    except Exception:
        return ""


def md5_file(path, limit=None):
    try:
        h = hashlib.md5()
        with open(path, "rb") as f:
            read = 0
            while True:
                chunk = f.read(262144)
                if not chunk:
                    break
                h.update(chunk)
                read += len(chunk)
                if limit and read >= limit:
                    break
        return h.hexdigest()
    except Exception:
        return ""


def shannon_entropy(data):
    """字节熵（0-8），>7.2 通常为加密/压缩载荷。"""
    if not data:
        return 0.0
    import math
    counts = [0] * 256
    for b in bytearray(data[:65536]):
        counts[b] += 1
    n = float(sum(counts[:256]))
    ent = 0.0
    for c in counts:
        if c:
            p = c / n
            ent -= p * math.log(p, 2)
    return round(ent, 2)


def load_ioc_file(path):
    """加载 IOC 列表（每行一条，支持注释 #）：自动识别 IP/域名/哈希/路径/关键字。"""
    n = 0
    t = safe_read(path, limit=4 * 1024 * 1024)
    if not t:
        return 0
    for ln in t.splitlines():
        s = ln.strip()
        if not s or s.startswith("#"):
            continue
        if re.match(r"^\d{1,3}(\.\d{1,3}){3}$", s):
            IOC["ip"].add(s)
        elif re.match(r"^[a-fA-F0-9]{32}$", s) or re.match(r"^[a-fA-F0-9]{64}$", s):
            IOC["hash"].add(s.lower())
        elif re.match(r"^[\w\-\.]+\.[A-Za-z]{2,}$", s):
            IOC["domain"].add(s.lower())
        elif s.startswith("/") or ":\\" in s:
            IOC["path"].add(s.lower())
        else:
            IOC["keyword"].add(s)
        n += 1
    return n


def ioc_match(text):
    """在文本中匹配 IOC，返回命中描述列表。"""
    if not text:
        return []
    hits = []
    low = text.lower()
    for ip in IOC["ip"]:
        if ip in text:
            hits.append("命中 IOC IP: %s" % ip)
    for d in IOC["domain"]:
        if d in low:
            hits.append("命中 IOC 域名: %s" % d)
    for k in IOC["keyword"]:
        if k.lower() in low:
            hits.append("命中 IOC 关键字: %s" % k)
    for ph in IOC["path"]:
        if ph in low:
            hits.append("命中 IOC 路径: %s" % ph)
    for h in IOC["hash"]:
        if h in low:
            hits.append("命中 IOC 哈希: %s" % h)
    return hits

# ============================================================ 基础框架

LEVEL_ORDER = ["严重", "高危", "中危", "低危", "提示"]
LEVEL_COLOR = {"严重": "#c0392b", "高危": "#e67e22", "中危": "#f1c40f",
               "低危": "#3498db", "提示": "#7f8c8d"}


def now_str():
    return time.strftime("%Y-%m-%d %H:%M:%S")


def decode_bytes(b):
    """子进程输出 → 文本（R16/P5：唯一解码机制，全部子进程文本解析只走这一处）。

    实测（2026-10-15，本机 ACP=UTF-8）：cmd/PowerShell/reg/schtasks 输出为 UTF-8，
    wevtutil /f:text 输出为 GBK——同一台机器的不同子进程编码并不一致。旧实现按“整段
    字节找到第一个能解开的编码就全段采用”，一旦一段输出里混入任一非法字节，就会整段
    回退 GBK，把其中的 UTF-8 中文按 GBK 解出「尘→灏榎」类乱码（R16 点名的现象）。
    新机制：按行独立判定——UTF-8 严格优先，失败回退 GBK 严格，再失败用 UTF-8+replace
    兜底（等价于显式 encoding="utf-8", errors="replace" 的确定性兜底，且不依赖 locale）；
    带 BOM 的 UTF-16/UTF-8 输入按 BOM 解码。行结构（\\n 与行内 \\r）原样保留。
    """
    if not b:
        return ""
    for bom, enc in ((b"\xff\xfe", "utf-16"), (b"\xfe\xff", "utf-16"),
                     (b"\xef\xbb\xbf", "utf-8-sig")):
        if b.startswith(bom):
            return b.decode(enc, "replace")
    parts = b.split(b"\n")
    out = []
    for i, ln in enumerate(parts):
        if i:
            out.append("\n")
        txt = ""
        for enc in ("utf-8", "gbk"):
            try:
                txt = ln.decode(enc)
                break
            except Exception:
                continue
        else:
            txt = ln.decode("utf-8", "replace")
        out.append(txt)
    return "".join(out)


# 命令输出中的环境噪声（会污染解析）：被植入 /etc/ld.so.preload 后，
# 系统每执行一条命令都会打印这种错误；必须过滤，否则会把噪声当成"发现"。
_NOISE_RES = [
    re.compile(r"(?i)^\s*(ERROR:\s*)?ld\.so:.*$"),
    re.compile(r"(?i)^.*cannot be preloaded.*$"),
    re.compile(r"(?i)^\s*bash:\s*(warning: setlocale|cannot set terminal process group|"
               r"no job control).*$"),
    re.compile(r"(?i)^.*Inappropriate ioctl for device.*$"),
    re.compile(r"(?i)^\s*WARNING:\s*Failed to add the host .*"),
]


def clean_output(text):
    """过滤环境噪声行（如 ld.so.preload 造成的加载告警），避免污染检测结果。"""
    if not text:
        return text
    out = []
    for ln in text.splitlines():
        if any(r.match(ln) for r in _NOISE_RES):
            continue
        out.append(ln)
    return "\n".join(out)


class CmdResult(tuple):
    """命令采集结果（R20/P3）：仍是长度 2 的元组（输出文本, 错误流），附加 rc 属性。

    既有的 `out, _ = win_cmd(...)` / `out, err = sh(...)` 解包逐字继续成立；新代码用
    `res.rc` 拿退出码（命令失败判定统一走 cmd_failure，见下）。tuple.__new__ 保证不可变。
    """

    def __new__(cls, out="", err="", rc=0):
        self = tuple.__new__(cls, (out, err))
        try:
            self.rc = int(rc)
        except Exception:
            self.rc = -1
        return self


# R20/P3：命令失败判定表（单一入口 cmd_failure 的唯一依据表）。
# 判据只看「退出码 + 错误流（stderr）」——stdout 里的中文错误词一律不作为失败依据
# （实测缺陷：wevtutil 的 xml 输出里 1 条事件数据含「拒绝访问」，曾把整个通道误判失败）。
# 扩展方式：向本表追加 (类别, 匹配正则, 中文原因文案) 一行即可，调用点无需改动。
_R20_CMD_FAIL_TABLE = (
    ("denied", r"(拒绝访问|access is denied|access denied|系统错误\s*5\b|system error\s*5\b|"
               r"permissionerror|权限不足|需要管理员|requires elevation|run as administrator)",
     "权限不足（拒绝访问，需要管理员权限）"),
    ("missing", r"(找不到|不存在|could not be found|does not exist|unable to find|cannot find|"
                r"no such file|not recognized)", "目标不存在（键/值/通道/文件缺失）"),
    ("timeout", r"(超时|timed out|timeout|执行超时)", "命令超时"),
    ("generic", None, "命令失败"),
)


def cmd_failure(out="", err="", rc=0, what=""):
    """R20/P3 单一「命令失败判定」入口：只看退出码与错误流，不看 stdout 内容。

    返回 None（rc=0，命令成功）或 dict(kind/text/rc/raw/what)（失败原因）。
    - rc != 0 才算失败；rc=0 时即使输出里出现「拒绝访问」等中文错误词也判成功；
    - 失败原因按 _R20_CMD_FAIL_TABLE 对错误流（stderr）分类；
    - 全库同类子串判据（R19 独立验收点名的 9 处）均已收敛到本函数。
    """
    try:
        rc_i = int(rc)
    except Exception:
        rc_i = -1
    if rc_i == 0:
        return None
    blob = (err or "").strip()
    for kind, pat, text in _R20_CMD_FAIL_TABLE:
        if pat and blob and re.search(pat, blob, re.I):
            return {"kind": kind, "text": text, "rc": rc_i, "raw": blob[:200], "what": what}
    return {"kind": "generic", "text": ("命令失败（%s，退出码 %s）"
                                        % (what or "命令", rc_i)),
            "rc": rc_i, "raw": blob[:200], "what": what}


def run_cmd(args, timeout=90, shell=False):
    """执行命令，返回 CmdResult(输出文本, 错误流, rc)。

    只用于只读的信息收集命令；任何异常都吞掉并返回错误串，避免中断排查。
    R20/P3：stderr 与 stdout 分开采集、退出码随结果返回（失败判定统一走 cmd_failure）。
    """
    if isinstance(args, str):
        shell = True
    try:
        kwargs = {}
        if IS_WIN and not shell:
            try:
                kwargs["creationflags"] = 0x08000000  # CREATE_NO_WINDOW
            except Exception as _e_r19:
                _degrade("run_cmd", _e_r19)
        p = subprocess.Popen(args, shell=shell, stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE, **kwargs)
        try:
            out, err = p.communicate(timeout=timeout)
            rc = p.returncode if p.returncode is not None else -1
        except Exception:
            try:
                p.kill()
            except Exception as _e_r19:
                _degrade("run_cmd", _e_r19)
            return CmdResult("", "执行超时或被拒绝: %s" % (args if shell else " ".join(args)), -1)
        return CmdResult(clean_output(decode_bytes(out or b"")),
                         decode_bytes(err or b""), rc)
    except Exception as e:
        return CmdResult("", "执行失败: %s (%s)" % (args if shell else " ".join(args), e), -1)


def is_private_ip(ip):
    try:
        parts = [int(x) for x in ip.split(".")]
        if len(parts) != 4:
            return True
        if parts[0] in (10, 127) or (parts[0] == 172 and 16 <= parts[1] <= 31) \
                or (parts[0] == 192 and parts[1] == 168) or parts[0] == 0 \
                or parts[0] >= 224:
            return True
    except Exception:
        return True
    return False


def human_time(ts):
    try:
        return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ts))
    except Exception:
        return str(ts)


def file_mtime(path):
    try:
        return os.path.getmtime(path)
    except Exception:
        return 0


def recent_file(path, days):
    mt = file_mtime(path)
    return mt > 0 and (time.time() - mt) <= days * 86400


def safe_read(path, limit=MAX_READ, binary=False):
    """安全读取文件；失败返回 None。"""
    try:
        if os.path.getsize(path) > limit and not binary:
            with open(path, "rb") as f:
                b = f.read(limit)
            return decode_bytes(b)
        mode = "rb" if binary else "r"
        if binary:
            with open(path, "rb") as f:
                return f.read(limit)
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            return f.read(limit)
    except Exception:
        return None


def write_text(path, text):
    d = os.path.dirname(path)
    if d and not os.path.isdir(d):
        os.makedirs(d)
    with open(path, "w", encoding="utf-8", errors="replace") as f:
        f.write(text)


def match_rules(text, rules):
    """返回命中的规则描述列表。"""
    hits = []
    for pat, desc in rules:
        try:
            if re.search(pat, text, re.I):
                hits.append(desc)
        except Exception:
            continue
    return hits


# 用于 cron / systemd / rc.local / profile.d / motd / autostart 等“配置文件内容”的高置信特征：
# 这些位置出现“下载后直接执行、反弹 shell、混淆载荷、写公钥、关记录”才算危险。
# 单纯出现 curl/wget/run-parts 等普通运维写法（如 Ubuntu 的 50-motd-news）不算。
CONFIG_DANGER_PATTERNS = [
    (r"(?i)(curl|wget|fetch)\s+[^|;&\n]*\|\s*(ba|z|da|k)?sh\b", "下载内容直接管道执行（curl|bash）"),
    (r"(?i)(bash|sh)\s+-c\s*['\"][^'\"]*(curl|wget|/dev/tcp)", "经 shell 执行下载/反弹命令"),
    (r"/dev/tcp/|bash\s+-i\s*>&|nc\s+-e|ncat\s+-e|socat\s+exec|mkfifo\s+/tmp", "反弹 shell"),
    (r"(?i)(base64\s+-d|base64\s+--decode|openssl\s+enc\s+-d)[^|;&\n]*\|", "解码后管道执行"),
    (r"(?i)(python|perl|php|ruby)[0-9.]*\s+-[ec]\s+[^'\"]*(socket|system\(|exec\(|/dev/tcp)",
     "脚本解释器执行内存载荷"),
    (r"(?i)chmod\s+\+?[0-7]?[0-7][0-7]\s+/(tmp|var/tmp|dev/shm)|chattr\s+[+-]i\s+/(tmp|var/tmp)",
     "临时目录文件赋权/加锁"),
    (r"(?i)ld\.so\.preload|LD_PRELOAD\s*=", "动态链接劫持（LD_PRELOAD）"),
    (r"(?i)HISTFILE=/dev/null|HISTSIZE=0|history\s+-c|set\s+\+o\s+history", "关闭/清理命令记录"),
    (r"(?i)(useradd\s+-[^|;&\n]*-p|chpasswd|echo\s+\S+\s*\|\s*passwd)", "静默新增账号/改密"),
    (r"(?i)ssh-keygen|authorized_keys", "写入 SSH 公钥免密登录"),
    (r"(?i)(wget|curl)\s+[^|;&\n]*-[Oo]\s+/?(tmp|var/tmp|dev/shm|root|home)/", "下载载荷写入敏感目录"),
    (r"@(reboot|daily|hourly)\s+\d+.*(bash|sh)\s+-c", "anacron 内联执行命令"),
    (r"(?i)(systemctl\s+(enable|start)\s+\S*(miner|xmr|kdevtmpfsi))|stratum\+tcp|pool\.",
     "服务化挖矿/矿池连接"),
]


def config_hits(text):
    """配置文件内容检测：只返回高置信危险特征。"""
    return match_rules(text, CONFIG_DANGER_PATTERNS)


# ============================================================ R18：严重级通用闸门（P2）
# 依据：R18 需求书 P2——真机 `win --days 1` 报告的唯一条「严重」是防火墙 2033 的稳定误报
#   （事件自带 ModifyingUser=NT AUTHORITY\LOCAL SERVICE + svchost.exe 已自证系统行为，当前
#   规则集仍存在）——根因是「结论与证据的关系没定死」：单条事件就能下严重。
# 机制层通用闸门（不是对某个样例写特例）：任何「严重」级结论必须随附 ≥2 条相互独立证据
#   来源（判定口径 = 去重后的来源名个数；例如 事件+现状交叉验证 / 事件+规模字段 / 两个不同
#   来源），由本闸门统一收口：
#     · 来源 ≥2 ⇒ 保留「严重」，并把所用交叉验证来源与结果写进结论明细；
#     · 来源 <2 ⇒ 自动降级为「高危」并在明细写明原因（单条证据不足以定严重）；
#     · 未经 add_verified() 申明的裸「严重」结论，由 _r18_sev_gate_sweep() 在报告收口时降级。
#   来源清单可扩展：调用点按 (来源名, 结果) 元组申明；判定只看来源名去重计数，不对任何
#   事件 ID / 进程名 / 账号名等具体字符串写分支，扩展时只需在调用点补充新的来源元组。
_R18_SEV_MIN_EVIDENCE = 2
_R18_SEV_KEEP_MARK = "R18"          # add_verified 已闸门标记（sweep 据此跳过）
_R18_SEV_SWEEP_MARK = "R18-sweep"   # sweep 降级标记（幂等：不会二次降级）
_R18_SEV_KEEP_NOTE = "\n【R18 严重级闸门】独立证据 %d 条（≥2）：%s ⇒ 保留「严重」。"
_R18_SEV_DOWN_NOTE = ("\n【R18 严重级闸门】独立证据 %s（<2）⇒ 由「严重」降级为「高危」；"
                      "补足 ≥2 条相互独立证据（如 事件+现状交叉验证 / 两个不同来源）后可恢复。")
_R18_SEV_SWEEP_NOTE = ("\n【R18 严重级闸门】本结论未经 add_verified() 申明交叉验证来源，"
                       "按机制层规则自动降级为「高危」（单条证据不得定严重）。")


def _r18_sev_source_norm(sources):
    """证据来源归一（R18/P2，纯函数）：[(来源名, 结果)] / [{"source":…,"result":…}] → 去重清单。

    去重键 = 来源名（去空白、大小写不敏感）；同一来源名的多个结果合并展示；非法项忽略。
    返回 [(来源名, 合并结果)]，保持首次出现顺序。
    """
    out = {}
    for s in (sources or ()):
        name, result = "", ""
        if isinstance(s, dict):
            name = str(s.get("source") or s.get("name") or "").strip()
            result = str(s.get("result") or s.get("detail") or "").strip()
        elif isinstance(s, (tuple, list)) and len(s) >= 2:
            name = str(s[0] or "").strip()
            result = str(s[1] or "").strip()
        elif isinstance(s, str):
            name = s.strip()
        if not name:
            continue
        key = name.lower()
        if key in out:
            if result and result not in out[key][1]:
                out[key][1] = (out[key][1] + "；" + result) if out[key][1] else result
        else:
            out[key] = [name, result]
    return [(v[0], v[1]) for v in out.values()]


def _r18_sev_gate_decide(level, detail, sources):
    """通用严重级闸门判定（R18/P2，纯函数）：返回 (最终级别, 新明细, 闸门标记)。

    非「严重」级别原样返回（不附加任何文本）；「严重」级别按独立证据来源计数：
    ≥ _R18_SEV_MIN_EVIDENCE 条 ⇒ 保留并把来源与结果写进明细；否则降级「高危」。
    """
    if level != "严重":
        return level, detail, ""
    norm = _r18_sev_source_norm(sources)
    body = "；".join("%d) %s：%s" % (i + 1, n, r or "（未写结果）")
                     for i, (n, r) in enumerate(norm))
    if len(norm) >= _R18_SEV_MIN_EVIDENCE:
        return "严重", (detail or "") + _R18_SEV_KEEP_NOTE % (len(norm), body), _R18_SEV_KEEP_MARK
    down_txt = "%d 条（%s）" % (len(norm), body) if norm else "0 条（未声明任何交叉验证来源）"
    return "高危", (detail or "") + _R18_SEV_DOWN_NOTE % down_txt, _R18_SEV_KEEP_MARK


def _r18_sev_gate_sweep(c):
    """报告收口（R18/P2）：把未经闸门申明的裸「严重」结论统一降级为「高危」。

    返回 (降级条数, 已闸门保留条数)。只改级别与明细文本，不删除结论、不改类别与证据；
    降级后在报告里追加一条「提示」说明条数，保证「悄悄少结论」不会发生（只是降级）。
    """
    downgraded, kept = 0, 0
    for f in c.all_findings():
        if getattr(f, "level", "") != "严重":
            continue
        if getattr(f, "gate", ""):
            kept += 1
            continue
        f.level = "高危"
        f.detail = (f.detail or "") + _R18_SEV_SWEEP_NOTE
        try:
            f.gate = _R18_SEV_SWEEP_MARK
        except Exception as _e_r19:
            _degrade("_r18_sev_gate_sweep", _e_r19)
        downgraded += 1
    if downgraded:
        c.add("提示", "严重级闸门",
              "R18 严重级闸门：%d 条未申明双独立证据的「严重」结论已降级为「高危」"
              "（逐条明细已注明；已通过闸门保留的「严重」结论 %d 条）" % (downgraded, kept))
    return downgraded, kept


class Finding(object):
    __slots__ = ("level", "category", "title", "detail", "evidence", "advice", "attck", "gate")

    def __init__(self, level, category, title, detail="", evidence=None, advice="", attck=""):
        self.level = level
        self.category = category
        self.title = title
        self.detail = detail
        self.evidence = evidence or []
        self.advice = advice
        self.attck = attck or ""        # R10 增量：可选 ATT&CK 编号（如 T1053.005）；默认空，既有调用不受影响
        self.gate = ""                  # R18 增量：严重级闸门标记（"R18"=已闸门；不进行 to_dict 输出）

    def to_dict(self):
        return {"level": self.level, "category": self.category, "title": self.title,
                "detail": self.detail, "evidence": self.evidence, "advice": self.advice,
                "attck": self.attck}


class Collector(object):
    """收集检测结论与原始证据。

    events: 可选回调 events(kind, data)，供 Web UI 实时推送进度与内容（CLI 下为 None）。
    R15/B4（为 R16 线程池铺路）：findings/raw/warnings/计数器的写入一律走实例锁，
    add/hit/raw_add/warn/count_up 可从多线程安全调用且不丢结论、不重复；
    单线程下行为与输出顺序逐字不变（先入表再 emit，与既有顺序一致）。
    """

    def __init__(self, root=None, days=DEFAULT_DAYS):
        self.findings = []
        self.raw = []          # [(标题, 命令/来源, 输出文本)]
        self.info = {}         # 环境基本信息
        self.root = root or ""
        self.days = days
        self.warnings = []     # 因权限等原因未完成的检查
        self.events = None     # SSE/进度回调
        self._stop = None      # 中止判断（Web UI 用）
        self._lock = threading.RLock()   # R15/B4：写入闸门（可重入；add ← hit 属嵌套调用）
        self.counters = {}     # R15/B4：线程安全实例计数器（不入报告，供 R16 并行步骤汇总）
        # R16 增量（只做加法）：持久化归因素材 / 事件取数统计与预算 / 通道与日志源探测结果
        self.persist_items = []    # [(kind,name,target,…)] 供「持久化归因」与创建事件对齐
        self._persist_keys = set()  # 去重键（kind,name,target 前 120 字符）
        self.evt_stats = []        # 每次 _evt_fetch 的取数统计（通道/上限/实取/截断/覆盖）
        self.evt_cache = {}        # 同参事件查询一轮内复用（Web UI 多任务时按任务重建 Collector）
        self.channel_probe = []    # 开跑通道探测结果（不存在/已禁用/无权限读取）
        self.src_probe = []        # 日志源/命令可用性（wevtutil/schtasks/reg/powershell 等）
        # R18 增量（只做加法）：档位跳面记录 / 各步骤耗时（P3 交付实测用，不入 findings.json 主体）
        self.r18_skipped_steps = []   # --fast 档跳过的检查面名（报告顶部与 coverage 据此声明）
        self.step_times = []          # [(步骤名, 秒, 是否跳过)]（报告 coverage 声明瓶颈步骤）
        # R19 增量（只做加法）：降级记录（P2）——原 `except …: pass` 的每一处都登记到这里，
        # 覆盖度段显式列出；degrade_total 为计数器（超 _R19_DEG_MAX 后只计数不加明细）。
        self.degrade_records = []
        self.degrade_total = [0]
        # R21 增量（只做加法）：一键深挖档状态（--deep）——档位声明用；单点模式不置位
        self.r21_deep = None          # None=非一键；True/False=本次一键是否为深挖档
        self.r21_platform = ""        # 一键平台（win/linux，声明文案用）
        self.r21_dossier = None       # {"max": 画像目标数上限, "n": 实际展开数}（win 一键画像步骤写）

    # ------------------------------------------------ 事件推送
    def emit(self, kind, **data):
        """推送一条事件（无状态、不持锁，保证 emit 与写入不互相阻塞）。"""
        if self.events is None:
            return
        try:
            self.events(kind, data)
        except Exception as _e_r19:
            _degrade("emit", _e_r19)

    def set_stop_check(self, fn):
        self._stop = fn

    def stopped(self):
        try:
            return bool(self._stop and self._stop())
        except Exception:
            return False

    def stage(self, name, index, total):
        """报告当前检查阶段（用于进度条）。"""
        self.emit("stage", name=name, index=index, total=total)

    # ------------------------------------------------ 线程安全写入（R15/B4）
    def count_up(self, key, n=1):
        """实例级计数器自增：锁保护，返回自增后的值。"""
        with self._lock:
            cur = int(self.counters.get(key) or 0) + int(n)
            self.counters[key] = cur
            return cur

    def count_of(self, key):
        """读回实例级计数器（锁保护）。"""
        with self._lock:
            return int(self.counters.get(key) or 0)

    # ------------------------------------------------ R16 增量接口（只做加法）
    def persist_add(self, kind, name, target="", ts=0, src="", reg="", extra=""):
        """登记一条“本次发现的持久化”素材，供「持久化归因」与创建事件对齐（P1）。

        kind：持久化种类（计划任务/服务/Run 键/启动文件夹/WMI 永久事件订阅/BITS/
        COM 劫持/AppInit_DLLs/IFEO/Winlogon/LSA 包/屏保/GPO 脚本/Active Setup/
        PowerShell Profile/Office 加载项…）；name/target：用于与创建事件按名/路径匹配；
        ts：自身可得的文件时间等锚点（epoch，可选）；reg：注册表路径（可选，Sysmon 12/13/14 匹配用）。
        写入走实例锁并做同键去重；不影响任何既有接口。
        """
        item = {"kind": kind or "持久化", "name": (name or "").strip(),
                "target": (target or "").strip(), "ts": int(ts or 0),
                "src": src or "", "reg": (reg or "").strip(), "extra": extra or ""}
        if not (item["name"] or item["target"]):
            return
        key = (item["kind"], item["name"], item["target"][:120])
        with self._lock:
            if key in self._persist_keys:
                return
            self._persist_keys.add(key)
            self.persist_items.append(item)
        self.emit("persist", item=dict(item))   # 事件名与载荷分离：避免 kind 参数与 emit(kind=…) 冲突

    def evt_stat_add(self, st):
        """记录一次事件取数统计（R16/P3：通道、上限、实取、截断、覆盖窗口），锁保护。"""
        with self._lock:
            self.evt_stats.append(dict(st or {}))

    def evt_budget(self, channel, want):
        """通道级每轮取数预算（R16/P3：每通道每轮 ≤ EVT_CHAN_ROUND_CAP[channel]）。

        返回本轮可用的条数（0=预算已用尽）；多线程安全，实际取数少于授予时用
        evt_budget_refund() 退还差额。
        """
        caps = globals().get("EVT_CHAN_ROUND_CAP") or {}
        cap = int(caps.get(channel, caps.get("default", 12000)))
        with self._lock:
            used = int(self.counters.get("evt_used:" + channel) or 0)
            grant = max(0, min(int(want or 0), cap - used))
            self.counters["evt_used:" + channel] = used + grant
            return grant

    def evt_budget_refund(self, channel, n):
        """退还通道预算差额（授予 N 条、实际只取了 M 条时退还 N-M）。锁保护。"""
        n = int(n or 0)
        if n <= 0:
            return
        with self._lock:
            used = int(self.counters.get("evt_used:" + channel) or 0)
            self.counters["evt_used:" + channel] = max(0, used - n)

    def add(self, level, category, title, detail="", evidence=None, advice="", gate=""):
        """记录一条检测结论（R18 增量：可选 gate 参数为严重级闸门标记，既有调用不受影响）。"""
        if level not in LEVEL_ORDER:
            level = "提示"
        f = Finding(level, category, title, detail, evidence, advice)
        f.gate = gate or ""
        with self._lock:
            self.findings.append(f)
        self.emit("finding", **f.to_dict())

    # -------------------------------------------------- R18/P2 严重级闸门入口
    def add_verified(self, level, category, title, detail="", evidence=None, advice="", sources=None):
        """R18/P2 通用严重级闸门入口：可能为「严重」的结论统一从这里上报。

        level=「严重」时必须随附 ≥2 条相互独立证据来源（sources=[(来源名, 结果), …] /
        等价的 dict 列表）；不足则由 _r18_sev_gate_decide 自动降级为「高危」，并把所用
        来源与结果写进结论明细；非严重级别原样透传（不改文本、不加标记）。
        """
        lvl, detail2, gate = _r18_sev_gate_decide(level, detail, sources)
        self.add(lvl, category, title, detail=detail2, evidence=evidence, advice=advice, gate=gate)

    # -------------------------------------------------- 公开接口（R6 增量）
    def hit(self, level, category, title, detail="", evidence=None, advice=""):
        """公开接口（R6 增量）：记录一条检测结论，等价于 add()。

        新增检查面统一走 hit()/warn()/raw_add()/all_findings()；
        add() 保留原样不改，保证既有调用方与 test.md §0.7 口径完全兼容。
        """
        self.add(level, category, title, detail=detail, evidence=evidence, advice=advice)

    def all_findings(self):
        """公开接口（R6 增量）：返回已收集结论的浅拷贝列表，供跨面去重等只读消费。"""
        with self._lock:
            return list(self.findings)

    def raw_add(self, title, source, output):
        if output is None:
            output = "(无输出)"
        if isinstance(output, list):
            output = "\n".join(output)
        with self._lock:
            self.raw.append((title, source, output))
        self.emit("log", title=title, source=source, output=output)

    def warn(self, msg):
        with self._lock:
            self.warnings.append(msg)
        self.emit("warn", msg=msg)

    def count(self, level):
        with self._lock:
            return len([f for f in self.findings if f.level == level])

    def sorted_findings(self):
        with self._lock:
            return sorted(self.findings, key=lambda f: LEVEL_ORDER.index(f.level))

    # -------------------------------------------------- 通用结论封装
    def conclude_scan(self, category, matched, label, advice="", level="高危"):
        """命中即报，未命中报提示。"""
        if matched:
            self.add(level, category, "发现%d个可疑%s" % (len(matched), label),
                     detail="; ".join(matched[:10]), evidence=matched[:200], advice=advice)
        else:
            self.add("提示", category, "未发现可疑%s" % label)


# ============================================================ 命令封装（跨平台）

def sh(cmd, timeout=90):
    return run_cmd(cmd, timeout=timeout, shell=True)


def win_cmd(args, timeout=90):
    return run_cmd(args, timeout=timeout)

# ============================================================ Windows 主机排查
# 依据：第01章 第1篇 Windows 入侵排查 / 第03章 第1、2篇 隐藏篇、后门篇

def parse_csv_table(text):
    """解析 wmic /format:csv 或 PowerShell ConvertTo-Csv 输出为 dict 列表。"""
    rows = []
    if not text:
        return rows
    lines = [ln for ln in text.splitlines() if ln.strip()]
    if not lines:
        return rows
    header = [h.strip() for h in next(csv.reader([lines[0]]))]
    if header and header[0].lower() == "node":
        header = header[1:]
    for ln in lines[1:]:
        try:
            vals = next(csv.reader([ln]))
        except Exception:
            continue
        if header and len(vals) == len(header) + 1:
            vals = vals[1:]
        if len(vals) != len(header):
            continue
        rows.append(dict(zip(header, [v.strip() for v in vals])))
    return rows


def ps_csv(expr, timeout=120):
    """调用 PowerShell 输出 CSV 并解析（wmic 在新系统已移除时的后备）。"""
    out, err = win_cmd(["powershell", "-NoProfile", "-NonInteractive",
                        "-ExecutionPolicy", "Bypass", "-Command", expr], timeout=timeout)
    if err and not out:
        return [], err
    return parse_csv_table(out), out


def wmic_csv(query, timeout=120):
    out, err = win_cmd(["wmic"] + query.split() + ["/format:csv"], timeout=timeout)
    rows = parse_csv_table(out)
    if not rows:
        return [], out or err
    return rows, out


# 命令行“强特征”：单独命中即可判高危；其余为需人工确认的弱特征
STRONG_CMD_KEYS = ("编码命令", "远程下载", "Base64 解码执行", "Base64 解码", "bash 反弹",
                   "反弹 shell 工具", "UNC 路径", "从临时目录执行", "伪装文件",
                   # R23/P5.1：新增 LOLBin 规则单独判强（不触碰既有「LOLBin 白利用执行」的强弱口径）
                   "IEExec", "MSXSL", "pubprn")


def cmdline_hits(text):
    """返回 (全部命中, 强特征命中, 弱特征命中)。"""
    hits = match_rules(text, SUSPICIOUS_CMDLINE_PATTERNS)
    strong = [h for h in hits if any(k in h for k in STRONG_CMD_KEYS)]
    weak = [h for h in hits if h not in strong]
    return hits, strong, weak


def is_system_exe_path(cmd):
    """判断命令行是否为系统目录下的可执行文件（用于降低 rundll32/svchost 误报）。"""
    low = (cmd or "").strip().lower()
    return bool(re.match(r'"?(%windir%|%systemroot%|c:\\windows)\\(system32|syswow64)\\\S+', low)) \
        or low.startswith("\\systemroot\\system32") or low.startswith("%windir%\\system32")


def win_env_info(c):
    cat = "系统信息"
    info = {}
    info["主机名"] = socket.gethostname()
    info["系统版本"] = "%s %s (build %s)" % (platform.system(), platform.release(), platform.version())
    info["架构"] = platform.machine()
    info["当前时间"] = now_str()
    info["Python"] = platform.python_version()
    out, _ = win_cmd(["systeminfo"])
    if out:
        for key in ("OS 名称", "OS 版本", "系统启动时间", "System Boot Time", "OS Name", "OS Version",
                    "初始安装日期", "Original Install Date"):
            for ln in out.splitlines():
                if ln.lower().startswith(key.lower()):
                    info[ln.split(":", 1)[0].strip()] = ln.split(":", 1)[1].strip()
                    break
        boot = ""
        for ln in out.splitlines():
            if "启动时间" in ln or "Boot Time" in ln:
                boot = ln.split(":", 1)[-1].strip()
        info["系统启动时间"] = boot
        c.raw_add("systeminfo", "systeminfo", out)
    else:
        c.warn("未能执行 systeminfo（权限或环境限制）")
    # 补丁缺失/默认共享/远程端口暴露
    c.add("提示", cat, "系统基础信息",
          detail="; ".join("%s=%s" % (k, v) for k, v in info.items()))
    netstat_sum, _ = win_cmd(["netstat", "-ano"])
    exposed = []
    for ln in netstat_sum.splitlines():
        m = re.search(r"TCP\s+(0\.0\.0\.0|\[::\]):(\d+)\s+\S+\s+LISTENING", ln)
        if m and m.group(2) in ("3389", "445", "139", "135", "22", "5900", "21", "23", "1433", "3306"):
            exposed.append("端口 %s 对外开放监听 (%s)" % (m.group(2), m.group(1)))
    if exposed:
        c.add("中危", cat, "对外监听的高风险管理端口",
              detail="; ".join(sorted(set(exposed))),
              advice="确认这些端口是否必须对公网开放；3389/445/3306 等暴露是暴力破解与横向移动的主要入口。")
    c.info.update(info)


def win_accounts(c):
    cat = "账号安全"
    net_user, _ = win_cmd(["net", "user"])
    c.raw_add("本机账号列表(net user)", "net user", net_user)
    names_net = []
    if net_user:
        grab = False
        for ln in net_user.splitlines():
            if ln.startswith("---"):
                grab = True
                continue
            if grab:
                if not ln.strip():
                    break
                names_net.extend(ln.split())
    # 过滤命令回显等非账号内容
    names_net = [n for n in names_net
                 if not re.search(r"命令成功完成|命令已完成|The command completed|^---", n)
                 and re.match(r"^[A-Za-z0-9_\-\.\$\u4e00-\u9fff]+$", n)]
    rows, raw = wmic_csv("useraccount get Name,SID,Disabled,PasswordRequired,PasswordExpires")
    if not rows:
        rows, raw = ps_csv("Get-LocalUser | Select-Object Name,Enabled,SID | ConvertTo-Csv -NoTypeInformation")
    c.raw_add("本地账户明细", "wmic useraccount / Get-LocalUser", raw)
    names = [r.get("Name", "") for r in rows if r.get("Name")]

    # 1) 隐藏账号：以 $ 结尾；net user 与 WMI 列表不一致
    hidden = [n for n in names if HIDDEN_ACCOUNT_HINT.search(n)]
    if hidden:
        c.add("高危", cat, "存在 $ 结尾的隐藏账号",
              detail="账号: %s（net user 命令默认不显示，删除时需加 $，例如 net user test$ /del）" % ", ".join(hidden),
              evidence=hidden, advice="确认是否为业务需要；非业务账号立即禁用: net user <名> /active:no 后 net user <名> /del。")
    if names_net and names:
        only_net = set(n.lower() for n in names_net) - set(n.lower() for n in names)
        if only_net:
            c.add("中危", cat, "账号列表存在差异（可能存在克隆/隐藏账号）",
                  detail="net user 可见但 WMI 未列出的账号: %s" % ", ".join(sorted(only_net)),
                  advice="结合注册表 HKLM\\SAM\\SAM\\Domains\\Account\\Users\\Names 与 D盾等工具核对克隆账号。")
        else:
            c.add("提示", cat, "账号列表一致性校验通过（net user 与 WMI 一致）")

    # 2) 管理员组成员
    admins, raw2 = win_cmd(["net", "localgroup", "administrators"])
    c.raw_add("管理员组成员", "net localgroup administrators", admins)
    members = []
    if admins:
        started = False
        for ln in admins.splitlines():
            if ln.startswith("---"):
                started = True
                continue
            if started:
                if not ln.strip():
                    break
                nm = ln.strip().lstrip("*").strip()
                if re.search(r"命令成功完成|命令已完成|The command completed", nm):
                    continue
                members.append(nm)
    if members:
        c.add("提示", cat, "管理员组成员（请人工核对是否有多余账号）",
              detail="; ".join(members), evidence=members)

    # 3) 空密码 / 密码永不过期（弱口令与后门账号特征）
    weak = []
    for r in rows:
        nm = r.get("Name", "")
        disabled = (r.get("Disabled", "") or "").strip().lower()
        if disabled in ("true", "yes", "1"):
            continue
        if (r.get("PasswordRequired", "") or "").strip().lower() in ("false", "no", "0"):
            weak.append("%s: 允许空密码 (PasswordRequired=False)" % nm)
        if (r.get("PasswordExpires", "") or "").strip().lower() in ("false", "no", "0"):
            weak.append("%s: 密码永不过期" % nm)
    if weak:
        c.add("中危", cat, "账号存在弱策略（空密码/密码永不过期）",
              detail="; ".join(weak[:20]), evidence=weak[:50],
              advice="对可疑账号执行 net user <名> /active:no 禁用；排查是否被用于持久化。")

    # 4) 克隆账号：SAM 中 Names 项与 Users 项数量比对（需管理员权限）
    sam, err = win_cmd(["reg", "query", r"HKLM\SAM\SAM\Domains\Account\Users\Names"])
    if sam and "拒绝访问" not in sam and "Access is denied" not in sam:
        n_names = len([l for l in sam.splitlines() if l.strip().startswith("HKEY_")])
        c.raw_add("SAM Names 键（需管理员）", "reg query HKLM\\SAM\\SAM\\Domains\\Account\\Users\\Names", sam)
        if n_names:
            c.add("提示", cat, "SAM 账号键数量=%d（与上方账号列表比对，多出的即为隐藏/克隆账号）" % n_names)
    else:
        c.warn("读取 SAM 失败（需以管理员权限运行才能检测克隆账号）")


def win_autoruns(c):
    cat = "启动项"
    keys = [
        (r"HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Run", "HKLM Run"),
        (r"HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce", "HKLM RunOnce"),
        (r"HKCU\SOFTWARE\Microsoft\Windows\CurrentVersion\Run", "HKCU Run"),
        (r"HKCU\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce", "HKCU RunOnce"),
        (r"HKLM\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Run", "HKLM Wow6432Node Run"),
        (r"HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run", "HKLN Policies Run"),
    ]
    entries = []
    for key, label in keys:
        out, _ = win_cmd(["reg", "query", key])
        if out:
            c.raw_add("启动项 %s" % label, "reg query " + key, out)
            for ln in out.splitlines():
                m = re.match(r"\s{4}(\S+)\s+REG_\w+\s+(.*)", ln)
                if m:
                    entries.append(("%s\\%s" % (label, m.group(1)), m.group(2), key))
    # Winlogon / Logon Script / AppInit / IFEO
    specials = [
        (r"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon", "Userinit", "Winlogon Userinit"),
        (r"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon", "Shell", "Winlogon Shell"),
        (r"HKCU\Environment", "UserInitMprLogonScript", "Logon Script(用户登录脚本)"),
        (r"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows", "AppInit_DLLs", "AppInit_DLLs"),
    ]
    for key, val, label in specials:
        out, _ = win_cmd(["reg", "query", key, "/v", val])
        if out and val in out:
            c.raw_add("特殊启动项 %s" % label, "reg query %s /v %s" % (key, val), out)
            m = re.search(r"REG_\w+\s+(.*)", out)
            if m:
                value = m.group(1).strip()
                entries.append((label, value, key))
                if label == "AppInit_DLLs" and value:
                    c.persist_add("AppInit_DLLs", "AppInit_DLLs", value, reg=key)

    # IFEO 劫持（Debugger）
    ifeo_key = r"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options"
    out, _ = win_cmd(["reg", "query", ifeo_key, "/s"], timeout=120)
    if out:
        cur = ""
        for ln in out.splitlines():
            if ln.strip().startswith("HKEY_"):
                cur = ln.strip()
            if "Debugger" in ln and "REG_" in ln:
                entries.append(("IFEO Debugger 劫持", ln.strip(), cur or ifeo_key))
                c.persist_add("IFEO 劫持", cur or ifeo_key, ln.strip(), reg=cur or ifeo_key)
                c.add("高危", cat, "存在 IFEO 映像劫持（Image File Execution Options\\Debugger）",
                      detail="%s -> %s" % (cur, ln.strip()),
                      advice="删除该 Debugger 键值并清理指向的程序（常见于粘滞键后门、杀软劫持）。")
    # ExcludeFromKnownDlls（LPK.dll 劫持前置条件）
    out, _ = win_cmd(["reg", "query",
                      r"HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\ExcludeFromKnownDlls"])
    if out and "REG_MULTI_SZ" in out:
        if not re.search(r"REG_MULTI_SZ\s*$", out, re.M):
            c.add("中危", cat, "ExcludeFromKnownDlls 中存在项（DLL 劫持前提）",
                  detail=out.strip()[-500:], advice="确认是否为业务需要，清理后可阻断 lpk.dll 等劫持。")

    # 启动文件夹
    startup_dirs = [os.path.join(os.environ.get("APPDATA", ""),
                                 r"Microsoft\Windows\Start Menu\Programs\Startup"),
                    os.path.join(os.environ.get("ProgramData", ""),
                                 r"Microsoft\Windows\Start Menu\Programs\Startup")]
    for d in startup_dirs:
        if d and os.path.isdir(d):
            files = [f for f in os.listdir(d) if f.lower() != "desktop.ini"]
            if files:
                c.add("中危", cat, "启动文件夹存在文件（默认应为空）",
                      detail="%s: %s" % (d, ", ".join(files)), evidence=files,
                      advice="核对文件来源，非业务文件删除并杀毒。")
                for f in files:
                    c.persist_add("启动文件夹", f, os.path.join(d, f))

    # 启动项内容判定（强特征=高危；弱特征/非标准目录=中危待人工确认）
    bad, weaks, odd = [], [], []
    for label, cmd, reg in entries:
        hits, strong, weak = cmdline_hits(cmd)
        if strong:
            bad.append("%s => %s  [强特征: %s]" % (label, cmd[:200], "/".join(strong)))
            c.persist_add("注册表启动项", label, cmd, reg=reg)
            continue
        p = re.match(r'^\s*"?([A-Za-z]:\\[^"]+?\.\w+)', cmd or "")
        if p and HIGH_RISK_DIR_RE.search(p.group(1)):
            bad.append("%s => 从临时/公共目录启动: %s" % (label, cmd[:200]))
            c.persist_add("注册表启动项", label, cmd, reg=reg)
            continue
        if p and not any(d in p.group(1).lower() for d in SIGNED_DIRS_WIN):
            odd.append("%s => 非标准安装目录: %s" % (label, cmd[:180]))
            c.persist_add("注册表启动项", label, cmd, reg=reg)
        if weak:
            weaks.append("%s => %s [需人工确认: %s]" % (label, cmd[:200], "/".join(weak)))
            c.persist_add("注册表启动项", label, cmd, reg=reg)
    if bad:
        c.add("高危", cat, "启动项中存在可疑命令", detail="\n".join(bad[:20]), evidence=bad,
              advice="逐条核对：reg delete 删除键值 / 删除对应文件 / 用 Autoruns 比对微软签名。")
    if weaks or odd:
        c.add("中危", cat, "启动项中存在需人工确认的条目",
              detail="\n".join((weaks + odd)[:25]), evidence=weaks + odd,
              advice="确认是否为业务软件自身行为（签名、厂商）；非业务项再清理。")
    if not bad and not weaks and not odd:
        c.add("提示", cat, "注册表启动项未命中可疑特征（共 %d 项）" % len(entries),
              detail="; ".join("%s=%s" % (l, (v or "")[:80]) for l, v, _k in entries[:15]),
              evidence=[str(e) for e in entries])


def win_tasks(c):
    cat = "计划任务"
    out, err = win_cmd(["schtasks", "/query", "/fo", "csv", "/v"], timeout=180)
    if not out:
        c.warn("schtasks 执行失败: %s" % err)
        return
    c.raw_add("计划任务全量", "schtasks /query /fo csv /v", out)
    rows = parse_csv_table(out)
    bad, weaks, total = [], [], 0
    for r in rows:
        run = r.get("Task To Run") or r.get("要运行的任务") or ""
        name = r.get("TaskName") or r.get("任务名") or ""
        if not run or run in ("N/A", "COM handler"):
            continue
        total += 1
        hits, strong, weak = cmdline_hits(run)
        sys_exe = is_system_exe_path(run)
        if strong:
            bad.append("%s => %s  [强特征: %s]" % (name, run[:220], "/".join(strong)))
            c.persist_add("计划任务", name, run)
        elif re.search(r"\\temp\\|\\appdata\\|\\programdata\\|\\users\\public\\|\\windows\\temp\\",
                       run, re.I):
            bad.append("%s => 从临时/公共目录执行: %s" % (name, run[:200]))
            c.persist_add("计划任务", name, run)
        elif weak and not sys_exe:
            weaks.append("%s => %s  [需人工确认: %s]" % (name, run[:200], "/".join(weak)))
            c.persist_add("计划任务", name, run)
    if bad:
        c.add("高危", cat, "计划任务中存在可疑/异常任务",
              detail="共 %d 个任务，命中 %d 个：\n%s" % (total, len(bad), "\n".join(bad[:25])),
              evidence=bad, advice="schtasks /delete /tn \"<任务名>\" /f 删除；并清理其执行的脚本文件。")
    if weaks:
        c.add("中危", cat, "计划任务中存在需人工确认的任务（脚本宿主/工具调用）",
              detail="共 %d 条：\n%s" % (len(weaks), "\n".join(weaks[:25])), evidence=weaks,
              advice="重点看任务作者、创建时间与执行程序路径；非业务任务可删除。")
    if not bad and not weaks:
        c.add("提示", cat, "计划任务未命中可疑特征（共 %d 个任务）" % total)


def win_services(c):
    cat = "服务自启动"
    rows, raw = wmic_csv("service get Name,DisplayName,PathName,StartMode,State,StartName")
    if not rows:
        rows, raw = ps_csv("Get-CimInstance Win32_Service | Select-Object Name,DisplayName,"
                           "PathName,StartMode,State,StartName | ConvertTo-Csv -NoTypeInformation")
    if not rows:
        c.warn("未能枚举服务（wmic 与 PowerShell 均失败）")
        return
    c.raw_add("服务列表", "wmic service / Get-CimInstance Win32_Service", raw)
    bad, weaks = [], []
    for r in rows:
        name = r.get("Name", "")
        path = (r.get("PathName") or "").strip()
        mode = (r.get("StartMode") or "").strip()
        if not path:
            continue
        hits, strong, weak = cmdline_hits(path)
        low = path.lower().strip('"')
        outside = not any(d in low for d in SIGNED_DIRS_WIN)
        if strong:
            bad.append("[强特征] %s (%s) => %s [命中: %s]" % (name, mode, path[:200], "/".join(strong)))
            c.persist_add("服务", name, path)
        elif outside and HIGH_RISK_DIR_RE.search(low):
            bad.append("[临时目录服务] %s (%s) => %s" % (name, mode, path[:200]))
            c.persist_add("服务", name, path)
        elif outside and BAD_PROC_HINT.search(low):
            weaks.append("[非标准安装目录] %s (%s) => %s" % (name, mode, path[:200]))
            c.persist_add("服务", name, path)
        elif weak and not is_system_exe_path(path):
            weaks.append("[需人工确认] %s (%s) => %s [命中: %s]" % (name, mode, path[:200], "/".join(weak)))
            c.persist_add("服务", name, path)
    if bad:
        c.add("高危", cat, "服务中存在可疑自启动项",
              detail="共 %d 个服务，命中 %d 个：\n%s" % (len(rows), len(bad), "\n".join(bad[:25])),
              evidence=bad, advice="sc qc <服务名> 确认，sc stop/sc delete 清除；注意先取证再删除。")
    if weaks:
        c.add("中危", cat, "服务中存在需人工确认的条目（非系统目录/命令行为脚本宿主）",
              detail="\n".join(weaks[:25]), evidence=weaks,
              advice="核对服务签名与厂商描述：sc qc <服务名>；非业务服务建议停用。")
    if not bad and not weaks:
        c.add("提示", cat, "服务项未命中可疑特征（共 %d 个服务）" % len(rows))


# ---------------------------------------------------- R23/P3：Windows 网络与横向面补强
# P3.1：SMB 横向判据——按 (进程, 远端端口) 聚合，阈值表 = LATERAL_PORT_THRESHOLDS（常量区）。
# P3.2：NetBIOS 暴露面——绑定状态（TcpipNetbiosOptions）＋ netstat 137/138/139 监听＋
#       Server/LanmanServer 服务状态；命中任一 ⇒ 提示「NetBIOS 暴露（可被枚举）」。
WIN_NET_ROW_RE = re.compile(r"\s*(TCP|UDP)\s+(\S+):(\d+)\s+(\S+):(\d+|\*)\s+(\S+)?\s*(\d+)")
NETBIOS_PORTS = (137, 138, 139)


def _win_net_rows(text):
    """解析 netstat -ano 输出（纯函数）：→ [dict(proto, lip, lport, rip, rport, state, pid)]。

    正则与既有 win_process_net 内联口径逐字一致；rport 为 "*"/缺失时置 None（判定与展示按需）。
    """
    rows = []
    for ln in (text or "").splitlines():
        m = WIN_NET_ROW_RE.match(ln)
        if not m:
            continue
        proto, lip, lport, rip, rport, state, pid = m.groups()
        try:
            lport_i = int(lport)
        except Exception:
            continue
        rport_i = None if rport in ("*", "", None) else int(rport)
        rows.append({"proto": proto, "lip": lip, "lport": lport_i, "rip": rip,
                     "rport": rport_i, "state": state or "", "pid": (pid or "").strip()})
    return rows


def _smb_multi_targets(rows, procs):
    """横向端口多目标聚合（纯函数）：→ [(pid, 进程名, 远端端口, [不同远端 IP...])]。

    口径（R23/P3.1）：TCP ESTABLISHED、远端端口命中 LATERAL_PORT_THRESHOLDS 键；按 PID+端口
    聚合「不同远端 IP」（排除回环/未指定地址）；是否达阈由调用方按下限判定。
    """
    want = set(int(p) for p in LATERAL_PORT_THRESHOLDS)
    agg = {}
    for r in (rows or []):
        if r.get("proto") != "TCP" or r.get("state") != "ESTABLISHED":
            continue
        if r.get("rport") not in want:
            continue
        ip = (r.get("rip") or "").strip("[]")
        if ip in ("", "0.0.0.0", "127.0.0.1", "::", "::1", "*"):
            continue
        pid = str(r.get("pid") or "")
        if not pid:
            continue
        agg.setdefault((pid, int(r["rport"])), set()).add(ip)
    out = []
    for (pid, port), ips in sorted(agg.items()):
        name = "?"
        try:
            name = (procs.get(int(pid)) or {}).get("name") or "?"
        except Exception as _e_r23:
            _degrade("_smb_multi_targets", _e_r23)
        out.append((pid, name, port, sorted(ips)))
    return out


def _netbios_opts_enabled(text):
    """TcpipNetbiosOptions 解析（纯函数）：→ (启用适配器数, 已探测总数)。

    取值 0=DHCP 启用、1=已启用、2=已禁用 ⇒ 0/1 计启用；兼容 PowerShell 'Desc=值' 与
    wmic CSV '…,值'（取行尾数字）。
    """
    en = tot = 0
    for m in re.finditer(r"(?:=|,\s*)([0-9])\s*$", text or "", re.M):
        v = int(m.group(1))
        if v > 2:
            continue
        tot += 1
        if v in (0, 1):
            en += 1
    return en, tot


def _netbios_listeners(text):
    """netstat 输出中的 NetBIOS 监听（纯函数）：→ ["137/udp", "139/tcp", ...]（排序去重）。

    UDP 137/138 无连接状态即视为监听；TCP 139 需 LISTENING；回环地址不算暴露。
    """
    out = set()
    for r in _win_net_rows(text):
        if r["lport"] not in NETBIOS_PORTS or r["lip"].strip("[]") in ("127.0.0.1", "::1"):
            continue
        if r["proto"] == "UDP":
            out.add("%d/udp" % r["lport"])
        elif "LISTENING" in (r["state"] or "").upper():
            out.add("%d/tcp" % r["lport"])
    return sorted(out)


def _svc_running(text):
    """sc query 输出判定（纯函数）：STATE 行含 RUNNING/正在运行 ⇒ True。"""
    return bool(re.search(r"(?im)^\s*(?:STATE|状态)\s*:\s*\d+\s*(?:RUNNING|正在运行)", text or ""))


def win_process_net(c):
    cat = "端口与进程"
    p_rows, p_raw = wmic_csv("process get ProcessId,Name,ExecutablePath,CommandLine,ParentProcessId")
    if not p_rows:
        p_rows, p_raw = ps_csv("Get-CimInstance Win32_Process | Select-Object ProcessId,Name,"
                               "ExecutablePath,CommandLine,ParentProcessId | ConvertTo-Csv -NoTypeInformation")
    procs = {}
    for r in p_rows:
        try:
            pid = int(r.get("ProcessId") or 0)
        except Exception:
            continue
        procs[pid] = {
            "name": r.get("Name") or "",
            "path": (r.get("ExecutablePath") or "").strip(),
            "cmd": (r.get("CommandLine") or "").strip(),
            "ppid": r.get("ParentProcessId") or "",
        }
    c.raw_add("进程列表", "wmic process / Get-CimInstance Win32_Process", p_raw)

    findings_proc = []
    weak_proc = []
    # 进程路径/伪装/父进程关系
    for pid, p in procs.items():
        name = (p["name"] or "").lower()
        path = (p["path"] or "")
        low = path.lower()
        base = name.replace(".exe", "")
        if name in ("svchost.exe", "lsass.exe", "services.exe", "csrss.exe", "winlogon.exe",
                    "smss.exe", "explorer.exe", "taskhostw.exe", "wininit.exe", "spoolsv.exe") \
                and path and "\\windows\\" not in low:
            findings_proc.append("[严重] 伪装系统进程: PID %d %s => %s" % (pid, name, path))
        if path and HIGH_RISK_DIR_RE.search(low):
            findings_proc.append("[临时/公共目录] PID %d %s => %s" % (pid, name, path))
        elif path and BAD_PROC_HINT.search(low):
            weak_proc.append("[用户/程序数据目录] PID %d %s => %s" % (pid, name, path))
        hits = match_rules(p["cmd"], SUSPICIOUS_CMDLINE_PATTERNS)
        strong = [h for h in hits if any(k in h for k in STRONG_CMD_KEYS)]
        if strong:
            findings_proc.append("[可疑命令行] PID %d %s => %s [命中: %s]"
                                 % (pid, name, p["cmd"][:200], "/".join(strong)))
        if name in ("cmd.exe", "powershell.exe") and p["ppid"]:
            try:
                parent = procs.get(int(p["ppid"]), {})
            except Exception:
                parent = {}
            if parent.get("name", "").lower() in ("w3wp.exe", "php-cgi.exe", "java.exe",
                                                  "tomcat.exe", "httpd.exe", "nginx.exe", "apache.exe"):
                findings_proc.append("[Web 落地执行] %s(PID %s) 由 %s 派生: %s"
                                     % (name, pid, parent.get("name"), p["cmd"][:200]))
    if findings_proc:
        c.add("高危", cat, "进程中发现可疑项", detail="\n".join(findings_proc[:25]),
              evidence=findings_proc, advice="先取进程内存/样本（tasklist /svc、procdump），再隔离处置。")
    if weak_proc:
        c.add("中危", cat, "进程运行在用户/程序数据目录（需人工确认，常见于正常软件）",
              detail="\n".join(weak_proc[:25]), evidence=weak_proc,
              advice="结合文件签名、厂商信息与网络外联判断；非业务程序再处置。")
    if not findings_proc and not weak_proc:
        c.add("提示", cat, "进程路径与命令行未命中可疑特征（共 %d 个进程）" % len(procs))

    # 未签名可疑进程（仅对非系统目录进程调用签名校验，控制耗时）
    suspects = [(pid, p) for pid, p in procs.items()
                if p["path"] and p["path"].lower().endswith(".exe")
                and not any(d in p["path"].lower() for d in SIGNED_DIRS_WIN)][:15]
    unsigned = []
    for pid, p in suspects:
        out, _ = win_cmd(["powershell", "-NoProfile", "-Command",
                          "(Get-AuthenticodeSignature -LiteralPath '%s').Status" % p["path"].replace("'", "''")],
                         timeout=30)
        st = (out or "").strip()
        if st and "Valid" not in st and "签名" not in st:
            unsigned.append("%s (PID %s) 签名状态=%s" % (p["path"], pid, st))
    if unsigned:
        c.add("中危", cat, "非系统目录进程未通过签名校验", detail="\n".join(unsigned[:15]),
              evidence=unsigned, advice="重点排查：这些进程常见于木马/挖矿，先比对外联 IP。")

    # 网络连接
    rows, raw = wmic_csv("process get ProcessId,ExecutablePath")
    n_out, _ = win_cmd(["netstat", "-ano"])
    c.raw_add("网络连接", "netstat -ano", n_out)
    net_rows = _win_net_rows(n_out)
    suspicious_conn = []
    external = []
    for r in net_rows:
        if r["proto"] == "TCP" and r["state"] != "ESTABLISHED":
            continue
        if r["rip"] in ("0.0.0.0", "127.0.0.1", "::", "*") or not r["rport"]:
            continue
        ip = r["rip"].strip("[]")
        if is_private_ip(ip):
            continue
        pid, lip, lport, rport = r["pid"], r["lip"], r["lport"], r["rport"]
        pname = procs.get(int(pid), {}).get("name", "?") if pid.isdigit() else "?"
        ppath = procs.get(int(pid), {}).get("path", "") if pid.isdigit() else ""
        external.append("%s -> %s:%s (PID %s %s)" % (lip, ip, rport, pid, pname))
        if rport in SUSPICIOUS_PORTS:
            suspicious_conn.append("[后门端口] %s:%s -> %s:%s 进程 %s(%s) %s"
                                   % (lip, lport, ip, rport, pname, pid, SUSPICIOUS_PORTS[rport]))
        elif ppath and HIGH_RISK_DIR_RE.search(ppath.lower()):
            suspicious_conn.append("[可疑进程外联] %s(%s) %s -> %s:%s 进程路径 %s"
                                   % (pname, pid, lip, ip, rport, ppath))
    if suspicious_conn:
        c.add("高危", cat, "存在可疑外联连接", detail="\n".join(suspicious_conn[:25]),
              evidence=suspicious_conn, advice="netstat -ano | findstr <PID> 定位；结合微步/VirusTotal 情报研判后阻断。")
    else:
        c.add("提示", cat, "未发现后门端口/可疑进程外联（公网连接 %d 条）" % len(external),
              evidence=external[:50])

    # R23/P3.1：SMB 多目标外连（横向移动/蠕虫扩散判据，阈值只读 LATERAL_PORT_THRESHOLDS）
    for _pid, _name, _port, _ips in _smb_multi_targets(net_rows, procs):
        _rule = LATERAL_PORT_THRESHOLDS.get(_port) or {}
        _min = int(_rule.get("min_remote_ips") or 10)
        if len(_ips) < _min:
            continue
        c.add("高危", cat, _rule.get("title") or "疑似横向移动（多目标外连）",
              detail="进程 %s(PID %s) 远端端口 %d 的不同远端 IP 数=%d（阈值 %d）\n前 10 个 IP: %s"
                     % (_name, _pid, _port, len(_ips), _min, "、".join(_ips[:10])),
              evidence=["进程=%s PID=%s 远端端口=%d 远端 IP 数=%d：%s"
                        % (_name, _pid, _port, len(_ips), "、".join(_ips[:10]))],
              advice="核对进程用途（签名/路径/启动参数）；SMB 多目标连接常见于 PsExec/勒索蠕虫"
                     "横向扩散，建议先隔离主机再比对目标资产清单。")

    # R23/P3.2：NetBIOS 暴露（绑定状态 / 137·138·139 监听 / Server·LanmanServer 服务三选一）
    nb_opts, _ = win_cmd(["powershell", "-NoProfile", "-Command",
                          "Get-CimInstance Win32_NetworkAdapterConfiguration | "
                          "Where-Object {$_.IPEnabled} | ForEach-Object { "
                          "\"$($_.Description)=$($_.TcpipNetbiosOptions)\" }"], timeout=60)
    if not (nb_opts or "").strip():
        nb_opts, _ = win_cmd(["wmic", "nicconfig", "get", "TcpipNetbiosOptions,Description",
                              "/format:csv"], timeout=60)
    nb_enabled, nb_total = _netbios_opts_enabled(nb_opts or "")
    nb_listen = _netbios_listeners(n_out or "")
    lms_out, _ = win_cmd(["sc", "query", "LanmanServer"], timeout=30)
    srv_out, _ = win_cmd(["sc", "query", "Server"], timeout=30)
    nb_svc = [nm for nm, out in (("LanmanServer", lms_out), ("Server", srv_out))
              if _svc_running(out or "")]
    nb_signals = []
    if nb_enabled:
        nb_signals.append("NetBIOS over TCP/IP 绑定状态：%d/%d 个适配器启用（TcpipNetbiosOptions 0/1）"
                          % (nb_enabled, nb_total))
    if nb_listen:
        nb_signals.append("netstat 监听端口：%s" % "、".join(nb_listen))
    if nb_svc:
        nb_signals.append("服务运行中：%s" % "、".join(nb_svc))
    if nb_signals:
        c.add("提示", cat, "NetBIOS 暴露（可被枚举）",
              detail="\n".join(nb_signals), evidence=nb_signals,
              advice="无 NetBIOS/旧版共享需求时：网卡属性禁用 NetBIOS over TCP/IP（或 "
                     "TcpipNetbiosOptions=2）、关闭 137/138/139 监听并停用 Server 服务。")


# ---------------------------------------------------- R23/P4：Windows 文件面增补
# 依据：R23 需求书 P4.1~P4.3（第01章第5篇 勒索、第03章第1篇 隐藏）。
# 4.1 勒索痕迹：用户目录/桌面/下载/文档/ProgramData/%TEMP% 上做「后缀 + 勒索信文件名」双判据扫描（高危）；
# 4.2 系统目录近期新增：C:\Windows 根 / System32 / SysWOW64，带「更新目录白名单 + 有效签名」降噪；
# 4.3 时间戳篡改：mtime < ctime（与 Linux 面同口径，命中=提示，证据含两个时间值）。
WIN_SYS_RECENT_SUBDIRS = ("", "System32", "SysWOW64")      # 相对 %SystemRoot%
WIN_SYS_RECENT_SKIP_DIRS = (
    # 更新/组件/维护目录（需求点名：WinSxS/assembly/servicing/Installer/Temp 等）
    "winsxs", "assembly", "servicing", "installer", "temp", "softwaredistribution",
    "logs", "prefetch", "catroot", "catroot2", "driverstore", "inf",
    # 系统自带目录名（Win10/11 默认安装即存在；同名目录不算“近期新增”，避免日常噪声）
    "appcompat", "apppatch", "appreadiness", "bcastdvr", "boot", "cleanlog", "config",
    "csc", "cursors", "debug", "diagnostics", "downloaded program files", "drivers",
    "fonts", "globalization", "help", "ime", "l2schemas", "lastgood", "lastgood.tmp",
    "livekernelreports", "media", "microsoft.net", "minidump", "moderation", "ndf",
    "panther", "performance", "policydefinitions", "provisioning", "registration",
    "resources", "security", "servicestate", "setup", "sleepstudy", "speech", "sru",
    "systemapps", "systemresources", "systemtemp", "system32", "syswow64", "tasks",
    "traces", "twain_32", "vss", "web", "winevt", "spool", "wbem", "logfiles",
    "msdtc", "schcache",
)   # 更新/组件维护目录 + 系统自带目录白名单
WIN_SYS_RECENT_EXTS = (".exe", ".dll", ".sys", ".drv", ".ocx", ".cpl", ".scr", ".com",
                       ".bat", ".cmd", ".ps1", ".vbs", ".js", ".jse", ".wsf", ".hta",
                       ".msc", ".jar")
WIN_SYS_RECENT_SKIP_NAMES = ("desktop.ini", "thumbs.db")
WIN_SYS_RECENT_MAX_SIG = 40        # 近期候选的签名批量校验上限（控制耗时）
WIN_RANSOM_MAX_HITS = 30           # 勒索痕迹证据上限
WIN_RANSOM_MAX_FILES = 40000       # 勒索扫描文件数上限（防止超大用户目录拖慢默认档）


def _win_ransom_scan(dirs):
    """勒索痕迹扫描（只读遍历）：→ (hits, scanned, truncated)。

    判据（R23/P4.1，与 Linux 侧同口径）：文件名（小写）包含勒索信名（表内大小写不敏感），
    或以 RANSOM_EXT_HINTS 后缀结尾。深度 ≤2、文件数上限见常量；命中后提前收敛。
    """
    hits, seen_dirs, seen_files, n, truncated = [], set(), set(), 0, False
    for d in (dirs or []):
        fa = os.path.abspath(d) if d else ""
        if not fa or fa in seen_dirs or not os.path.isdir(fa):
            continue
        seen_dirs.add(fa)
        for root, dirs_, files in os.walk(fa):
            if root.count(os.sep) - fa.count(os.sep) >= 2:
                dirs_[:] = []
            else:
                dirs_[:] = [x for x in dirs_
                            if x.lower() not in ("appdata", "application data")]
            for f in files:
                n += 1
                if n > WIN_RANSOM_MAX_FILES:
                    return hits, n - 1, True
                fp = os.path.join(root, f)
                key = fp.lower()
                if key in seen_files:
                    continue
                seen_files.add(key)
                low = f.lower()
                if any(nm.lower() in low for nm in RANSOM_NOTE_NAMES):
                    hits.append("勒索信: %s" % fp)
                elif low.endswith(RANSOM_EXT_HINTS):
                    hits.append("被加密文件: %s" % fp)
                if len(hits) >= WIN_RANSOM_MAX_HITS:
                    return hits, n, False
    return hits, n, truncated


def _win_sys_recent_scan(c, dirs, sig_map=None):
    """系统目录近期新增扫描（R23/P4.2）：→ (files, dirs_, info)。

    files: [(path, stat, 签名状态文本)]（已按有效签名排除后的保留项）；
    dirs_: [(path, stat)]（近期目录）；info: dict(candidates/sig_excluded/whitelist_excluded)。
    只扫各目录的直接子项（不递归，控制耗时）；时间窗沿用 c.days；名称命中更新/维护目录
    白名单的直接跳过；签名有效（sig_map 给出且状态 Valid）的文件跳过；sig_map=None 时
    调用 _hj_adv_sig_map 批量取（只对近期候选）。
    """
    files, dirs_, skipped_wh = [], [], 0
    for d in (dirs or []):
        if not d or not os.path.isdir(d):
            continue
        try:
            entries = list(os.scandir(d))
        except Exception as _e_r23:
            _degrade("_win_sys_recent_scan", _e_r23)
            continue
        for e in entries:
            nm = (e.name or "").lower()
            if nm in WIN_SYS_RECENT_SKIP_NAMES or nm in WIN_SYS_RECENT_SKIP_DIRS:
                skipped_wh += 1
                continue
            try:
                st = e.stat()
            except Exception as _e_r23:
                _degrade("_win_sys_recent_scan", _e_r23)
                continue
            if (time.time() - st.st_mtime) > c.days * 86400:
                continue
            if e.is_dir():
                dirs_.append((e.path, st))
            elif e.is_file() and os.path.splitext(nm)[1] in WIN_SYS_RECENT_EXTS:
                files.append((e.path, st))
    if sig_map is None and files:
        sig_map = _hj_adv_sig_map(c, [p for p, _st in files[:WIN_SYS_RECENT_MAX_SIG]],
                                  tag="（系统目录近期新增）")
    sig_map = sig_map or {}
    kept, sig_excluded = [], 0
    for p, st in files:
        sg = sig_map.get(p.lower())
        if sg and (sg[0] or "").strip().lower() == "valid":
            sig_excluded += 1
            continue
        kept.append((p, st, (sg[0] if sg else "不可得")))
    info = {"candidates": len(files) + len(dirs_), "sig_excluded": sig_excluded,
            "whitelist_excluded": skipped_wh}
    return kept, dirs_, info


def win_files(c, extra_dirs=None):
    cat = "异常文件"
    dirs = list(extra_dirs or [])
    for d in (os.environ.get("TEMP", ""), r"C:\Windows\Temp",
              os.path.join(os.environ.get("SystemDrive", "C:") + "\\", "inetpub\\wwwroot"),
              os.path.join(os.environ.get("ProgramData", ""), ""),
              os.path.join(os.environ.get("USERPROFILE", ""), "Downloads")):
        if d and os.path.isdir(d):
            dirs.append(d)
    seen = set()
    findings, tamper = [], []
    for d in dirs:
        d = os.path.abspath(d)
        if d in seen or not os.path.isdir(d):
            continue
        seen.add(d)
        for root, dirs_, files in os.walk(d):
            if root.count(os.sep) - d.count(os.sep) > 2:
                dirs_[:] = []
                continue
            for f in files:
                fp = os.path.join(root, f)
                try:
                    st = os.stat(fp)
                except Exception:
                    continue
                if time.time() - st.st_mtime <= c.days * 86400 and \
                        re.search(r"\.(exe|dll|bat|ps1|vbs|js|jse|wsf|scr|com|pif|lnk|php|jsp|asp)$", f, re.I):
                    findings.append("近期(%d天)新增/变动: %s (%s, %d字节)"
                                    % (c.days, fp, human_time(st.st_mtime), st.st_size))
                    if len(tamper) < TIMESTOMP_MAX_EVIDENCE and _timestomp_hit(st):
                        tamper.append(_timestomp_text(fp, st))     # R23/P4.3
                if len(findings) > 200:
                    break
    if findings:
        c.add("中危", cat, "临时/Web 目录存在近期落地的脚本或可执行文件",
              detail="\n".join(findings[:25]), evidence=findings,
              advice="逐个核对来源、创建时间；可再执行: python er_check.py webshell --dir <Web根目录> 进一步确认。")
    else:
        c.add("提示", cat, "临时/Web 目录未发现近期落地文件")

    # R23/P4.1：勒索痕迹（用户目录/桌面/下载/文档/ProgramData/%TEMP% 双判据扫描）
    _up = os.environ.get("USERPROFILE", "")
    ransom_dirs = []
    for d in (_up, os.path.join(_up, "Desktop") if _up else "",
              os.path.join(_up, "Downloads") if _up else "",
              os.path.join(_up, "Documents") if _up else "",
              os.environ.get("ProgramData", ""), os.environ.get("TEMP", "")):
        if d and d not in ransom_dirs:
            ransom_dirs.append(d)
    ransom_hits, ransom_n, ransom_trunc = _win_ransom_scan(ransom_dirs)
    c.raw_add("勒索痕迹扫描（后缀+勒索信名）",
              "扫描目录：%s（深度≤2，文件上限 %d）" % ("、".join(ransom_dirs) or "(无)",
                                                       WIN_RANSOM_MAX_FILES),
              ("\n".join(ransom_hits[:WIN_RANSOM_MAX_HITS]) + "\n" if ransom_hits else "")
              + "扫描文件数: %d%s" % (ransom_n, "（达到上限，已截断）" if ransom_trunc else ""))
    if ransom_hits:
        c.add("高危", cat, "发现勒索痕迹（后缀/勒索信命中）",
              detail="\n".join(ransom_hits[:25]), evidence=ransom_hits[:50],
              advice="勒索事件优先断网隔离并固定磁盘镜像/样本；核验备份可用性，处置前不要清理现场。")

    # R23/P4.2：系统目录（C:\Windows 根 / System32 / SysWOW64）近期新增，带白名单降噪
    _sysroot = os.environ.get("SystemRoot", r"C:\Windows")
    _sys_dirs = [os.path.join(_sysroot, _sub) if _sub else _sysroot
                 for _sub in WIN_SYS_RECENT_SUBDIRS]
    sys_files, sys_dirs, sys_info = _win_sys_recent_scan(c, _sys_dirs)
    sys_hits = ["[目录] %s（mtime %s）" % (p, human_time(st.st_mtime)) for p, st in sys_dirs]
    sys_hits += ["[文件] %s（mtime %s，签名=%s）" % (p, human_time(st.st_mtime), sg)
                 for p, st, sg in sys_files]
    c.raw_add("系统目录近期新增扫描",
              "扫描 %s；窗口 %d 天；更新目录白名单 + 有效签名排除" % ("、".join(_sys_dirs), c.days),
              (("\n".join(sys_hits[:40]) + "\n") if sys_hits else "")
              + "候选条目: %d；白名单排除: %d；签名排除: %d；命中: %d"
              % (sys_info["candidates"], sys_info["whitelist_excluded"],
                 sys_info["sig_excluded"], len(sys_hits)))
    if sys_hits:
        c.add("中危", cat, "系统目录存在近期新增/变动条目（已按更新目录与签名白名单降噪）",
              detail="\n".join(sys_hits[:25]), evidence=sys_hits[:50],
              advice="核对条目来源与签名（Get-AuthenticodeSignature）；非补丁/更新产生的可执行文件重点排查。")
    for p, st, _sg in sys_files:
        if len(tamper) < TIMESTOMP_MAX_EVIDENCE and _timestomp_hit(st):
            tamper.append(_timestomp_text(p, st))                  # R23/P4.3

    # ADS 数据流（隐藏后门：echo shell > index.php:hidden.jpg）
    ads = []
    for d in list(seen)[:6]:
        out, _ = win_cmd(["cmd", "/c", "dir", "/a", "/r", "/s", "/b", d], timeout=120)
        for ln in (out or "").splitlines():
            ln = ln.strip()
            if not ln or "找不到文件" in ln or "File Not Found" in ln:
                continue
            if re.search(r":[^\\/]\S*", ln) and "Zone.Identifier" not in ln:
                ads.append(ln)
    if ads:
        c.add("高危", cat, "发现 NTFS 数据流（ADS 隐藏文件）",
              detail="\n".join(ads[:20]), evidence=ads,
              advice="type <宿主文件>:<流名> 查看内容；删除宿主文件即可清除该流（第03章 隐藏篇）。")
    else:
        c.add("提示", cat, "未发现异常 NTFS 数据流(ADS)")

    # hosts 文件
    hosts = os.path.join(os.environ.get("SystemRoot", r"C:\Windows"),
                         r"System32\drivers\etc\hosts")
    content = safe_read(hosts) or ""
    c.raw_add("hosts 文件", hosts, content)
    lines = [l for l in content.splitlines() if l.strip() and not l.strip().startswith("#")]
    hijack = []
    for l in lines:
        parts = l.split()
        if len(parts) >= 2 and parts[0] not in ("0.0.0.0", "127.0.0.1", "::1", "::"):
            hijack.append(l.strip())
    if hijack:
        c.add("高危", cat, "hosts 文件存在非回环地址的重定向（疑似域名劫持）",
              detail="\n".join(hijack[:20]), evidence=hijack,
              advice="删除异常解析行；域名被指向攻击者 IP 可造成挂马/钓鱼/更新劫持。")
    elif len(lines) > 30:
        c.add("低危", cat, "hosts 文件存在大量屏蔽条目（%d 条，多为去广告/防护软件写入）" % len(lines),
              detail="\n".join(lines[:10]), advice="核对是否为安全软件/去广告工具写入，非业务条目可清理。")
    else:
        c.add("提示", cat, "hosts 文件解析条目正常（%d 条）" % len(lines),
              detail="\n".join(lines[:10]))

    # 隐藏+系统属性文件（attrib +s +a +h +r）
    SKIP_NAMES = ("desktop.ini", "application data", "documents", "templates", "开始菜单",
                  "桌面", "settings", "recent", "「开始」菜单", "sendto", "netHood",
                  "PrintHood", "Cookies", "Local Settings", "My Documents", "History")
    for d in list(seen)[:4]:
        out, _ = win_cmd(["cmd", "/c", "dir", "/a:s", "/a:h", "/b", "/s", d], timeout=120)
        files = []
        for x in (out or "").splitlines():
            x = x.strip()
            if not x or "找不到文件" in x or "File Not Found" in x:
                continue
            base = os.path.basename(x).lower()
            if base in [n.lower() for n in SKIP_NAMES]:
                continue
            if "\\microsoft\\" in x.lower():   # 系统/驱动包自带
                continue
            try:
                st = os.stat(x)
                if getattr(st, "st_file_attributes", 0) & 0x400:  # 重解析点/联接，系统自带
                    continue
            except Exception as _e_r19:
                _degrade("win_files", _e_r19)
            files.append(x)
        if files:
            c.raw_add("隐藏+系统属性文件: %s" % d, "dir /a:s /a:h /s /b", "\n".join(files[:100]))
            c.add("中危", cat, "存在隐藏+系统属性文件（%s）" % d,
                  detail="; ".join(files[:10]), evidence=files[:50],
                  advice="attrib -s -h -r <文件> 可恢复显示（第03章 隐藏篇）；核对是否为业务文件。")

    # R23/P4.3：时间戳篡改（mtime < ctime，Windows/Linux 同口径；证据含两个时间值）
    if tamper:
        c.add("提示", cat, "文件时间被篡改（修改时间早于创建时间）",
              detail="\n".join(tamper[:TIMESTOMP_MAX_EVIDENCE]),
              evidence=tamper[:TIMESTOMP_MAX_EVIDENCE],
              advice="mtime 早于 ctime（Windows 为创建时间）常见于 timestomp 反取证；"
                     "请结合日志时间线人工确认文件真实落地时间。")


def sec_query(c, ids, count=200, timeout=180, label=""):
    """查询安全日志（R16/P3：并入统一分页取数机制；无权限时给出明确提示）。

    返回 [(epoch, 时间串, {字段:值})]（升序）；失败/空 → []。拒绝访问时保持既有提示口径：
    只告警一次「安全日志(Security)不可读」并给出「安全日志未分析（权限不足）」结论。
    """
    ev, why = _evt_fetch(c, "Security", ids, count=count, timeout=timeout,
                         label=label or "日志分析")
    if ev is None:
        low = (why or "").lower()
        if "拒绝访问" in (why or "") or "denied" in low:
            if not any("安全日志" in w for w in c.warnings):
                c.warn("安全日志(Security)不可读：登录成功/失败、账号变更、爆破统计已跳过，请以管理员身份运行")
                c.add("提示", "日志分析", "安全日志未分析（权限不足）",
                      advice="以管理员身份重新运行本脚本；或手工导出 Security 日志后用微软 Log Parser 分析。")
        return []
    return ev


def win_logs(c):
    """日志分析（R16/P3 重构：改为结构化事件字段解析 + 统一分页取数）。

    要点：① 结果不再依赖 /f:text 的本地化文本（“账户名/Logon Type” 混排、中文路径经
    文本输出再回解析都易失真），统一走 /f:xml 结构化字段；② 通道可用性来自开跑探测
    （不存在/已禁用/无权限读取与“无事件”可区分，P4）；③ 取数上限显式化，达上限时由
    「数据源与覆盖度」段声明截断与真实覆盖时长。既有分类名、标题与阈值口径保持不变。
    """
    cat = "日志分析"
    sys_state = _r16_probe_or_read_state(c, "System")
    if sys_state.get("status") != "ok":
        c.warn("系统日志(System)不可用（%s）：服务安装(7045)、登录/账号变更事件均无法分析"
               % sys_state.get("detail"))
        c.add("提示", cat, "事件日志未分析（通道不可用）",
              advice="以管理员身份重新运行本脚本，或手工导出日志（eventvwr.msc）后用 Log Parser 分析。")
        return
    got, _why = _evt_fetch(c, "System", ("7045",), count=300, timeout=180,
                           label="日志分析-服务安装(7045)")
    if got:
        svc = []
        for _ep, disp, d in got:
            nm = _sec_get(d, "ServiceName") or "?"
            path = _sec_get(d, "ImagePath") or "?"
            svc.append("%s 安装服务 %s => %s" % (disp, nm, path))
        c.raw_add("系统日志-服务安装(7045)", "wevtutil qe System EventID=7045（分页，上限 300 条）",
                  "\n".join(svc[:80]))
        bad = [s for s in svc if match_rules(s, SUSPICIOUS_CMDLINE_PATTERNS) or
               re.search(r"\\temp\\|\\tmp\\|\\appdata\\|\\programdata\\|\\users\\public\\", s, re.I)]
        if bad:
            c.add("高危", cat, "近期有服务安装事件且路径可疑",
                  detail="\n".join(bad[:20]), evidence=bad,
                  advice="sc qc <服务名> 核对；非业务服务：sc stop / sc delete 并清理文件。")
        else:
            c.add("提示", cat, "近期服务安装事件 %d 条（未见可疑路径）" % len(svc),
                  detail="\n".join(svc[:10]), evidence=svc[:20])

    # 账号相关：4720 新增用户 / 4726 删除用户 / 4728+4732 加入特权组 / 4625 失败登录 / 4624 成功登录
    ev = sec_query(c, ("4720", "4726", "4728", "4732"), 200)
    if ev:
        lines = ["EventID=%s 涉及账户=%s" % (d.get("_EventID") or "?",
                                           _sec_get(d, "TargetUserName", "MemberName") or "?")
                 for _ep, _disp, d in ev]
        c.raw_add("安全日志-账号变更事件", "wevtutil qe Security 4720/4726/4728/4732（分页，上限 200 条）",
                  "\n".join(lines[:80]))
        c.add("中危", cat, "存在账号新增/删除/提权事件",
              detail="\n".join(lines[:30]), evidence=_adv_cap(lines, 100, 500),
              advice="核对是否为运维操作；可疑账号立即禁用并回溯其登录源 IP。")

    ev = sec_query(c, ("4625",), 1000)
    if ev:
        users, ips = {}, {}
        for _ep, _disp, d in ev:
            u = _sec_get(d, "TargetUserName", "SubjectUserName")
            ip = _sec_get(d, "IpAddress", "SourceNetworkAddress")
            if u:
                users[u] = users.get(u, 0) + 1
            if ip:
                ips[ip] = ips.get(ip, 0) + 1
        top_u = sorted(users.items(), key=lambda x: -x[1])[:10]
        top_i = sorted(ips.items(), key=lambda x: -x[1])[:10]
        over = [x for x in top_i if x[1] >= BRUTE_THRESHOLD and x[0] not in ("-", "", "::1", "127.0.0.1")]
        if over:
            c.add("高危", cat, "检测到暴力破解（登录失败次数超阈值 %d）" % BRUTE_THRESHOLD,
                  detail="源 IP 失败次数: %s" % "; ".join("%s=%d" % x for x in over),
                  advice="封禁来源 IP；确认这些账号是否弱口令并被登录成功（结合 4624）。")
        else:
            c.add("提示", cat, "登录失败 TOP（未超阈值）",
                  detail="账号: %s; 源IP: %s" % (top_u, top_i))
        c.raw_add("安全日志-登录失败(4625)",
                  "wevtutil qe Security EventID=4625（分页，上限 1000 条）",
                  "\n".join("%s EventID=4625 账户=%s 来源=%s" % (disp, _sec_get(d, "TargetUserName") or "?",
                                                                 _sec_get(d, "IpAddress", "SourceNetworkAddress") or "-")
                            for _ep, disp, d in ev[:300]))
        c.raw_add("登录失败统计(账号)", "wevtutil 4625 统计", "\n".join("%s: %d" % x for x in top_u))
        c.raw_add("登录失败统计(源IP)", "wevtutil 4625 统计", "\n".join("%s: %d" % x for x in top_i))

    ev = sec_query(c, ("4624",), 500, label="日志分析-登录成功(4624)")
    if ev:
        succ, rdp, raw_lines = [], [], []
        for _ep, disp, d in ev:
            u = _sec_get(d, "TargetUserName", "SubjectUserName")
            t = _sec_get(d, "LogonType")
            ip = _sec_get(d, "IpAddress", "SourceNetworkAddress") or "-"
            raw_lines.append("%s 账户=%s 类型=%s 来源IP=%s" % (disp, u or "?", t or "?", ip))
            if u and ip not in ("-", "127.0.0.1", "::1", ""):
                line = "账户=%s 类型=%s 来源IP=%s" % (u, t or "?", ip)
                succ.append(line)
                if t in ("10", "3", "8"):
                    rdp.append(line)
        c.raw_add("安全日志-登录成功(4624)",
                  "wevtutil qe Security EventID=4624（分页，上限 500 条）",
                  "\n".join(raw_lines[:200]))
        if rdp:
            c.add("中危", cat, "存在远程登录成功记录（RDP/网络登录）",
                  detail="\n".join(rdp[:20]), evidence=rdp,
                  advice="核对这些登录是否为管理员本人；异常登录需立即改密并排查其后续操作。")
        else:
            c.add("提示", cat, "未发现远程(类型10/3/8)登录成功记录",
                  detail="\n".join(succ[:10]))


# ============================================================ Windows 提权面（R5 新增面）
# 依据：test.md §P0-5（未引用服务路径 / AlwaysInstallElevated）、§P1-8（服务失败恢复 / 隐藏任务）
# 说明：本段全部为新增代码——不调用、不修改既有 win_services() / win_tasks()；
#       命中前先读 c.findings 中「服务自启动 / 计划任务」两类做去重，同一对象（服务名/任务名/exe 路径）
#       已被既有面报过的一律跳过（宁少报，不重复报）。
# 证据口径：每条结论都带可核对命令或注册表项（icacls / reg query / sc qfailure / schtasks /xml）。

_PRIV_DEDUP_CATS = ("服务自启动", "计划任务")
_PRIV_ENC_DESC = SUSPICIOUS_CMDLINE_PATTERNS[0][1]   # “PowerShell 编码命令（无文件攻击常用）”
_PRIV_BROAD_PEER = re.compile(
    r"(?i)(everyone|所有人|authenticated users|已通过身份验证的用户|\busers\b|interactive|"
    r"iis_iusrs|domain users|anonymous|匿名)")
_PRIV_WRITE_ACE = re.compile(r"(?i)(\(f\)|\(m\)|\(w\)|\(wd\)|完全控制|修改|写入)")
_PRIV_DENY_ACE = re.compile(r"(?i)(\(deny\)|（deny）|\(拒绝\)|拒绝|deny)")
_PRIV_TEMP_TOKENS = ("\\temp\\", "\\tmp\\", "\\users\\", "\\appdata\\", "\\downloads\\",
                     "\\desktop\\", "\\documents\\", "\\public\\", "\\$recycle.bin\\",
                     "\\perflogs\\", "\\windows\\temp\\", "%temp%", "%tmp%", "%appdata%")
_PRIV_EXE_EXT = r"(?:exe|com|scr|bat|cmd|ps1|vbs|js|hta)"
_PRIV_MAX_HIDDEN = 10
_PRIV_MAX_TASK_XML = 24


def _priv_expand(path):
    """展开 %VAR% 形式的环境变量（不依赖 shell；未知变量原样保留）。"""
    def _repl(m):
        v = os.environ.get(m.group(1))
        return v if v else m.group(0)
    return re.sub(r"%([^%]+)%", _repl, path or "")


def _priv_temp_hit(path):
    """是否指向临时/用户目录（Temp、AppData、Users、下载、桌面等）。纯函数。"""
    p = (path or "").strip().replace("/", "\\").lower()
    if not p:
        return False
    return any(t in p for t in _PRIV_TEMP_TOKENS)


def _priv_flat(text, n=200):
    """压缩空白便于单行证据展示（纯函数）。"""
    return re.sub(r"\s+", " ", (text or "")).strip()[:n]


def _priv_unquoted_exe(pathname):
    """未引用服务路径判定（纯函数）：满足条件返回可执行体路径，否则返回空串。

    条件（同时成立）：ImagePath 无引号、裸盘符开头、可执行体路径内含空格。
    只截到首个可执行扩展名且其后是空格/结尾，避免把参数误当路径（宁漏不误）。
    """
    raw = (pathname or "").strip()
    if not raw or '"' in raw or "'" in raw:
        return ""
    p = _priv_expand(raw)
    if not re.match(r"(?i)^[a-z]:\\", p):
        return ""
    m = re.match(r"(?i)^([a-z]:\\[^\"']*?\.%s)(?=\s|$)" % _PRIV_EXE_EXT, p)
    if not m:
        return ""
    exe = m.group(1)
    return exe if " " in exe else ""


def _priv_exe_from_cmd(cmd):
    """从命令行里稳健截取可执行体路径（带空格且未加引号时按扩展名截断）。"""
    p = (cmd or "").strip()
    if not p:
        return ""
    if p.startswith('"'):
        m = re.match(r'"([^"]+)"', p)
        return m.group(1).strip() if m else ""
    if not re.match(r"(?i)^[a-z]:\\", p):
        m = re.match(r"^(\S+)", p)
        return m.group(1).strip() if m else ""
    m = re.match(r"(?i)^([a-z]:\\[^\"']*?\.%s)(?=\s|$)" % _PRIV_EXE_EXT, p)
    return m.group(1) if m else ""


def _priv_parent_dirs(path):
    """路径的各级父目录（含盘根）。如 C:\\A B\\C\\svc.exe → [C:\\, C:\\A B, C:\\A B\\C]。纯函数。"""
    p = (path or "").strip().rstrip("\\")
    parts = [x for x in p.split("\\") if x]
    out = []
    for i in range(1, len(parts)):
        d = "\\".join(parts[:i])
        if len(d) == 2 and d.endswith(":"):
            d += "\\"
        out.append(d)
    return out


def _priv_acl_verdict(text, dirpath=None):
    """从 icacls 输出判定『普通用户可写』（纯函数）；返回 (state, why)。

    state ∈ {"writable","not","unknown"}：拒绝优先（广义主体存在 DENY/拒绝 → 不可写）；
    仅当 Everyone/Users/已认证用户等广义主体被授予 (F)/(M)/(W)/完全控制/修改/写入 才判可写；
    解析不出任何 ACE 时返回 unknown（调用方据此保守降级，绝不冒进）。
    """
    lines = [ln.strip() for ln in (text or "").splitlines() if ln.strip()]
    if not lines:
        return "unknown", "icacls 无输出（命令不可用或权限不足）"
    pre = (dirpath or "").strip().lower()
    ace = 0
    broad_write = ""
    broad_deny = ""
    broad_io = ""
    for ln in lines:
        if pre and ln.lower().startswith(pre):
            ln = ln[len(pre):].strip()      # icacls 会把首条 ACE 接在目录名后，先剥掉目录前缀
        i = ln.find(":")
        if i <= 0:
            continue
        principal, rights = ln[:i], ln[i + 1:]
        if "(" not in rights:
            continue
        ace += 1
        if "(io)" in rights.lower():
            # (IO)=仅继承：对目录本身无效，只影响子对象，不能作为“本级目录可写”的依据
            if _PRIV_BROAD_PEER.search(principal):
                broad_io = broad_io or ln
            continue
        if _PRIV_DENY_ACE.search(rights) and _PRIV_BROAD_PEER.search(principal):
            broad_deny = broad_deny or ln
        elif _PRIV_BROAD_PEER.search(principal) and _PRIV_WRITE_ACE.search(rights):
            broad_write = broad_write or ln
    if broad_deny:
        return "not", "拒绝优先: %s" % broad_deny
    if broad_write:
        return "writable", broad_write
    if ace == 0:
        return "unknown", "无法解析 ACL（共 %d 行输出）" % len(lines)
    if broad_io:
        return "not", "仅 (IO) 继承限定授权（目录本身不可写，只影响子对象）: %s" % broad_io
    return "not", "未发现对普通用户的可写授权（已解析 %d 条 ACE）" % ace


def _priv_is_admin():
    """当前进程是否为管理员（icacls 不可用时用于保守降级）。"""
    try:
        if os.name != "nt":
            return False
        import ctypes
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False


def _priv_dir_writable(icacls_text, d):
    """目录对普通用户是否可写：优先 icacls 判定；不可用时退回 os.access 等价判断。"""
    state, why = _priv_acl_verdict(icacls_text, d)
    if state != "unknown":
        return state, "icacls: %s" % why
    if _priv_is_admin():
        return "unknown", "%s；当前为管理员，os.access 不能代表普通用户 → 需人工确认" % why
    try:
        ok = os.access(d, os.W_OK)
    except Exception:
        ok = False
    if ok:
        # Windows 下 os.access 只看只读属性、不校验 ACL：True 不能证明可写 → 保守记为无法确认
        return "unknown", "%s；icacls 不可用，os.access(%s, W_OK)=True 不能证明 ACL 可写 → 需人工确认" \
            % (why, d)
    return "not", "%s；icacls 不可用，退回 os.access(%s, W_OK)=False" % (why, d)


def _priv_already_reported(c, *names):
    """去重：既有「服务自启动 / 计划任务」结论里已出现同一对象（服务名/任务名/exe 路径）→ True。"""
    want = [str(n).strip().lower() for n in names if str(n or "").strip()]
    want = [w for w in want if len(w) >= 3]
    if not want:
        return False
    for f in c.findings:
        if f.category not in _PRIV_DEDUP_CATS:
            continue
        blob = " ".join([f.title, f.detail] + [str(x) for x in f.evidence]).lower()
        for w in want:
            if w in blob:
                return True
    return False


def _priv_service_rows(c):
    """枚举 Windows 服务（与 win_services 同源同法，只读；失败 warn 并返回空表）。"""
    rows, raw = wmic_csv("service get Name,DisplayName,PathName,StartMode")
    if not rows:
        rows, raw = ps_csv("Get-CimInstance Win32_Service | Select-Object Name,PathName,StartMode "
                           "| ConvertTo-Csv -NoTypeInformation")
    if not rows:
        c.warn("提权面：未能枚举服务（wmic 与 PowerShell 均失败），未引用服务路径检查未完成")
        return []
    c.raw_add("提权面-服务清单", "wmic service get Name,PathName,StartMode / Get-CimInstance Win32_Service", raw)
    return rows


def _priv_unquoted_services(c, rows):
    """§P0-5：未引用服务路径 + 逐级目录可写性判定（各级均可写 → 高危；否则中危待人工确认）。"""
    cat = "提权面"
    if not rows:
        return
    high, mid, skipped = [], [], []
    acl_cache = {}      # 同一目录只跑一次 icacls（多服务常共享父目录）
    for r in rows:
        name = (r.get("Name") or "").strip()
        path = (r.get("PathName") or "").strip()
        exe = _priv_unquoted_exe(path)
        if not exe or not name:
            continue
        if _priv_already_reported(c, name, exe):
            skipped.append(name)
            continue
        dirs = _priv_parent_dirs(exe)
        verdicts = []
        for d in dirs:
            key = d.lower()
            if key not in acl_cache:
                out, _ = win_cmd(["icacls", d], timeout=60)
                acl_cache[key] = _priv_dir_writable(out, d)
            verdicts.append((d,) + acl_cache[key])
        head = "服务=%s；ImagePath=%s" % (name, path[:300])
        ev = [head]
        for d, st, why in verdicts:
            ev.append("icacls \"%s\" → %s（%s）" % (
                d, {"writable": "普通用户可写", "not": "普通用户不可写",
                    "unknown": "无法确认"}.get(st, st), why[:220]))
        ev.append("核对命令: sc qc %s；icacls \"%s\"" % (name, os.path.dirname(exe) or exe))
        if verdicts and all(st == "writable" for _, st, _ in verdicts):
            high.append(ev)
        else:
            ev.append("逐级判定: " + "，".join(
                "%s=%s" % (d, {"writable": "可写", "not": "不可写", "unknown": "无法确认"}.get(st, st))
                for d, st, _ in verdicts))
            mid.append(ev)
    if high:
        c.add("高危", cat, "存在未引用服务路径且各级目录对普通用户可写（可本地提权）",
              detail="共 %d 个服务：\n%s" % (len(high), "\n".join(ev[0] for ev in high[:20])),
              evidence=[x for ev in high for x in ev][:200],
              advice="Windows 启动这类服务时会按空格逐级尝试路径，普通用户可在可写目录投放同名程序劫持。"
                     "处置：sc qc <服务名> 核对后，把 ImagePath 改为带引号的完整路径（先取证再变更）。")
    if mid:
        c.add("中危", cat, "存在未引用服务路径（需人工确认注入点目录权限）",
              detail="共 %d 个服务：\n%s" % (len(mid), "\n".join(ev[0] for ev in mid[:20])),
              evidence=[x for ev in mid for x in ev][:200],
              advice="存在未引用路径但未能确认各级目录对普通用户可写；按证据中的 icacls 逐级核对，"
                     "只要有一级可写即可被用于提权。修复方式同：ImagePath 加引号。")
    if not high and not mid:
        c.add("提示", cat, "未发现未引用服务路径（共检查 %d 个服务）" % len(rows),
              evidence=["核对命令: wmic service get Name,PathName,StartMode",
                        "判据: ImagePath 无引号、含空格、且可执行体路径内存在空格"])
    if skipped:
        c.raw_add("提权面-未引用路径去重跳过", "c.findings 中「服务自启动」已报过同名/同路径对象",
                  "\n".join(skipped[:100]))


def _priv_always_install_elevated(c):
    """§P0-5：AlwaysInstallElevated（HKLM+HKCU 同时为 1 → 高危；仅其一 → 提示）。"""
    cat = "提权面"
    key = r"SOFTWARE\Policies\Microsoft\Windows\Installer"
    state, lines = {}, []
    for hive in ("HKLM", "HKCU"):
        full = hive + "\\" + key
        out, _ = win_cmd(["reg", "query", full, "/v", "AlwaysInstallElevated"], timeout=60)
        txt = (out or "").strip()
        lines.append("reg query \"%s\" /v AlwaysInstallElevated → %s"
                     % (full, (txt.splitlines()[-1].strip() if txt else "(无输出)")))
        m = re.search(r"(?i)AlwaysInstallElevated\s+REG_DWORD\s+0x([0-9a-f]+)", txt)
        if m:
            state[hive] = 1 if int(m.group(1), 16) == 1 else 0
        elif txt and re.search(r"(?i)(找不到|not find|cannot find|错误|error)", txt):
            state[hive] = "none"
        else:
            state[hive] = "err"
            c.warn("提权面：AlwaysInstallElevated 读取失败/为空（%s），该键未完成" % full)
    h, u = state.get("HKLM"), state.get("HKCU")
    if h == 1 and u == 1:
        c.add("高危", cat, "AlwaysInstallElevated 在 HKLM 与 HKCU 同时启用（任意用户可用 MSI 提权）",
              detail="HKLM=1，HKCU=1（两处同时置 1 时 msiexec 安装任意 MSI 会以 SYSTEM 执行）",
              evidence=lines,
              advice="把 HKLM/HKCU 两处的 AlwaysInstallElevated 置 0 或删除该键值，并核查是哪条组策略下发的；"
                     "处置前先固定注册表导出作为证据。")
    elif h == 1 or u == 1:
        c.add("提示", cat, "AlwaysInstallElevated 仅单侧为 1（未构成提权条件，建议核对来源）",
              detail="；".join("%s=%s" % (k, v) for k, v in sorted(state.items())),
              evidence=lines, advice="单侧启用不满足提权条件；确认是否为组策略遗留配置。")
    elif "err" in (h, u):
        return      # 读取失败已 warn，避免误报“未启用”
    else:
        c.add("提示", cat, "未启用 AlwaysInstallElevated（HKLM/HKCU 均未置 1）",
              evidence=lines)


def _priv_failureactions_binary(data):
    """解析 FailureActions 二进制里的恢复命令行（UTF-16LE，偏移相对结构起点）。"""
    if not data or len(data) < 20:
        return ""
    try:
        import struct
        cmd_off = struct.unpack_from("<I", data, 8)[0]
    except Exception:
        return ""
    if cmd_off in (0, 0xFFFFFFFF) or cmd_off >= len(data):
        return ""
    try:
        s = data[cmd_off:].decode("utf-16-le", "ignore")
    except Exception:
        return ""
    return s.split("\x00")[0].strip()


def _priv_failure_service_names():
    """列出配置了 FailureActions/FailureCommand 的服务名；返回 (names, 来源说明, err)。"""
    try:
        import winreg
    except Exception as e:
        return [], "", "winreg 不可用: %s" % e
    names = []
    try:
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SYSTEM\CurrentControlSet\Services") as root:
            i = 0
            while True:
                try:
                    nm = winreg.EnumKey(root, i)
                except OSError:
                    break
                i += 1
                try:
                    with winreg.OpenKey(root, nm) as sk:
                        j = 0
                        hit = False
                        while True:
                            try:
                                vn, _, _ = winreg.EnumValue(sk, j)
                            except OSError:
                                break
                            j += 1
                            if vn.lower() in ("failureactions", "failurecommand"):
                                hit = True
                                break
                        if hit:
                            names.append(nm)
                except Exception:
                    continue
    except Exception as e:
        return [], "", "读取服务注册表失败: %s" % e
    return names, "HKLM\\SYSTEM\\CurrentControlSet\\Services\\*\\FailureActions（winreg 枚举）", ""


def _priv_failureactions_command(name):
    """取服务失败恢复命令行：sc qfailure 优先（可核对）；失败退回注册表二进制解析。"""
    out, err = win_cmd(["sc", "qfailure", name], timeout=60)
    txt = out or ""
    if txt and not re.search(r"(?i)(指定的服务未安装|does not exist|拒绝访问|access is denied|"
                             r"失败|FAILED\s+\d+)", txt):
        return _priv_parse_qfailure(txt), "sc qfailure %s" % name, ""
    cmd2, src2 = "", ""
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                            r"SYSTEM\CurrentControlSet\Services\%s" % name) as sk:
            try:
                data, _ = winreg.QueryValueEx(sk, "FailureActions")
                cmd2 = _priv_failureactions_binary(data)
                src2 = "HKLM\\SYSTEM\\CurrentControlSet\\Services\\%s\\FailureActions（二进制解析）" % name
            except Exception as _e_r19:
                _degrade("_priv_failureactions_command", _e_r19)
    except Exception as e:
        err = err or str(e)
    if src2:
        return cmd2, src2, ""
    return "", "", (err or "无输出")


def _priv_parse_qfailure(text):
    """解析 sc qfailure 输出里的 COMMAND_LINE（纯函数）；空命令行返回空串。

    注意：只能用 [ \\t] 匹配行内空白——用 \\s 会跨行把下一个字段（FAILURE_ACTIONS）吞进来。
    """
    m = re.search(r"(?im)^[ \t]*(?:COMMAND_LINE|命令行)[ \t]*:[ \t]*(.*)$", text or "")
    return m.group(1).strip() if m else ""


def _priv_failureactions_hint(name):
    """预判该服务的失败恢复配置里是否有“运行程序”命令行（winreg 只读）。

    返回 True/False/None（None=无法判断，需要调用方按保守路径继续查）。
    Windows 默认给大量服务写的是“无操作(0)”动作，预判可避免对数百个服务逐个跑 sc。
    """
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                            r"SYSTEM\CurrentControlSet\Services\%s" % name) as sk:
            try:
                fc, _ = winreg.QueryValueEx(sk, "FailureCommand")
            except OSError:
                fc = ""
            if fc:
                return True
            try:
                data, _ = winreg.QueryValueEx(sk, "FailureActions")
            except OSError:
                data = b""
    except Exception:
        return None
    if not data or not isinstance(data, (bytes, bytearray)) or len(data) < 20:
        return None if data else False      # 读不到值→无法判断；空二进制按无命令行处理
    try:
        import struct
        cmd_off = struct.unpack_from("<I", data, 8)[0]
    except Exception:
        return None
    return False if cmd_off in (0, 0xFFFFFFFF) else True


def _priv_fail_verdict(cmd):
    """恢复命令行判据（纯函数）：返回 [(类型, 说明)]，类型 ∈ {临时/用户目录, 路径不存在}。"""
    p = (cmd or "").strip()
    if not p:
        return []
    exp = _priv_expand(p)
    out = []
    if _priv_temp_hit(exp):
        out.append(("临时/用户目录", exp[:300]))
    exe = _priv_exe_from_cmd(exp)
    if exe and re.match(r"(?i)^[a-z]:\\", exe):
        try:
            exists = os.path.exists(exe)
        except Exception:
            exists = True
        if not exists:
            out.append(("路径不存在", exe))
    return out


def _priv_service_failure_actions(c):
    """§P1-8：服务失败恢复动作（FailureActions）指向临时/用户目录或不存在路径 → 中危。"""
    cat = "提权面"
    names, src, err = _priv_failure_service_names()
    if err:
        out, _ = win_cmd(["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
                          "-Command",
                          "Get-ChildItem 'HKLM:\\SYSTEM\\CurrentControlSet\\Services' | "
                          "Where-Object { $_.Property -contains 'FailureActions' } | "
                          "ForEach-Object { $_.PSChildName }"], timeout=120)
        if out and out.strip():
            names, src, err = [x.strip() for x in out.splitlines() if x.strip()], \
                "PowerShell 枚举（winreg 不可用兜底）", ""
            c.raw_add("提权面-失败恢复服务清单(PS兜底)", "Get-ChildItem HKLM:\\SYSTEM\\...\\Services", out)
    if err:
        c.warn("提权面：服务失败恢复检查未完成（注册表与命令均读取失败: %s）" % str(err)[:200])
        return
    if not names:
        c.add("提示", cat, "未发现配置了失败恢复动作的服务",
              evidence=["已检查键: HKLM\\SYSTEM\\CurrentControlSet\\Services\\*\\FailureActions",
                        "核对命令: reg query \"HKLM\\SYSTEM\\CurrentControlSet\\Services\" /s /f FailureActions"])
        return
    hits, unread, skipped, scanned, with_cmd, rawlines, capped = [], [], [], 0, 0, [], 0
    sc_tries, sc_budget = 0, 80   # 兜底上限：winreg 不可用时避免对数百个服务逐个跑 sc（正常路径不触发）
    for name in names:
        if _priv_already_reported(c, name):
            skipped.append(name)
            continue
        hint = _priv_failureactions_hint(name)
        if hint is False:
            continue        # 默认“无操作”动作，无命令行可指向路径
        if hint is None and sc_tries >= sc_budget:
            capped += 1
            continue
        sc_tries += 1
        cmd, got_src, e = _priv_failureactions_command(name)
        if e:
            unread.append("%s: %s" % (name, str(e)[:120]))
            continue
        scanned += 1
        if not cmd:
            continue
        with_cmd += 1
        rawlines.append("[%s] 来源=%s COMMAND_LINE=%s" % (name, got_src, cmd[:300]))
        verdicts = _priv_fail_verdict(cmd)
        if verdicts:
            hits.append("服务=%s；恢复命令=%s；判定=%s；来源=%s；核对命令: sc qfailure %s"
                        % (name, cmd[:300], "、".join(k for k, _ in verdicts), got_src, name))
    if rawlines:
        c.raw_add("提权面-服务失败恢复", "sc qfailure <服务名> / FailureActions", "\n".join(rawlines[:200]))
    if hits:
        c.add("中危", cat, "服务失败恢复动作指向临时/用户目录或不存在路径（需人工确认）",
              detail="共 %d 个服务：\n%s" % (len(hits), "\n".join(hits[:20])),
              evidence=hits[:100],
              advice="失败恢复命令由服务控制管理器以服务账号（常为 SYSTEM）启动。核对 sc qfailure <服务名>，"
                     "非业务/异常路径用 sc failure <服务名> reset=0 actions=none 重设或清除（先取证）。")
    else:
        c.add("提示", cat, "服务失败恢复未发现指向临时/用户目录或不存在路径",
              detail="配置了失败恢复的服务 %d 个；含“运行程序”命令行 %d 个；已逐条核对 %d 个"
                     % (len(names), with_cmd, scanned),
              evidence=["核对命令: sc qfailure <服务名>",
                        "服务清单来源: %s" % src])
    if skipped:
        c.raw_add("提权面-失败恢复去重跳过", "c.findings 中「服务自启动」已报过同名服务",
                  "\n".join(skipped[:100]))
    if unread:
        c.warn("提权面：%d 个服务的失败恢复配置未能读取（sc qfailure 与注册表均失败/权限不足），例: %s"
               % (len(unread), "；".join(unread[:5])))
    if capped:
        c.warn("提权面：失败恢复按 sc 核对上限 %d 执行，另有 %d 个服务未核对（注册表读取不可用时的兜底限制）"
               % (sc_budget, capped))


def _priv_read_task_xml(path, limit=262144):
    """读取任务定义文件（支持 UTF-16 BOM）；失败返回空串。"""
    try:
        with open(path, "rb") as f:
            b = f.read(limit)
    except Exception:
        return ""
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        try:
            return b.decode("utf-16")
        except Exception as _e_r19:
            _degrade("_priv_read_task_xml", _e_r19)
    return decode_bytes(b)


def _priv_task_file(name):
    """按任务名拼磁盘任务定义文件路径（%SystemRoot%\\System32\\Tasks\\...）。"""
    rel = (name or "").strip().strip("\\")
    if not rel:
        return ""
    root = os.path.join(os.environ.get("SystemRoot") or r"C:\Windows", "System32", "Tasks")
    return os.path.join(root, *[x for x in rel.split("\\") if x])


def _priv_task_xml(name, hint_path=""):
    """取任务 XML：schtasks /query /tn <name> /xml 优先，失败退回磁盘任务定义文件。"""
    out, _ = win_cmd(["schtasks", "/query", "/tn", name, "/xml"], timeout=60)
    txt = out or ""
    if "\x00" in txt and "<Task" not in txt:      # UTF-16 原样输出时做一次补救解码
        try:
            txt = txt.encode("latin-1", "ignore").decode("utf-16-le", "ignore")
        except Exception as _e_r19:
            _degrade("_priv_task_xml", _e_r19)
    if "<Task" in txt:
        return txt, "schtasks /query /tn \"%s\" /xml" % name
    for p in (hint_path, _priv_task_file(name)):
        if p and os.path.isfile(p):
            t = _priv_read_task_xml(p)
            if "<Task" in t:
                return t, p
    return "", ""


def _priv_task_xml_flags(xml):
    """解析任务 XML 关键事实（纯函数）：Hidden / 启用状态 / 触发器 / 动作 / 编码命令。"""
    x = xml or ""
    flags = {"hidden": bool(re.search(r"(?i)<Hidden>\s*true\s*</Hidden>", x)),
             "enabled": not bool(re.search(r"(?i)<Enabled>\s*false\s*</Enabled>", x)),
             "triggers": [], "trigger_count": 0, "action": "", "temp_action": False,
             "encoded": False, "hits": [], "hidden_frag": ""}
    m = re.search(r"(?i)<Hidden>\s*true\s*</Hidden>", x)
    if m:
        flags["hidden_frag"] = _priv_flat(x[max(0, m.start() - 20):m.end() + 10], 80)
    trig = re.findall(r"(?i)<(BootTrigger|LogonTrigger|IdleTrigger|TimeTrigger|CalendarTrigger|"
                      r"EventTrigger|RegistrationTrigger|SessionStateChangeTrigger)\b", x)
    flags["triggers"] = sorted(set(t.lower() for t in trig))
    flags["trigger_count"] = len(trig)
    cmds = re.findall(r"(?i)<(?:Command|Arguments|WorkingDirectory)>\s*([^<]*)</", x)
    flags["action"] = _priv_flat(" ".join(c.strip() for c in cmds if c.strip()), 400)
    flags["temp_action"] = _priv_temp_hit(flags["action"])
    flags["hits"] = match_rules(x, SUSPICIOUS_CMDLINE_PATTERNS)
    flags["encoded"] = _PRIV_ENC_DESC in flags["hits"]
    return flags


def _priv_enc_fragment(text):
    """截取编码命令附近的 XML 片段，作为可核对证据。"""
    m = re.search(SUSPICIOUS_CMDLINE_PATTERNS[0][0], text or "", re.I)
    if not m:
        return ""
    return _priv_flat(text[max(0, m.start() - 40):m.end() + 10], 160)


def _priv_hidden_scan():
    """隐藏任务双来源扫描（PowerShell + 磁盘任务定义文件）。返回 (found, raw, errs, meta)。"""
    found, raw, errs = {}, [], []
    ps_ok = False
    out, _ = win_cmd(["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
                      "-Command",
                      "Get-ScheduledTask -ErrorAction SilentlyContinue | "
                      "Where-Object { $_.Settings -and $_.Settings.Hidden } | "
                      "Select-Object TaskName,TaskPath | ConvertTo-Csv -NoTypeInformation"], timeout=120)
    if out and "TaskName" in out:
        ps_ok = True
        raw.append(("提权面-隐藏任务(PowerShell)", "Get-ScheduledTask Settings.Hidden", out))
        for r in parse_csv_table(out):
            nm = (r.get("TaskName") or "").strip()
            pa = (r.get("TaskPath") or "").strip().strip("\\")
            if nm:
                found.setdefault("\\" + (pa + "\\" + nm if pa else nm),
                                 ("Get-ScheduledTask Settings.Hidden 命中", ""))
    else:
        errs.append("PowerShell Get-ScheduledTask 隐藏任务查询不可用/无结果")
    root = os.path.join(os.environ.get("SystemRoot") or r"C:\Windows", "System32", "Tasks")
    scanned = failed = 0
    dir_ok = False
    if os.path.isdir(root):
        for dirpath, _dirnames, filenames in os.walk(root):
            for fn in filenames:
                if scanned >= 4000:
                    break
                p = os.path.join(dirpath, fn)
                scanned += 1
                t = _priv_read_task_xml(p, limit=131072)
                if not t:
                    failed += 1
                    continue
                if re.search(r"(?i)<Hidden>\s*true\s*</Hidden>", t):
                    rel = os.path.relpath(p, root).replace(os.sep, "\\")
                    found.setdefault("\\" + rel, ("任务目录文件: %s" % p, p))
            if scanned >= 4000:
                break
        dir_ok = scanned > 0 and failed < scanned
        raw.append(("提权面-任务目录扫描", root,
                    "扫描文件=%d；读取失败=%d；Hidden=true 命中=%d" % (scanned, failed, len(found))))
    else:
        errs.append("任务定义目录不存在: %s" % root)
    meta = {"ps_ok": ps_ok, "dir_ok": dir_ok, "root": root, "scanned": scanned, "failed": failed}
    return found, raw, errs, meta


def _priv_hidden_tasks(c):
    """§P1-8：隐藏/异常计划任务（Hidden / 无触发器 / 空闲·登录+临时目录 / XML 编码命令）。"""
    cat = "提权面"
    found, raw, errs, meta = _priv_hidden_scan()
    for t, s, o in raw:
        c.raw_add(t, s, o)
    if not found and not meta["ps_ok"] and not meta["dir_ok"]:
        c.warn("提权面：隐藏任务扫描未完成（PowerShell 与任务目录均不可用）——%s" % "；".join(errs[:3]))
    cands, seen = [], set()
    for nm, (src, path) in sorted(found.items())[:_PRIV_MAX_HIDDEN]:
        cands.append((nm, path, src, True))
        seen.add(nm.lower())
    out, _ = win_cmd(["schtasks", "/query", "/fo", "csv", "/v"], timeout=180)
    n_extra = 0
    if out:
        for r in parse_csv_table(out):
            run = (r.get("Task To Run") or r.get("要运行的任务") or "").strip()
            nm = (r.get("TaskName") or r.get("任务名") or "").strip()
            if not nm or len(cands) >= _PRIV_MAX_TASK_XML:
                continue
            if nm.lower() in seen:
                continue
            low = run.lower()
            unreadable = (not run) or run.upper() == "N/A" or "com handler" in low \
                or "com 处理程序" in low
            if not unreadable or _priv_already_reported(c, nm):
                continue
            cands.append((nm, "", "CSV 动作不可读（win_tasks 跳过）", False))
            seen.add(nm.lower())
            n_extra += 1
            if n_extra >= 8:
                break
    hidden_hits, notrig_hits, idle_hits, enc_hits, skipped, xml_fail = [], [], [], [], [], []
    checked = 0
    for nm, hint, src, is_hidden in cands:
        if _priv_already_reported(c, nm):
            skipped.append(nm)
            continue
        xml, got_src = _priv_task_xml(nm, hint)
        if not xml:
            xml_fail.append(nm)
            continue
        checked += 1
        fl = _priv_task_xml_flags(xml)
        base = ("任务=%s；Hidden=%s；启用=%s；触发器=%s；动作=%s；核对命令=%s；来源=%s"
                % (nm, "true" if fl["hidden"] else ("见文件" if is_hidden else "false"),
                   fl["enabled"], ",".join(fl["triggers"]) or "无", fl["action"][:200] or "(空)",
                   "schtasks /query /tn \"%s\" /xml" % nm, got_src))
        if fl["encoded"]:
            enc_hits.append(base + "；命中=%s；XML片段=%s"
                            % ("、".join(fl["hits"]), _priv_enc_fragment(xml)))
        elif fl["hidden"] or is_hidden:
            hidden_hits.append(base + ("；Hidden片段=%s" % fl["hidden_frag"][:80] if fl["hidden_frag"] else ""))
        elif fl["enabled"] and fl["trigger_count"] == 0:
            notrig_hits.append(base)
        elif fl["trigger_count"] and set(fl["triggers"]) <= {"idletrigger", "logontrigger"} \
                and fl["temp_action"]:
            idle_hits.append(base)
    if enc_hits:
        c.add("高危", cat, "计划任务 XML 动作含 PowerShell 编码命令（隐藏/异常任务专项）",
              detail="共 %d 个任务：\n%s" % (len(enc_hits), "\n".join(enc_hits[:20])),
              evidence=enc_hits[:100],
              advice="编码命令常用于无文件落地执行。核对 schtasks /query /tn <任务名> /xml 与任务作者，"
                     "非业务任务用 schtasks /delete /tn \"<任务名>\" /f 删除（先取证）。")
    if hidden_hits:
        hidden_total = len(found)
        c.add("中危", cat, "发现隐藏计划任务（Hidden=true，需人工确认）",
              detail="共发现 %d 个隐藏任务，本次复核前 %d 个（按名称序）：\n%s"
                     % (hidden_total, len(hidden_hits), "\n".join(hidden_hits[:20])),
              evidence=(["隐藏任务总数=%d；完整清单见附录『提权面-隐藏任务(PowerShell)』"
                         "（本轮按上限复核前 %d 个）" % (hidden_total, len(hidden_hits))]
                        + hidden_hits)[:100],
              advice="隐藏任务在任务计划程序中默认不可见，常用于持久化。核对作者/创建时间/动作路径，"
                     "非业务任务先导出 XML 取证再删除。")
    if notrig_hits:
        c.add("中危", cat, "发现启用中但无触发器的计划任务（需人工确认）",
              detail="共 %d 个任务：\n%s" % (len(notrig_hits), "\n".join(notrig_hits[:20])),
              evidence=notrig_hits[:100],
              advice="正常计划任务都有触发器；无触发器的启用任务可能由其它程序/服务直接调用。"
                     "核对是否为业务软件设计，非业务建议禁用并取证。")
    if idle_hits:
        c.add("中危", cat, "计划任务仅空闲/登录触发且动作位于临时/用户目录（需人工确认）",
              detail="共 %d 个任务：\n%s" % (len(idle_hits), "\n".join(idle_hits[:20])),
              evidence=idle_hits[:100],
              advice="空闲/登录触发隐蔽性高，配合临时/用户目录动作高度可疑；核对任务作者与文件来源后处置。")
    if not (enc_hits or hidden_hits or notrig_hits or idle_hits):
        c.add("提示", cat, "未发现隐藏/异常计划任务（已复核 %d 个任务）" % checked,
              evidence=["核对命令: schtasks /query /tn \"<任务名>\" /xml；Get-ScheduledTask Settings.Hidden",
                        "任务定义目录: %s（扫描 %d 个文件）" % (meta["root"], meta["scanned"]),
                        "判据: Hidden=true / 启用且无触发器 / 仅空闲·登录触发且动作在临时·用户目录 / XML 编码命令"])
    if skipped:
        c.raw_add("提权面-任务去重跳过", "c.findings 中「计划任务」已报过同名任务",
                  "\n".join(skipped[:100]))
    if xml_fail:
        c.warn("提权面：%d 个候选任务的 XML 无法读取（schtasks /xml 与任务文件均失败/权限不足）：%s"
               % (len(xml_fail), "，".join(xml_fail[:5])))


def win_priv_esc(c):
    """【新增】Windows 提权面：未引用服务路径 / AlwaysInstallElevated / 服务失败恢复 / 隐藏·异常计划任务。

    依据：test.md §P0-5、§P1-8。全部只读；与 win_services()/win_tasks() 的既有结论去重
    （同一服务名/任务名/路径不重复上报）。任一子项失败只 warn，不影响其它子项继续执行。
    """
    for label, fn in (("AlwaysInstallElevated", lambda: _priv_always_install_elevated(c)),
                      ("未引用服务路径与失败恢复", lambda: _priv_services_surface(c)),
                      ("隐藏/异常计划任务", lambda: _priv_hidden_tasks(c))):
        try:
            fn()
        except Exception as e:
            c.warn("提权面「%s」异常: %s" % (label, e))


def _priv_services_surface(c):
    """服务相关两个子项：未引用路径 + 失败恢复（共用一次服务枚举）。"""
    rows = _priv_service_rows(c)
    _priv_unquoted_services(c, rows)
    _priv_service_failure_actions(c)


class CheckStep(tuple):
    """检查步骤（R15/B2：步骤表从裸二元组升级为带元数据的步骤对象）。

    仍是长度 2 的不可变元组：step[0]=显示名、step[1]=runner，因此
    `for i, (name, fn) in enumerate(steps, 1)`、`dict(steps)`、自检里的
    「isinstance(tuple) / len==2 / str / callable」契约逐字继续成立；
    附加信息只走属性（name/runner/doc/round_name），不改变既有解包与比较口径。
    """

    def __new__(cls, name, runner, doc="", round_name=""):
        self = tuple.__new__(cls, (name, runner))
        self.name = name
        self.runner = runner
        self.doc = doc
        self.round_name = round_name
        return self


# Windows 检查项（顺序即 UI 进度条顺序）：CheckStep(显示名, 调用方式[, 说明, 轮次])
