    CheckStep("事件日志分析", lambda c, o: win_logs(c)),
    CheckStep("深度事件日志(PS脚本块/Sysmon/WMI活动/任务计划/Defender/RDP/防火墙)",
              lambda c, o: win_logs_advanced(c)),
    CheckStep("安全日志增强(登录类型统计/特权与显式凭据/Kerberos票据/共享访问/DCSync/日志清空)",
              lambda c, o: win_security_advanced(c)),
    CheckStep("WMI 事件订阅持久化", lambda c, o: win_wmi_subscription(c)),
