# 命令行分隔符（cmd 与 bash 语义相同；PowerShell 同用 ; 与 |）：先切段、段内再切词元。
_R19_ATTR_SEP_RE = re.compile(r"&&|\\\\|[;&|]")
_R19_ATTR_SEG_RE = re.compile(r"\S+")        # 含引号的词元整体保留


def _attr_seg_spans(seg):
    """一条命令行片段 -> [(词元值, 词元在整行中的起始下标)]（R19/P1，纯函数）。"""
    out = []
    for m in _R19_ATTR_SEG_RE.finditer(seg):
        v = m.group(0)
        i = 0
        while i < len(v) and v[i] in "&|;" + chr(34) + chr(39):
            i += 1
        v = v[i:].strip(chr(34) + chr(39))
        if v:
            out.append((v, m.start() + i))
    return out


def _attr_cmd_segs(cmd):
    """命令行 -> 片段序列（R19/P1，纯函数）：先按分隔符切段，再在段内切词元，
    供「最靠前命中」定位。解析失败退化为整行一个片段，绝不因此漏判型。"""
    raw = str(cmd or "")
    if not raw:
        return []
    segs = []
    for seg in _R19_ATTR_SEP_RE.split(raw):
        if seg and seg.strip():
            segs.extend(_attr_seg_spans(seg))
    return segs or [(raw, 0)]


def _r19vkey(spec, tok):
    """命中的词元 -> 可读动词键（R19/P1，纯函数）：动作自成词元时直接取该词（reg add -> add），
    动作与命令同词元时取到动作起点为止（Get-ItemProperty -> Get-ItemProperty）。"""
    tok = str(tok or "")
    if spec[0].pattern == spec[1].pattern:
        return tok.strip("-").lower()          # 自含动词：命令词元即动词
    tok = tok.strip("-")
    if spec[1].search(tok) and not spec[0].search(tok):
        return tok.lower()                      # 动作自成词元（reg add -> add）
    hits = [(m.start(), m.end()) for m in spec[1].finditer(tok)]
    return tok[:hits[0][1]].strip("-").lower() if hits else tok.lower()


def _attr_cmd_first_verb(cmd):
    """命令行 -> (动词表项, 动作词元起始下标, 命中的动作词)（R19/P1，纯函数）。

    取「最靠前」= 需求书 P1 要求 2 的实现口径：同一条命令行含多个动作时按该行最靠前的写动词判定
    （reg query X && reg add X 判读型；reg add X && reg query X 判写型）。判定方式为「相邻词元对」：
    命令词元（reg / schtasks / sc / wevtutil / Get-ItemProperty …）后紧跟动作词元才算命中，位置取
    动作词元下标；同位置时写型表整体优先（两张表拼接顺序即优先级）。都不命中 -> (None, -1, "")。
    """
    toks = _attr_cmd_segs(cmd)
    if not toks:
        return None, -1, "", ""
    best, bpos, bkey, bkind, _bspan = None, -1, "", "", 0
    for _tbl in _R19_ATTR_WRITE_VERBS + _R19_ATTR_READ_VERBS:
        _kind = _tbl[0]
        for _entry in _tbl[1]:
            _cmd_re, _act_re, _gates, _self = _entry[0], _entry[1], _entry[2], _entry[3]
            for idx in range(len(toks)):
                tok, pos = toks[idx]
                _cut = max(tok.rfind(chr(92)), tok.rfind(chr(47)))
                _comp = tok[_cut + 1:]
                _cm = _cmd_re.search(_comp)
                if not _cm or _cm.start() != 0:
                    continue
                if _self:
                    _pos2, _tok2 = pos, tok
                elif idx + 1 < len(toks):
                    _tok2, _pos2 = toks[idx + 1]
                    if not _act_re.search(_tok2):
                        continue
                else:
                    continue
                # 同一起始下标时「更长的命令词」优先，避免 sc 抢先命中 schtasks
                if bpos < 0 or _pos2 < bpos or (_pos2 == bpos and _cm.end() > _bspan):
                    best, bpos, bkey, bkind = _entry, _pos2, _entry[4], _kind
                    _bspan = _cm.end()
    return best, bpos, bkey, bkind


def _attr_verb_class(cmd):
    """命令行 -> "write" / "read" / ""（R19/P1 动词分档，纯函数）。扩展方式见两张表头注释。

    判定顺序（需求书 P1 要求 1/2）：
      1) 取本行最靠前的命中动词（_attr_cmd_first_verb）；
      2) 目标门控（表项第 3 元素，如 copy 写到启动目录）非空时，要求命令行通过门控，
         否则该项不成立——按「动词未识别」处理；
      3) 两张表都不命中 -> 返回空串（调用方按「动词未识别，不予采信」处理）。
    """
    spec, _pos, _key, _kind = _attr_cmd_first_verb(cmd)
    if spec is None:
        return ""
    if spec[2]:
        low = _r19_cmd_low(cmd)
        if not any(g(low) for g in spec[2] if callable(g)):
            return ""
    return _kind


def _attr_single_side_exclude_reason(info):
    """全部候选均非写型时给出显式排除理由（R19/P1 要求 3，纯函数）。

    口径：读型/审计型动作只说明「该进程读过这个条目」，不构成创建证据；动词未识别的条目按
    「不计入」处理且写明「动词未识别，不予采信」。绝不退回「疑似」，也绝不沉默。
    """
    items = list((info or {}).get("matches") or [])
    if not items:
        return ""
    read = [h for h in items if not h.get("unk")]
    unk = [h for h in items if h.get("unk")]
    head = "命中 %d 条进程命令行" % len(items)
    parts = []
    if read:
        sample = "、".join((h.get("verb_name") or _adv_trunc(h.get("frag"), 60) or "（未识别）")
                           for h in read[:2])
        parts.append(("全部为读取/审计型（示例：%s）" % sample) if not unk
                     else ("%d 条为读取/审计型（示例：%s）" % (len(read), sample)))
    if unk:
        parts.append("%d 条动词未识别，不予采信" % len(unk))
    return "%s，%s，不予采信" % (head, "；".join(parts))


def _attr_single_side_scan(pool_index, values, limit=_R18_ATTR_SINGLE_MAX, want_info=False):
    """单侧证据扫描（R18/P1 + R19/P1）：进程索引 × 干净强值 -> [命中 hit]（纯函数）。

    R18/P1 原口径（保留）：值与进程 CommandLine 的完整词元（另允许词元尾段/去扩展名尾段两级精确
    写法）相等，或与进程 Image 可执行名相等，才算命中；禁止任何子串式泛化；不命中返回空。

    R19/P1 增量（本轮机制层收口）：命中不再直接等于证据——还要看该进程对目标是写还是读：
      · 每条命令行命中按 _attr_verb_class 分出「写型 / 读型·审计型 / 动词未识别」；
      · 只采信写型；多候选按「素材池首见且带写动词」取一条（命令行内多动作由
        _attr_cmd_first_verb 的「最靠前」口径解决）；
      · 读型/审计型与动词未识别一律不采信，仅在 want_info 时随 info 返回，供调用方在证据段
        显式写出排除理由（只读动作不得当创建证据，但也不许沉默）。
    want_info=True 时返回 (写型证据 hit 或 None, info)：info 含 matches（非写型命中及其识别出的
    动词名/片段）、read_n、unk_n、write_hit、reason（排除理由文本）。
    """
    info = {"matches": [], "read_n": 0, "unk_n": 0, "write_hit": None, "reason": ""}
    if not pool_index or not values:
        return (None, info) if want_info else []
    clean = [v for v in values if v and not _attr_terms_is_generic(v)]
    if not clean:
        return (None, info) if want_info else []
    matches = []
    for ep, disp, d, cset, eset, cmd, img in pool_index:
        if len(matches) >= limit:
            break
        hit = None
        for v in clean:
            if v in cset:
                hit = _attr_hit(ep, disp, d, "CommandLine", v,
                                "精确（命令行完整词元/词元尾段相等）",
                                "单侧证据命中=%s" % v)
            elif v in eset:
                hit = _attr_hit(ep, disp, d, "Image", v, "精确（可执行名相等）",
                                "单侧证据命中=%s" % v)
            if hit is not None:
                break                   # 同一事件只取一条证据（首个命中的干净值）
        if hit is None:
            continue
        cls = _attr_verb_class(cmd)
        hit["verb"] = cls                 # 证据行据此写出「动词分档=写型」
        hit["verb_name"] = ""
        hit["frag"] = ""
        if cls != "write":
            spec, pos, vkey, _kk = _attr_cmd_first_verb(cmd)
            hit["verb_name"] = vkey
            if pos >= 0:
                for frag, fpos in _attr_cmd_segs(cmd):
                    if fpos <= pos:
                        hit["frag"] = frag
                    else:
                        break
            if hit["frag"] and (hit["frag"].strip("-").lower() == (vkey or "").lower()
                                or (vkey or "").lower().endswith( " " + hit["frag"].strip("-").lower())):
                hit["frag"] = vkey      # 片段与动词重名（reg query -> query）时用动词全名
            elif hit["frag"] and spec is not None:
                _f = hit["frag"].strip("-").lower()
                _vk = (vkey or "").lower()
                _f2 = _vk.split(chr(32))[-1] if chr(32) in _vk else ""
                if _f and _f == _f2:
                    hit["frag"] = _vk.rsplit(chr(32), 1)[0] + chr(32) + hit["frag"]
            if not hit["frag"]:
                hit["frag"] = _adv_trunc(cmd.strip(), 120)
            hit["pos"] = pos
            matches.append(hit)
            if cls == "read":
                info["read_n"] += 1
            continue
        # 写型：按「最早且带写动词」口径取第一条即收；返回形态与 R18 的列表口径逐条一致
        info["write_hit"] = hit
        info["matches"] = matches[:limit]
        return ([hit], info) if want_info else [hit]
    for h in matches:
        h["unk"] = not h.get("verb_name")
    matches.sort(key=lambda h: (h.get("pos", -1) < 0, h.get("pos", -1)))
    info["matches"] = matches[:limit]
    info["unk_n"] = len([h for h in matches if h.get("unk")])
    info["reason"] = _attr_single_side_exclude_reason(info)
    return (None, info) if want_info else []


def _attr_single_side_tag(direct_keys, src_notes):
    """单侧证据标注文案（R18/P1）：无创建事件源的实际状态清单。纯函数。"""
    parts = []
    for key in (direct_keys or ()):
        spec = _R16_ATTR_SRC_BY_KEY.get(key)
        label = spec[5] if spec else key
        note = src_notes.get(key) or ""
        if "不可用" in note:
            parts.append("%s 未启用/不可用" % label)
        elif "无事件" in note:
            parts.append("%s 无事件" % label)
        elif "截断" in note:
            parts.append("%s 取数被截断（可能漏档）" % label)
        elif "失败" in note:
            parts.append("%s 查询失败" % label)
        else:
            parts.append("%s 未命中" % label)
    if not parts:
        parts.append("直接创建事件源未命中")
    return _R18_ATTR_SINGLE_TAG % "；".join(parts)


def _attr_checked_fields_text(direct_keys, pool_label=""):
    """「无归因」时必须写清的已查源与已查字段清单（R18/P1 要求 3）。纯函数。"""
    parts = []
    for key in (direct_keys or ()):
        spec = _R16_ATTR_SRC_BY_KEY.get(key)
        rules = _attr_src_fields(key)
        if not spec or not rules:
            continue
        parts.append("%s[%s]" % (spec[5], "/".join(r[0] for r in rules)))
    parts.append("进程素材%s[Image/CommandLine（完整词元精确，单侧证据路径）]"
                 % (("（%s）" % pool_label) if pool_label else ""))
    return "；".join(parts)


def _attr_account(d):
    """事件自带创建者账户信息（P1 证据链优先）：返回 (账户, 来源字段)。纯函数。"""
    for f in ("SubjectUserName", "AccountName", "TargetUserName", "UserContext", "SubjectDomainName"):
        v = str(d.get(f) or "").strip()
        if v and v not in ("-", "SYSTEM"):
            return v, f
        if v == "SYSTEM":
            return v, f
    return "", ""


def _attr_verdict(proven, hits):
    """三态结论（R17/P1 三态，不允许第四种或空，纯函数）。

    已证实：创建事件自带创建者信息（Subject*/AccountName/域账户）——直接作为结论；
    疑似：只有进程素材时，命中进入「父子链 + 时间同窗」（PID/父 PID 与创建事件对齐）；
    无归因：证据不足——严禁给出创建者猜测。
    """
    strong = [h[1] for h in (hits or []) if h[1] == "strong"]
    if proven:
        return "已证实", strong
    if len(set(strong)) >= 2:
        return "疑似", strong
    return "无归因", strong


def _attr_verdict_lines(verdict, hits, direct_why, creator, note):
    """三态结论的可核细节（纯函数）。"""
    out = []
    if verdict == "已证实":
        out.append("  已证实依据：创建事件自带创建者信息 %s" % (direct_why or "（见证据行）"))
    elif verdict == "疑似":
        out.append("  疑似依据：创建事件与 %d 条同类强项命中（%s），时间同窗（锚点前 %d 秒 ~ 后 %d 秒）"
                   % (len(hits), "、".join(sorted(set(hits))) if hits else "无",
                      _R17_ATTR_BEFORE, _R17_ATTR_AFTER))
    if creator:
        out.append("  创建进程: %s" % _attr_proc_blob(creator[2]).strip())
        out.append("  创建进程来源: %s（%s；PID=%s；匹配字段=%s；匹配值=%s；相等方式=%s）"
                   % (creator[6] or "进程创建事件", creator[1], _attr_proc_ref(creator[2])[0],
                      creator[3], _adv_trunc(str(creator[4]), 120), creator[5]))
        if note:
            out.append("  创建进程特征: %s（可疑信号仅供研判；归因结论级别保持“提示”）" % note)
    return out


def _attr_jobid(d):
    """事件 → BITS 作业 GUID（取不到返回 ""）。纯函数。"""
    blob = " ".join(str(d.get(k) or "") for k in ("TargetObject", "Details", "CommandLine",
                                                  "ScriptBlockText", "CONSUMER"))
    return _attr_bits_jobid(blob)


def _attr_eff_mode(mode, fmode):
    """条目项相等方式与字段规则相等方式取严（纯函数）。

    字段规则本身是身份级（part/exact/task/svc/image/cmd）时以规则为准；规则是 path
    （目标路径/命令行中的路径）而条目项给的是 tail（路径尾段）时，仍按尾段判定。
    """
    if mode == "tail" and fmode == "path":
        return "tail"
    return mode or fmode


def _attr_scan_item(key, evs, terms, jobid="", id_fields=("TargetObject", "Details")):
    """单个事件源 × 条目匹配项 → [((命中, 强度, 源键))]。白名单字段限定，禁全字段包含。"""
    rules = _attr_src_fields(key)
    if not rules:
        return []
    out = []
    for ep, disp, d in (evs.get(key) or []):
        if not isinstance(d, dict):
            continue
        # BITS 作业 GUID：条目与事件双向精确相等（JobId 即身份，强证据）
        if jobid and any(_attr_bits_jobid(d.get(f) or "").lower() == jobid for f in id_fields):
            f = id_fields[0] if _attr_bits_jobid(d.get(id_fields[0]) or "") else id_fields[-1]
            out.append(((_attr_hit(ep, disp, d, f, jobid, "精确（BITS JobId 相等）",
                                   "命中=%s" % jobid), "strong", key)))
            continue
        for term, tfields, mode, strength in terms:
            for flt, fmode, _fstrength in rules:
                if tfields and flt not in tfields:
                    continue
                got = _attr_term_match(term, d, flt, _attr_eff_mode(mode, fmode), strength)
                if got:
                    out.append(((_attr_hit(ep, disp, d, flt, got["value"], got["mode"],
                                           "命中=%s" % term), strength, key)))
                    break
    return out


def _attr_dedup_hits(hits):
    """同一事件被多个源键复用时只留第一条（保持源键顺序；纯函数）。"""
    out, seen = [], set()
    for h in hits:
        d = h[0]["data"]
        sig = (h[0]["ep"], str(d.get("_RecordID") or ""), str(d.get("_EventID") or ""),
               h[0]["field"], str(h[0]["value"]))
        if sig in seen:
            continue
        seen.add(sig)
        out.append(h)
    return out


def win_persist_attribution(c):
    """持久化归因步骤（P1/R17）：消费 c.persist_items 与创建事件通道，逐条给出三态结论。

    三态（不允许第四种或空）：已证实 / 疑似 / 无归因；每条都给可核证据行（命中的事件
    EventID + 通道 + 记录时间 + EventRecordID、匹配字段名、匹配值、相等方式、与创建事件
    的时间差）。等级恒为「提示」（它解释创建过程，不改变条目本身级别）。

    数据源不可用/截断：随条目与汇总行显式声明；窗口跟随 --days（与其它事件检查一致）；
    档位（--fast / 默认）由「数据源与覆盖度」段声明。
    R18/P1 增量：条目无自身锚点（ts=0）且窗口内无直接创建事件时，走「单侧证据」路径——仍扫描
    进程素材池，命令行完整词元/映像名精确命中 ⇒ 「疑似」+ 单侧证据证据行；未命中 ⇒ 「无归因」
    并写明已查源与已查字段（见 _attr_single_side_values / _attr_single_side_scan）。
    """
    cat = "持久化归因"
    items = list(getattr(c, "persist_items", []) or [])
    if not items:
        c.add("提示", cat, "本轮未发现需要归因的持久化条目（0 条；未发现 ≠ 不存在，"
                           "数据源可用性见「数据源与覆盖度」段）")
        return
    need = set(_R16_ATTR_PROC_SOURCES)
    for item in items:
        keys = _R16_ATTR_DEFAULT_SOURCES
        for kind_set, src_keys in _R17_ATTR_KIND_SOURCES:
            if item.get("kind") in kind_set:
                keys = src_keys
                break
        need.update(keys)
    need = [s[0] for s in _R16_ATTR_SOURCES if s[0] in need]
    evs, src_notes, src_ok = {}, {}, {}
    days = max(1, int(getattr(c, "days", None) or DEFAULT_DAYS))
    win = _evt_scope(days)
    for key in need:
        spec = _R16_ATTR_SRC_BY_KEY[key]
        _k, channel, ids, cap, timeout, label = spec
        state = _r16_chan_state(c, channel)
        if state is not None and state.get("status") in ("missing", "denied", "unreadable"):
            evs[key], src_ok[key] = [], False
            src_notes[key] = "%s 不可用（%s）" % (label, state.get("detail"))
            continue
        got, why = _adv_query(c, channel, ids, win, count=cap, timeout=timeout,
                              label="归因-%s" % label, days=days)
        if got is None:
            evs[key], src_ok[key] = [], False
            if "上限" in (why or "") or "预算" in (why or ""):
                src_notes[key] = ("%s 取数被截断（%s）：本条目的创建过程可能在未覆盖时段内"
                                  % (label, why))
            else:
                src_notes[key] = "%s 查询失败（%s）" % (label, why or "未知原因")
            continue
        evs[key], src_ok[key] = got, True
        st = _r16_last_stat(c, channel, "归因-%s" % label)
        if st and st.get("truncated"):
            oldest = int(st.get("oldest") or 0)
            # R18/P3 文案修复：截断声明不得写含糊的「未知」——给实际值或「无法确定（原因）」。
            _span_txt = _r16_span_text(max(0, int(time.time()) - oldest)) if oldest else \
                "无法确定覆盖时长（该统计未记录最早事件时间）"
            _days_v = st.get("win_days")
            _days_txt = _r17_days_num(_days_v) if _days_v is not None else "无法确定（该查询未登记时间窗）"
            src_notes[key] = ("%s 已达取数上限 %d 条：实际覆盖 %s，未覆盖完整 %s 天窗口"
                              % (label, int(st.get("cap") or 0), _span_txt, _days_txt))
        elif not got:
            src_notes[key] = "%s 窗口内无事件（不能据此判定该创建过程不存在）" % label
    pool, pool_label = _attr_proc_pool(evs, src_ok)
    stat = {"已证实": 0, "疑似": 0, "无归因": 0}
    findings_n, omitted, summary_lines = 0, 0, []
    pool_index = None                    # R18/P1：进程素材词元索引（延迟构建，多处复用）
    for item in items:
        kind = item.get("kind") or "持久化"
        name = item.get("name") or item.get("target") or "(未命名)"
        terms = _attr_terms(item, kind)
        direct_keys = _R16_ATTR_DEFAULT_SOURCES
        for kind_set, src_keys in _R17_ATTR_KIND_SOURCES:
            if kind in kind_set:
                direct_keys = src_keys
                break
        anchor = int(item.get("ts") or 0)
        jobid = _attr_bits_jobid(item.get("reg") or item.get("target") or "").lower() \
            if kind == "BITS 任务" else ""
        hits = []
        for key in direct_keys:
            hits.extend(_attr_scan_item(key, evs, terms, jobid))
        hits = _attr_dedup_hits(hits)        # 同一事件被多个源键复用时只留一条证据行
        hits.sort(key=lambda h: (0 if h[1] == "strong" else 1,
                                 abs(h[0]["ep"] - anchor) if anchor else h[0]["ep"]))
        direct = None
        for h in hits:
            if h[1] == "strong":
                direct = (h[2], h[0])
                break
        account, account_field = ("", "")
        subj_pid = ""
        if direct is not None:
            _dd = direct[1]["data"]
            account, account_field = _attr_account(_dd)
            subj_pid = str(_dd.get("SubjectProcessId") or "").strip()
        creator = None
        proc_terms = _attr_process_terms(item, kind)
        proven = False
        direct_why = ""
        if account:
            proven = True
            direct_why = "%s=%s（字段 %s）" % ("账户", account, account_field)
        if direct is not None:
            creator = _attr_creator_from_direct(pool, direct[1]["ep"], subj_pid)
            if creator is not None:
                proven = True
            elif not account and not subj_pid:
                # 无自有创建者信息：只允许进程素材「父子链 + 时间同窗」（锚点 = 创建事件）
                creator = _attr_creator(pool, proc_terms, anchor=direct[1]["ep"], label=pool_label)
        if creator is None and not direct and anchor:
            # 无创建事件可对齐：条目自身锚点（文件时间等）时间同窗内同名进程
            creator = _attr_creator(pool, proc_terms, anchor=anchor, label=pool_label)
        # R18/P1 单侧证据：条目无自身锚点、且窗口内无直接创建事件时，仍扫描进程素材池。
        # 命中强项（命令行完整词元/映像名精确）⇒ 「疑似」+ 证据行；未命中 ⇒ 仍「无归因」。
        single_side = None
        single_side_checked = False
        pool_scanned = 0
        single_side = None            # R19/P1：只采信「带写动词」的单侧证据
        single_side_checked = False
        single_side_reason = ""       # 全部候选为读型/审计型/未识别时的显式排除理由
        single_side_n = 0
        pool_scanned = 0
        if creator is None and direct is None and not anchor:
            if pool_index is None:
                pool_index = _attr_pool_index(pool)
            single_side_checked = True
            pool_scanned = len(pool_index)
            # R19/P1：命中后按动词分档——写型（reg add / schtasks /create / Register-ScheduledTask …）
            # 才计入证据；读型/审计型（reg query / Get-ItemProperty / schtasks /query …）一律排除，
            # 但必须在证据段写出排除理由（取证者的只读动作不得被当创建证据，也不许沉默）。
            sh, _ss_info = _attr_single_side_scan(pool_index,
                                                  _attr_single_side_values(item, kind),
                                                  want_info=True)
            single_side_reason = _ss_info.get("reason") or ""
            single_side_n = len(_ss_info.get("matches") or [])
            if sh:
                single_side = sh[0]
                creator = (single_side["ep"], single_side["disp"], single_side["data"],
                           single_side["field"], single_side["value"], single_side["mode"],
                           pool_label, "strong")
        if subj_pid:
            direct_why = (direct_why + "；" if direct_why else "") + \
                "SubjectProcessId=%s（进程侧已对齐=%s）" % (subj_pid, "是" if creator else "否")
        verdict, strong_labels = _attr_verdict(proven, hits)
        if single_side is not None and verdict == "无归因":
            verdict = "疑似"        # R18/P1：单侧证据成立 ⇒ 疑似（不许升级为「已证实」）
        note = _attr_risk_note((creator[0], creator[1], creator[2],
                                creator[4]) if creator else None)
        detail = ["条目: [%s] %s" % (kind, _adv_trunc(name, 220))]
        if item.get("target") and item.get("target") != name:
            detail.append("  目标: %s" % _adv_trunc(item.get("target"), 220))
        if item.get("reg"):
            detail.append("  注册表: %s" % _adv_trunc(item.get("reg"), 200))
        detail.append("  匹配项（结构化）：%d 项（强 %d / 弱 %d）"
                      % (len(terms), len([t for t in terms if t[3] == "strong"]),
                         len([t for t in terms if t[3] == "weak"])))
        lines = []
        for h in hits[:6]:
            row, _eid = _attr_evidence_row(h[0], anchor)
            row += "；强度=%s；来源=%s" % ("强" if h[1] == "strong" else "弱（不得单独支撑结论）",
                                         _R16_ATTR_SRC_BY_KEY[h[2]][5])
            lines.append(row)
        detail.extend(lines)
        if single_side is not None:
            row, _eid = _attr_evidence_row(single_side, 0)
            detail.append("  " + _attr_single_side_tag(direct_keys, src_notes))
            detail.append(row + "；强度=强；来源=%s（%s）"
                          % (pool_label, "单侧证据，无创建事件可对齐"))
            detail.append("  创建进程: %s" % _attr_proc_blob(single_side["data"]).strip())
            detail.append("  " + _R18_ATTR_SINGLE_NOTE)
        else:
            detail.extend(_attr_verdict_lines(verdict, strong_labels, direct_why, creator, note))
        if not hits and single_side is None:
            detail.append("  证据行：无 —— 条目名/目标/注册表项与 %d 个事件源的白名单字段均未"
                          "精确命中（未命中 ≠ 不存在）" % len(direct_keys))
        if single_side is not None and verdict == "疑似":
            detail.append("  归因等级：疑似（单侧证据：仅进程侧命令行/映像名精确命中，"
                          "无创建事件源可对齐；需人工复核）")
        else:
            detail.append("  " + _R17_ATTR_VERDICT[_R17_ATTR_LEVELS.index(verdict)])
        if verdict == "无归因":
            notes = []
            for key in list(direct_keys) + list(_R16_ATTR_PROC_SOURCES):
                nt = src_notes.get(key)
                if nt and nt not in notes:
                    notes.append(nt)
            if notes:
                detail.append("  数据源说明: %s" % "；".join(notes[:4]))
            detail.append("  已查字段: %s" % _attr_checked_fields_text(direct_keys, pool_label))
            if single_side_reason:
                # R19/P1：命中的全是读型/审计型或动词未识别——显式给排除理由，不许沉默
                detail.append("  排除理由: %s" % single_side_reason)
            if single_side_checked:
                detail.append("  单侧证据扫描: 进程素材 %d 条 × 命令行完整词元/映像名精确匹配 = "
                              "%d 命中（未命中 ≠ 不存在；无命中不得猜测创建者）" % (pool_scanned, single_side_n))
            detail.append("  说明: 未查到创建记录 ≠ 不存在；精确归因需启用 Sysmon 12/13/14/1 与 "
                          "Security 进程创建审核(4688)；未给出创建者猜测。")
        stat[verdict] += 1
        if findings_n < _R16_ATTR_MAX_ITEMS:
            c.add("提示", cat, "持久化归因：[%s] %s（%s）" % (kind, _adv_trunc(name, 120), verdict),
                  detail="\n".join(detail[:12]), evidence=detail[:12],
                  advice="[%s] 归因只说明“谁在何时创建了这条持久化”，是否恶意请结合条目本身级别与创建"
                         "进程路径判断；核查命令：schtasks /query /v、sc qc、reg query、"
                         "Get-WmiObject -Namespace root\\subscription -Class __EventFilter。"
                         % verdict)
            findings_n += 1
        else:
            omitted += 1
        cimg = "?"
        if creator:
            cimg = str(creator[2].get("Image") or creator[2].get("NewProcessName") or "?")
        summary_lines.append("[%s] %s ← %s（%s）" % (kind, _adv_trunc(name, 80),
                                                    ("%s @ %s" % (_adv_trunc(cimg, 120), creator[1]))
                                                    if creator else _R16_NO_ATTR, verdict))
    state_txt = []
    for key in need:
        spec = _R16_ATTR_SRC_BY_KEY[key]
        if not src_ok.get(key, False):
            state_txt.append("%s: %s" % (spec[5], src_notes.get(key) or "不可用"))
        elif src_notes.get(key):
            state_txt.append("%s: %s" % (spec[5], src_notes[key]))
    c.add("提示", cat,
          "持久化归因汇总：已证实 %d / 疑似 %d / 无归因 %d（共 %d 条%s）"
          % (stat["已证实"], stat["疑似"], stat["无归因"], len(items),
             ("，未展开 %d 条" % omitted) if omitted else ""),
          detail="\n".join(summary_lines[:40] + (["数据源：%s" % "；".join(state_txt)] if state_txt else [])),
          advice="「%s」只表示本轮取数范围内未找到创建事件，不等于该持久化不存在或未被创建；"
                 "「疑似」需人工复核父子链与时间差；数据源不可用/截断时请先补齐 Sysmon 与安全审核"
                 "日志再复测。" % _R16_NO_ATTR)


# ============================================================ Windows 安全日志补全（win_security_advanced）
# 与 win_logs()（分类「日志分析」）和 win_logs_advanced()（「深度事件日志」）互补的 Security 通道增量：
#   4624 登录类型分布（重点 3 网络 / 10 RDP）+ 同账号短窗口多次类型 3 → 横向移动线索（中危）
#   4625+4776 合并爆破判定（4776 的 Status=0x0 是验证成功，必须过滤，否则会把成功当失败 → 假高危）
#   4672 特权登录 / 4648 显式凭据登录
#   4768/4769 Kerberos TGT/服务票据（TicketEncryptionType=0x17 RC4 / 0x18 RC4-EXP 属降级线索）
#   4907 对象审核设置变更 / 4719 审核策略修改 / 1102 安全日志清空（严重）
#   5140/5145 网络共享与对象访问（只报 ADMIN$/C$/IPC$ 或敏感路径，避免噪音）
#   4662 目录服务访问（只按 DCSync 属性 GUID 命中才报，裸 4662 一律不告警）
# 约束：任一 XPath 查询失败只 c.warn() 并继续；统计结论走 c.add("提示"|"中危", ...)；
#       evidence ≤100 条、每条 ≤500 字符；原始事件走 c.raw_add()；窗口跟随 --days。
# 口径（R16/P3 修复）：统一分页取数——直到窗口覆盖完或达单查询上限，达到上限的截断与真实
#       覆盖时长由「数据源与覆盖度」段显式声明；统计结论均在标题/明细注明条数上限；
#       域控专属事件（4768/4769/4662）在非域控上必然为 0，一律报“数据缺失”而非“无异常”。

# R16/P3：以下为「单查询分页取数上限」——未达上限即窗口内全量；达到上限时由报告
# 「数据源与覆盖度」段显式声明截断与实际覆盖时长（旧口径是固定 /c:N 只取最新 N 条）。
SEC_ADV_CAP = {"4624": 2400, "4625": 2000, "4776": 2000}   # 高频事件单查询上限
SEC_ADV_N = 1200                      # 其余事件（4672/4648/4768/4769/4907/4719/5140/5145/4662）
# DCSync 属性 GUID：只有命中这两个目录复制权限才升级为高危
SEC_DCSYNC_GUIDS = {
    "1131f6aa-9c07-11d1-f79f-00c04fc2dcd2": "DS-Replication-Get-Changes",
    "1131f6ad-9c07-11d1-f79f-00c04fc2dcd2": "DS-Replication-Get-Changes-All",
}
SEC_LOGON_TYPE_NAME = {"0": "系统", "2": "交互", "3": "网络", "4": "批处理", "5": "服务",
                       "7": "解锁", "8": "网络明文", "9": "新凭据", "10": "远程交互(RDP)",
                       "11": "缓存交互", "12": "缓存远程交互", "13": "缓存解锁"}
# 5140/5145 只在命中“敏感共享名/敏感目标路径”时上报（其余只计数，避免噪音）
SEC_SENSITIVE_SHARE_RE = re.compile(r"(?i)^(ADMIN\$|C\$|D\$|E\$|IPC\$|SYSVOL|NETLOGON)$")
SEC_SENSITIVE_PATH_RE = re.compile(
    r"(?i)(ntds\.dit|\\windows\\ntds|[\\/]config[\\/](sam|security|system)\b|"
    r"\\windows\\system32\\config|sysvol|\.ssh[\\/]|id_rsa|id_ed25519|web\.config|"
    r"[\\/]\.git[\\/]|unattend\.xml|\.kdbx\b|\.pfx\b|\.pem\b|passwords?\.)")
# 4648：进程落在临时/落地目录属可疑
SEC_RISKY_PROC_RE = re.compile(
    r"(?i)(\\temp\\|\\tmp\\|\\appdata\\|\\users\\public\\|\\downloads\\|\\programdata\\|\\perflogs\\)")


def _sec_get(d, *names):
    """按候选字段名取值（兼容 EventData 字段名差异：IpAddress/SourceNetworkAddress 等）。"""
    low = {str(k).lower(): v for k, v in (d or {}).items()}
    for n in names:
        v = low.get(n.lower())
        if v:
            return str(v).strip()
    return ""


def _sec_int(v):
    """整数字符串 → int；失败返回 -1（字段缺失时便于识别，不误判为类型 0）。"""
    try:
        return int(str(v).strip())
    except Exception:
        return -1


def _sec_skip_acct(u):
    """机器账号（域$）与系统伪账号：统计/告警都跳过，避免把系统自身行为当成线索。"""
    u = (u or "").strip()
    if not u or u.endswith("$") or u in ("-", "N/A"):
        return True
    if u.upper() in ("SYSTEM", "LOCAL SERVICE", "NETWORK SERVICE", "ANONYMOUS LOGON"):
        return True
    return u.upper().startswith(("DWM-", "UMFD-"))


def _sec_hexnorm(v):
    """把 0x17 / 23 这类写法归一为 '0x17'（TicketEncryptionType 兼容十进制），失败返回 ''。"""
    v = (v or "").strip().lower()
    if not v:
        return ""
    try:
        n = int(v, 16) if v.startswith("0x") else int(v)
    except Exception:
        return ""
    return "0x%x" % n


def _sec_logon_types(events):
    """纯函数：4624 → [(账号, 登录类型int, 来源IP, epoch)]（供登录类型统计与自检使用）。"""
    recs = []
    for ep, _disp, d in (events or []):
        recs.append((_sec_get(d, "TargetUserName", "SubjectUserName"),
                     _sec_int(_sec_get(d, "LogonType")),
                     _sec_get(d, "IpAddress", "SourceNetworkAddress", "ClientAddress") or "-",
                     ep))
    return recs
def _sec_burst(recs, ltype=3, window=600, minimum=3):
    """纯函数：同账号在 window 秒内 ≥minimum 次 ltype 登录 → [(账号, 次数, 起, 止, IP列表)]。

    用于“同一账号短窗口内多次类型 3（网络登录）→ 疑似横向移动”的人工确认线索。
    """
    per = {}
    for u, t, ip, ep in recs:
        if t == ltype and ep and not _sec_skip_acct(u):
            per.setdefault(u, []).append((ep, ip))
    hits = []
    for u, lst in per.items():
        lst.sort()
        for i in range(len(lst)):
            grp = [x for x in lst if lst[i][0] <= x[0] <= lst[i][0] + window]
            if len(grp) >= minimum:
                hits.append((u, len(grp), grp[0][0], grp[-1][0],
                             sorted(set(x[1] for x in grp))))
                break
    return sorted(hits, key=lambda x: -x[1])


def _sec_brute_fail(e4625, e4776):
    """纯函数：聚合失败登录 → {"acct": {账号: [4625, 4776]}, "src": {来源: [4625, 4776]}}。

    4776（NTLM 凭据验证）**成功也会记录**：Status=0x0 视为成功、Status 缺失视为无法判定，
    两者都不计入失败，避免把验证成功当失败 → 假高危。
    来源维度：4625 用源 IP、4776 用 Workstation（来源主机名），共用一张计数表但键各自独立；
    本机回环地址（-、127.0.0.1、::1）不作为来源聚合，避免把本地失败算成爆破。
    """
    acct, src = {}, {}

    def bump(tbl, k, idx):
        if not k or k in ("-", "::1", "127.0.0.1"):
            return
        row = tbl.setdefault(k, [0, 0])
        row[idx] += 1

    for _ep, _disp, d in (e4625 or []):
        bump(acct, _sec_get(d, "TargetUserName", "SubjectUserName"), 0)
        bump(src, _sec_get(d, "IpAddress", "SourceNetworkAddress"), 0)
    for _ep, _disp, d in (e4776 or []):
        st = _sec_hexnorm(_sec_get(d, "Status", "ErrorCode", "ErrorMessage"))
        if st in ("", "0x0"):
            continue
        bump(acct, _sec_get(d, "TargetUserName", "SubjectUserName"), 1)
        bump(src, _sec_get(d, "Workstation", "SourceWorkstation"), 1)
    return {"acct": acct, "src": src}


def _sec_dcsync_hit(data):
    """4662 是否命中 DCSync 属性 GUID（Get-Changes / Get-Changes-All）；返回命中名称列表。"""
    blob = " ".join(str(v) for k, v in (data or {}).items()
                    if not str(k).startswith("_")).lower()
    blob = blob.replace("{", "").replace("}", "")

    return [name for guid, name in sorted(SEC_DCSYNC_GUIDS.items()) if guid in blob]


def _r18_oldest_record_epoch(channel, timeout=120):
    """通道现存最早一条记录的 (epoch, 展示时间)（R18/P2 现状交叉验证；读不到返回 (None, 原因)）。

    用于「安全日志被清空(1102)」的现状交叉验证：日志被清空后，现存最早记录时间应不早于
    清空事件时间（容差见调用点）。只做一次 /c:1 /rd:false 单条读取，离线本机口径。
    """
    out, err = win_cmd(["wevtutil", "qe", channel, "/c:1", "/rd:false", "/f:xml"], timeout=timeout)
    if not out or "<Event" not in out:
        return None, ("查询失败/无记录（%s）" % str(err or out or "无输出")[:120])
    ev = _evt_parse(out)
    if not ev:
        return None, "返回内容解析失败"
    return ev[0][0], ev[0][1]


def win_security_advanced(c):
    """安全日志增量检查（Security 通道）：见本段落头注释的事件清单。

    与 win_logs() 互补：分类名「安全日志增强」独立，不改动既有函数与结论；
    任一查询失败只 c.warn()；统计类结论走 c.add("提示"|"中危", ...)，
    爆破与 DCSync 为「高危」、安全日志清空(1102)为「严重」（沿用既有分级）。
    """
    cat = "安全日志增强"
    days = max(1, int(c.days or DEFAULT_DAYS))
    win = _evt_scope(days)
    thr = BRUTE_THRESHOLD                  # 复用全局阈值（--threshold 可调）

    def q(ids, count=SEC_ADV_N, timeout=240):
        return _adv_query(c, "Security", ids, win, count=count, timeout=timeout,
                          label="安全日志增强(%s)" % "/".join(str(i) for i in ids))

    def raw(title, evs, src, n=60):
        c.raw_add(title, src,
                  [_adv_blob(d, 400) for _ep, _disp, d in (evs or [])[:n]] or ["(无事件)"])

    # ---------------------------------------------------- 1) 4624 登录类型分布 + 横向移动线索
    n24 = SEC_ADV_CAP["4624"]
    ev24, why = q(("4624",), count=n24)
    if ev24 is None:
        c.warn("安全日志(Security)不可读（%s）：登录类型统计、特权/显式凭据登录、Kerberos 票据、"
               "共享访问与 DCSync 均未分析（需管理员身份运行）" % (why or "未知原因"))
    else:
        raw("安全日志-登录成功(4624)", ev24,
            "wevtutil qe Security 4624（窗口 %d 天，单查询上限 %d 条；未达上限即窗口内全量）" % (days, n24))
        recs = _sec_logon_types(ev24)
        dist = {}
        for _u, t, _ip, _ep in recs:
            dist[t] = dist.get(t, 0) + 1
        rows = ["类型 %d（%s）= %d 次" % (t, SEC_LOGON_TYPE_NAME.get(str(t), "未知"), n)
                for t, n in sorted(dist.items(), key=lambda x: -x[1])]
        if not rows:
            c.add("提示", cat, "窗口内无 4624 登录成功事件（数据缺失，不能据此判定“无异常”）")
        else:
            c.add("提示", cat,
                  "登录类型分布（4624，上限 %d 条 / 窗口 %d 天；未达上限即窗口内全量）" % (len(recs), days),
                  detail="%s；重点：类型 3（网络）%d 次、类型 10（远程交互/RDP）%d 次"
                         % ("; ".join(rows[:10]), dist.get(3, 0), dist.get(10, 0)),
                  evidence=_adv_cap(rows, 100, 500),
                  advice="类型 3 常为共享/服务访问，类型 10 为远程桌面；异常来源 IP 需结合 4672/4648 复核。")
            c.raw_add("登录类型分布(4624)", "按 LogonType 统计（分页取数上限 %d 条）" % len(recs), rows)
        hits = _sec_burst(recs, 3, 600, 3)
        if hits:
            lines = ["账号=%s 600 秒内 %d 次类型 3（%s ~ %s）来源=%s"
                     % (u, n, human_time(t0), human_time(t1), ",".join(ips[:5]) or "-")
                     for u, n, t0, t1, ips in hits]
            c.add("中危", cat, "疑似横向移动（同账号短窗口多次网络登录，需人工确认）",
                  detail="\n".join(lines[:12]), evidence=_adv_cap(lines, 100, 500),
                  advice="核对该账号是否为失窃凭据：结合 4672/4648、5140/5145 与目标主机日志确认；"
                         "必要时隔离来源主机并强制改密。")
    if c.stopped():
        return

    # ------------------------- 2) 4776 NTLM 凭据验证 + 3) 4625/4776 合并爆破判定
    n25, n76 = SEC_ADV_CAP["4625"], SEC_ADV_CAP["4776"]
    ev25, why25 = q(("4625",), count=n25)
    ev76, why76 = q(("4776",), count=n76)
    if ev25 is not None:
        raw("安全日志-登录失败(4625)", ev25,
            "wevtutil qe Security 4625（窗口 %d 天，单查询上限 %d 条；未达上限即窗口内全量）" % (days, n25))
    if ev76 is not None:
        raw("安全日志-NTLM 凭据验证(4776)", ev76,
            "wevtutil qe Security 4776（窗口 %d 天，单查询上限 %d 条；未达上限即窗口内全量）" % (days, n76))
    if ev25 is None or ev76 is None:
        c.warn("安全日志查询失败（4625/4776，%s）：含 NTLM 维度的爆破聚合未完成"
               % (why25 or why76 or "未知原因"))
    else:
        agg = _sec_brute_fail(ev25, ev76)
        rows = ([("账号", k, v) for k, v in agg["acct"].items()] +
                [("来源(IP/主机名)", k, v) for k, v in agg["src"].items()])

        def joined_over(items):
            return ["%s %s：4625 失败 %d 次 + 4776 失败 %d 次 = %d 次"
                    % (dim, k, v[0], v[1], v[0] + v[1]) for dim, k, v in items]

        over = [(dim, k, v) for dim, k, v in rows if sum(v) >= thr and v[1] > 0]
        only25 = [(dim, k, v) for dim, k, v in rows if sum(v) >= thr and v[1] == 0]
        if over:
            c.add("高危", cat, "窗口内 4625+4776 合并爆破（含 NTLM 凭据验证失败）",
                  detail="阈值 %d；%s" % (thr, "; ".join(joined_over(over)[:10])),
                  evidence=_adv_cap(joined_over(over), 100, 500),
                  advice="封禁来源 IP/主机；确认被爆破账号是否已成功登录（结合 4624 类型 3/10），"
                         "必要时强制改密并检查该账号的后续操作。")
        if only25:
            c.add("提示", cat, "纯 4625 失败超阈值（已在「日志分析」按暴力破解报出，此处不重复高危）",
                  detail="; ".join(joined_over(only25)[:10]))
        if not over:
            top = sorted(rows, key=lambda x: -sum(x[2]))[:10]
            c.add("提示", cat,
                  "登录失败聚合（4625+4776，上限 %d/%d 条）：未超阈值 %d" % (n25, n76, thr),
                  detail="; ".join(joined_over(top)) or "窗口内无失败登录事件",
                  advice="4776 记录 NTLM 凭据验证（成功/失败都记）：怀疑爆破时优先看账号与来源主机名维度。")
    if c.stopped():
        return

    # ---------------------------------------------------- 4) 4672 特权登录 / 4648 显式凭据登录
    ev, why = q(("4672", "4648"))
    if ev is None:
        c.warn("安全日志查询失败（4672/4648，%s）：特权登录与显式凭据登录未分析"
               % (why or "未知原因"))
    else:
        raw("安全日志-特权/显式凭据登录(4672/4648)", ev,
            "wevtutil qe Security 4672/4648（窗口 %d 天，单查询上限 %d 条；未达上限即窗口内全量）" % (days, SEC_ADV_N))
        a672, a648, risky = {}, {}, []
        for ep, disp, d in ev:
            eid = (d.get("_EventID") or "").strip()
            u = _sec_get(d, "SubjectUserName")
            if eid == "4672":
                if not _sec_skip_acct(u):
                    a672[u] = a672.get(u, 0) + 1
                continue
            tgt = _sec_get(d, "TargetUserName")
            srv = _sec_get(d, "TargetServerName", "TargetInfo")
            proc = _sec_get(d, "ProcessName")
            if _sec_skip_acct(u) and _sec_skip_acct(tgt):
                continue
            key = "%s→%s" % (u or "?", tgt or "?")
            a648[key] = a648.get(key, 0) + 1
            ipm = re.search(r"\b(\d{1,3}(?:\.\d{1,3}){3})\b", srv or "")
            if (ipm and is_private_ip(ipm.group(1)) is False) or SEC_RISKY_PROC_RE.search(proc or ""):
                risky.append("%s 账号=%s 目标=%s（%s）进程=%s"
                             % (disp, u or "?", tgt or "?", srv or "-", proc or "-"))
        rows672 = ["%s = %d 次" % (k, v) for k, v in sorted(a672.items(), key=lambda x: -x[1])]
        rows648 = ["%s = %d 次" % (k, v) for k, v in sorted(a648.items(), key=lambda x: -x[1])]
        if rows672 or rows648:
            c.add("提示", cat,
                  "特权登录(4672)/显式凭据登录(4648) 聚合（上限 %d 条 / 窗口 %d 天）"
                  % (len(ev), days),
                  detail="4672: %s；4648: %s" % ("; ".join(rows672[:8]) or "无",
                                                  "; ".join(rows648[:8]) or "无"),
                  advice="4672=分配特殊权限（管理员登录/服务启动属正常）；4648=用显式凭据登录，"
                         "重点看目标为公网地址或进程落在临时目录的条目。")
            c.raw_add("特权/显式凭据登录统计(4672/4648)",
                      "按账号聚合（分页取数上限 %d 条）" % len(ev), rows672 + rows648)
        if risky:
            c.add("中危", cat, "显式凭据登录(4648)命中可疑目标（公网地址/临时目录进程，需人工确认）",
                  detail="\n".join(risky[:12]), evidence=_adv_cap(risky, 100, 500),
                  advice="确认是否为运维脚本；可疑进程立即取证（文件+父进程+网络连接），"
                         "并按“凭据可能泄露”处置。")

    # ---------------------------------------------------- 5) 4768/4769 Kerberos 票据（RC4 降级线索）
    ev, why = q(("4768", "4769"))
    if ev is None:
        c.warn("安全日志查询失败（4768/4769，%s）：Kerberos 票据降级线索未分析"
               % (why or "未知原因"))
    elif not ev:
        c.add("提示", cat, "窗口内无 Kerberos 票据事件（4768/4769）：本机非域控/未加入域，"
                           "或窗口内无票据申请（数据缺失，不能据此判定“无异常”）")
    else:
        raw("安全日志-Kerberos 票据(4768/4769)", ev,
            "wevtutil qe Security 4768/4769（窗口 %d 天，单查询上限 %d 条；未达上限即窗口内全量）" % (days, SEC_ADV_N))
        n_tgt = n_svc = n_fail = 0
        down = []
        for ep, disp, d in ev:
            eid = (d.get("_EventID") or "").strip()
            if eid == "4768":
                n_tgt += 1
            else:
                n_svc += 1
            if _sec_hexnorm(_sec_get(d, "Status", "ResultCode")) not in ("", "0x0"):
                n_fail += 1
            tet = _sec_hexnorm(_sec_get(d, "TicketEncryptionType"))
            if tet in ("0x17", "0x18"):
                down.append("%s %s 降级加密 TET=%s（%s）账号=%s 服务=%s 来源=%s"
                            % (disp, "TGT(4768)" if eid == "4768" else "服务票据(4769)", tet,
                               "RC4-HMAC" if tet == "0x17" else "RC4-HMAC-EXP",
                               _sec_get(d, "TargetUserName") or "?",
                               _sec_get(d, "ServiceName") or "-",
                               _sec_get(d, "IpAddress") or "-"))
        if down:
            c.add("中危", cat, "Kerberos 票据使用 RC4 降级加密（TET=0x17/0x18，需人工确认）",
                  detail="TGT %d 条 / 服务票据 %d 条（失败 %d 条）；命中 %d 条：\n%s"
                         % (n_tgt, n_svc, n_fail, len(down), "\n".join(down[:10])),
                  evidence=_adv_cap(down, 100, 500),
                  advice="RC4 票据是 Kerberoasting/票据传递的常见线索；核对命中账号与服务账号口令强度，"
                         "必要时禁用 RC4 并排查来源主机。")
        else:
            c.add("提示", cat, "Kerberos 票据未见 RC4 降级（TET 无 0x17/0x18；TGT %d 条 / 服务票据 %d 条 / "
                               "失败 %d 条，上限 %d 条）" % (n_tgt, n_svc, n_fail, len(ev)))

    # ---------------------------------------------------- 6) 4907 对象审核设置 / 4719 审核策略
    ev, why = q(("4907", "4719"))
    if ev is None:
        c.warn("安全日志查询失败（4907/4719，%s）：对象审核设置与审核策略变更未分析"
               % (why or "未知原因"))
    else:
        raw("安全日志-审核设置变更(4907/4719)", ev,
            "wevtutil qe Security 4907/4719（窗口 %d 天，单查询上限 %d 条；未达上限即窗口内全量）" % (days, SEC_ADV_N))
        rows4907, rows4719 = [], []
        for ep, disp, d in ev:
            eid = (d.get("_EventID") or "").strip()
            u = _sec_get(d, "SubjectUserName") or "?"
            if eid == "4719":
                rows4719.append("%s 账号=%s 变更：%s" % (disp, u, _adv_blob(d, 200)))
            else:
                rows4907.append("%s 账号=%s 对象=%s（%s）"
                                % (disp, u, _sec_get(d, "ObjectName") or "?",
                                   _sec_get(d, "ObjectType") or "-"))
        if rows4719:
            c.add("中危", cat, "审核策略被修改（4719，需人工确认）",
                  detail="共 %d 条（上限 %d 条；未达上限即窗口内全量）：\n%s"
                         % (len(rows4719), len(ev), "\n".join(rows4719[:10])),
                  evidence=_adv_cap(rows4719, 100, 500),
                  advice="核对是否为合规调整/GPO 刷新；攻击者常改审核策略以掩盖行为，需与变更单比对。")
        if rows4907:
            c.add("中危", cat, "对象审核设置发生变更（4907，需人工确认）",
                  detail="共 %d 条（上限 %d 条；未达上限即窗口内全量）：\n%s"
                         % (len(rows4907), len(ev), "\n".join(rows4907[:10])),
                  evidence=_adv_cap(rows4907, 100, 500),
                  advice="确认新 SACL 是否由安全产品/运维下发；若为取消审核，"
                         "需重点排查同一时段的其它行为。")
        if not rows4719 and not rows4907:
            c.add("提示", cat, "窗口内无审核设置变更事件（4719/4907，上限 %d 条）" % len(ev))

    # ---------------------------------------------------- 7) 5140/5145 网络共享与对象访问
    ev, why = q(("5140", "5145"))
    if ev is None:
        c.warn("安全日志查询失败（5140/5145，%s）：网络共享/对象访问未分析" % (why or "未知原因"))
    elif ev:
        raw("安全日志-共享与对象访问(5140/5145)", ev,
            "wevtutil qe Security 5140/5145（窗口 %d 天，单查询上限 %d 条；未达上限即窗口内全量）" % (days, SEC_ADV_N))
        hits = []
        for ep, disp, d in ev:
            share = _sec_get(d, "ShareName")
            path = (_sec_get(d, "RelativeTargetName") or _sec_get(d, "ShareLocalPath")
                    or _sec_get(d, "ObjectName"))
            if not (share and SEC_SENSITIVE_SHARE_RE.match(share)) \
                    and not SEC_SENSITIVE_PATH_RE.search(path or ""):
                continue
            hits.append("%s 共享=%s 目标=%s 账号=%s 来源=%s"
                        % (disp, share or "-", _adv_trunc(path or "-", 160),
                           _sec_get(d, "SubjectUserName") or "?", _sec_get(d, "IpAddress") or "-"))
        if hits:
            c.add("中危", cat, "敏感共享/对象被访问（ADMIN$/C$/IPC$ 或敏感路径，需人工确认）",
                  detail="命中 %d 条 / 共 %d 条（上限 %d 条；未达上限即窗口内全量）：\n%s"
                         % (len(hits), len(ev), len(ev), "\n".join(hits[:10])),
                  evidence=_adv_cap(hits, 100, 500),
                  advice="管理共享被访问多为正常运维；重点看非管理员账号、非管理网段来源，"
                         "以及目标落在 NTDS.dit、SAM/SECURITY、.ssh、web.config 等敏感文件上的条目。")
        else:
            c.add("提示", cat, "网络共享/对象访问 %d 条（未命中 ADMIN$/C$/IPC$ 或敏感路径，"
                               "仅统计；上限 %d 条）" % (len(ev), len(ev)))
    if c.stopped():
        return

    # ---------------------------------------------------- 8) 4662 目录服务访问（仅 DCSync GUID 定向）
    ev, why = q(("4662",))
    if ev is None:
        c.warn("安全日志查询失败（4662，%s）：DCSync 线索未分析" % (why or "未知原因"))
    elif not ev:
        c.add("提示", cat, "窗口内无 4662 目录服务访问事件：本机非域控或未开启“目录服务访问”审核"
                           "（数据缺失，不能据此判定“无异常”）")
    else:
        raw("安全日志-目录服务访问(4662)", ev,
            "wevtutil qe Security 4662（窗口 %d 天，单查询上限 %d 条；未达上限即窗口内全量）" % (days, SEC_ADV_N))
        hits, machine, other = [], 0, 0
        for ep, disp, d in ev:
            names = _sec_dcsync_hit(d)
            if not names:
                other += 1
                continue
            u = _sec_get(d, "SubjectUserName") or "?"
            if _sec_skip_acct(u):
                machine += 1
                continue
            hits.append("%s 主体=%s（%s）命中=%s 对象=%s"
                        % (disp, u, _sec_get(d, "SubjectDomainName") or "-",
                           ",".join(names), _sec_get(d, "ObjectName") or "-"))
        if hits:
            c.add("高危", cat, "疑似 DCSync（4662 命中目录复制属性 GUID：Get-Changes/Get-Changes-All）",
                  detail="命中 %d 条（上限 %d 条；未达上限即窗口内全量）：\n%s"
                         % (len(hits), len(ev), "\n".join(hits[:10])),
                  evidence=_adv_cap(hits, 100, 500),
                  advice="确认该主体是否为域控/复制服务账号；非机器账号命中即视为高危："
                         "立即冻结该账号、排查其来源主机并重置 krbtgt（必要时两次）。")
        elif machine:
            c.add("提示", cat, "4662 命中目录复制 GUID 的主体均为机器账号"
                               "（域控自身复制，属正常）：%d 条" % machine)
        if other:
            c.add("提示", cat, "4662 其余 %d 条未命中目录复制 GUID（裸 4662 不作告警；"
                               "上限 %d 条）" % (other, len(ev)))

    # ---------------------------------------------------- 9) 1102 安全日志被清空（严重）
    ev, why = q(("1102",), count=20)
    if ev is None:
        c.warn("安全日志查询失败（1102，%s）：日志清空事件未分析" % (why or "未知原因"))
    elif ev:
        lines = ["%s 账号=%s（%s）%s" % (disp, _sec_get(d, "SubjectUserName") or "?",
                                        _sec_get(d, "SubjectDomainName") or "-", _adv_blob(d, 160))
                 for ep, disp, d in ev]
        # R18/P2：1102 交叉验证——事件 + 现状（Security 日志现存最早记录不早于清空时间）。
        # 两条独立证据成立才保留「严重」；现状不可得/不一致 ⇒ 闸门自动降级为「高危」。
        last_ep = max(int(ep or 0) for ep, _disp, _d in ev)
        oldest_ep, oldest_disp = _r18_oldest_record_epoch("Security")
        if oldest_ep is None:
            now_result = "Security 日志现存最早记录不可得（%s），现状交叉验证未完成" % oldest_disp
            consistent = False
        else:
            consistent = oldest_ep >= last_ep - 300
            now_result = ("Security 日志现存最早记录=%s（与最近一次清空时间差 %+d 秒）⇒ %s"
                          % (oldest_disp, oldest_ep - last_ep,
                             "与「日志已被清空」现状一致" if consistent
                             else "与「日志已被清空」现状不一致（存在早于清空的留存记录）"))
        src_evt = ("Security 1102 事件",
                   "共 %d 条（上限 20）；清空者=%s" % (len(ev), lines[0][:160]))
        if consistent:
            c.add_verified("严重", cat, "安全日志被清空（1102）：事件 + 日志现状交叉验证一致",
                  detail="共 %d 条（上限 20 条）：\n%s\n交叉验证：%s"
                         % (len(ev), "\n".join(lines[:10]), now_result),
                  evidence=_adv_cap(lines + [now_result], 100, 500),
                  advice="日志清空是攻击者典型的反取证动作：立即隔离主机、保全磁盘镜像，"
                         "并从日志服务器/EDR 侧恢复该时段的记录。",
                  sources=[src_evt, ("Security 日志现状最早记录", now_result)])
        else:
            c.add_verified("严重", cat, "安全日志被清空（1102）",
                  detail="共 %d 条（上限 20 条）：\n%s\n交叉验证：%s\n"
                         "判定：未取得可支撑「严重」的第二条独立证据（现状不可得或与事件不一致）"
                         "⇒ 按 R18 严重级闸门降级处理，需人工复核。" % (len(ev), "\n".join(lines[:10]), now_result),
                  evidence=_adv_cap(lines + [now_result], 100, 500),
                  advice="先复核清空者账户与来源；再检查日志服务器/EDR 侧该时段记录是否缺失，"
                         "确认后再按反取证处置（保全磁盘镜像）。",
                  sources=[src_evt])
    else:
        c.add("提示", cat, "窗口内无 1102（安全日志未被清空；上限 20 条）")

    c.add("提示", cat, "安全日志增强检查完成：4624 登录类型统计 / 4672 / 4648 / 4776（NTLM 失败聚合） / "
                       "4768+4769（票据降级） / 4907 / 4719 / 5140+5145（敏感共享） / "
                       "4662（DCSync GUID 定向） / 1102；各查询分页取数直到窗口覆盖完或达到单查询上限，"
                       "达上限时由「数据源与覆盖度」段声明截断；缺失即“数据缺失”")


# ============================================================ R22/P1：矿池端口命中的回环/远程判定
# 依据：R22 需求书 P1 —— netstat -ano 的「矿池端口外联」不能只看端口号：连接两端均为回环/本机
#   地址时，本机服务/代理的自环连接（实例：深信服 VDI 客户端 vECAgent.exe 监听 127.0.0.1:3333）
#   会被误判为矿池外联。机制：地址归一、判定分流、证据行格式都收在下面这组纯函数里（单一判定点/
#   单一上报点），win_process_anomaly 只负责取数与调用；非本机地址一侧仍走原「高危」口径，文案与
#   证据行格式逐字不变。判定依据只有地址与进程身份，不引入任何配置文件/白名单。

def _ip_norm(addr):
    """netstat 地址串归一：去 []、去 %zone、小写。纯函数。"""
    s = str(addr or "").strip()
    if "%" in s:
        s = s.split("%", 1)[0]
    return s.strip().strip("[]").lower()


def _is_loop_local_addr(addr, local_ips=None):
    """地址串是否回环/本机：127.0.0.0/8、::1、[::1]、localhost 或本机地址集合。纯函数。"""
    s = _ip_norm(addr)
    if not s:
        return False
    if s == "localhost" or s == "::1":
        return True
    if re.match(r"^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$", s):
        return True
    return s in (local_ips or ())


def _mine_port_conns(ns_text):
    """netstat -ano 文本 → 命中 MINING_PORTS 的 ESTABLISHED 连接（判据=远端端口，与 R20 同）。

    纯函数；返回 [{"local": 本地主机串, "remote": 远端主机串, "port": 远端端口,
    "pid": PID, "desc": 端口说明}]（字段与原正则捕获组一致：展示格式仍为
    「本地主机 -> 远端主机:端口 (PID …) 说明」），顺序 = netstat 出现顺序。
    """
    out = []
    for ln in (ns_text or "").splitlines():
        m = re.search(r"(\S+):(\d+)\s+(\S+):(\d+)\s+ESTABLISHED\s+(\d+)", ln)
        if not m:
            continue
        port = int(m.group(4))
        if port in MINING_PORTS:
            out.append({"local": m.group(1), "remote": m.group(3), "port": port,
                        "pid": m.group(5), "desc": MINING_PORTS[port]})
    return out


def _mine_port_split(conns, local_ips=None):
    """连接命中列表 → (非回环项, 回环项)。判定（R22/P1）：本地与远端均为回环/本机地址 ⇒ 回环项
    （提示级，需人工确认）；任一端为非本机地址 ⇒ 非回环项（原高危口径）。纯函数。"""
    ips = set(x for x in (_ip_norm(v) for v in (local_ips or ())) if x)
    non_loop, loop = [], []
    for x in conns or []:
        if (_is_loop_local_addr(x.get("local"), ips)
                and _is_loop_local_addr(x.get("remote"), ips)):
            loop.append(x)
        else:
            non_loop.append(x)
    return non_loop, loop


def _mine_conn_line(x, procs=None, sig_map=None):
    """连接命中项 → 证据行。基线格式与 R20 逐字一致：本地->远端:端口 (PID …) 端口说明；

    传 procs/sig_map 时补「进程名 / 可执行路径 / 签名状态」（任一项取不到写「不可得」，
    进程完全取不到写「进程信息不可得」）。纯函数（自检直接调用）。
    """
    line = "%s -> %s:%s (PID %s) %s" % (x.get("local"), x.get("remote"), x.get("port"),
                                        x.get("pid"), x.get("desc"))
    if procs is None:
        return line
    proc = None
    try:
        proc = (procs or {}).get(int(x.get("pid")))
    except Exception:
        proc = None
    name, path = "", ""
    if isinstance(proc, dict):
        name = str(proc.get("disp") or proc.get("name") or "").strip()
        path = str(proc.get("path") or "").strip()
    if not name:
        return line + "；进程信息不可得"
    st = ""
    if sig_map and path:
        v = sig_map.get(path.lower())
        if isinstance(v, (tuple, list)) and v:
            st = str(v[0] or "").strip()
        elif v:
            st = str(v).strip()
    return "%s；进程=%s，路径=%s，签名状态=%s" % (line, name, path or "不可得", st or "不可得")


def _win_local_addrs():
    """本机地址集合（回环/本机判定用）：ipconfig 文本提取 IPv4/IPv6（去 zone）。

    只读、离线；取不到返回空集（127.0.0.0/8、::1、localhost 的字面量判定不受影响）。
    """
    ips = set()
    try:
        out, _ = win_cmd(["ipconfig"], timeout=30)
    except Exception as _e_r22:
        _degrade("_win_local_addrs", _e_r22)
        out = ""
    for m in re.finditer(r"\b\d{1,3}(?:\.\d{1,3}){3}\b", out or ""):
        ips.add(m.group(0))
    for m in re.finditer(r"\b(?:[0-9a-fA-F]{1,4}:){2,7}[0-9a-fA-F]{1,4}\b", out or ""):
        ips.add(m.group(0))
    return ips


def _mine_port_report(c, cat, conns, local_ips=None, procs=None, sig_map=None, hosts_lines=None):
    """R22/P1 单一上报点：矿池端口 / hosts 命中 → 结论。

    - 非回环项（任一端非本机）+ hosts 矿池域名 → 「高危」「存在矿池相关连接/配置」（文案与证据
      格式 = R20 逐字不变）；
    - 回环项（两端均回环/本机）→ 单独一条「提示」「回环端口命中矿池端口表（需人工确认）」，
      证据行补 PID 进程名/路径/签名状态（取不到写「进程信息不可得」）；
    - 同轮两者都有时高危只列非回环项，绝不混成一条高危。
    返回 (高危条数, 提示条数)。sig_map=None 时按需批量取签名（PowerShell 不可用则降级为「不可得」）。
    """
    non_loop, loop = _mine_port_split(conns, local_ips)
    pool = [_mine_conn_line(x) for x in non_loop] + [str(s) for s in (hosts_lines or [])]
    if pool:
        c.add("高危", cat, "存在矿池相关连接/配置", detail="\n".join(pool[:20]), evidence=pool,
              advice="立即封禁矿池 IP/域名；排查下载来源与持久化项。")
    if loop:
        if sig_map is None:
            paths = []
            for x in loop:
                try:
                    p = (procs or {}).get(int(x.get("pid"))) or {}
                except Exception:
                    p = {}
                pp = str(p.get("path") or "").strip()
                if pp:
                    paths.append(pp)
            sig_map = _hj_adv_sig_map(c, paths, tag="（矿池端口回环命中进程）") if paths else {}
        lines = [_mine_conn_line(x, procs, sig_map) for x in loop]
        c.add("提示", cat, "回环端口命中矿池端口表（需人工确认）",
              detail="\n".join(lines[:20]), evidence=lines,
              advice="本机回环连接，通常为本机服务或代理；核对上述进程身份后再判。")
    return (1 if pool else 0, 1 if loop else 0)


def win_process_anomaly(c):
    """进程树异常 + 挖矿/横向工具特征。"""
    cat = "进程树与恶意家族"
    rows, raw = wmic_csv("process get ProcessId,Name,ExecutablePath,CommandLine,ParentProcessId")
    if not rows:
        rows, raw = ps_csv("Get-CimInstance Win32_Process | Select-Object ProcessId,Name,"
                           "ExecutablePath,CommandLine,ParentProcessId | ConvertTo-Csv -NoTypeInformation")
    procs = {}
    for r in rows:
        try:
            pid = int(r.get("ProcessId") or 0)
        except Exception:
            continue
        procs[pid] = {"name": (r.get("Name") or "").lower(),
                      "disp": (r.get("Name") or ""),
                      "path": (r.get("ExecutablePath") or ""),
                      "cmd": (r.get("CommandLine") or ""),
                      "ppid": r.get("ParentProcessId") or "0"}
    if not procs:
        return
    anom, mining = [], []
    shell_names = ("cmd.exe", "powershell.exe", "pwsh.exe", "mshta.exe", "wscript.exe",
                   "cscript.exe", "rundll32.exe", "regsvr32.exe", "certutil.exe", "bitsadmin.exe")
    bad_parents = ("winword.exe", "excel.exe", "powerpnt.exe", "outlook.exe", "w3wp.exe",
                   "php-cgi.exe", "java.exe", "tomcat", "httpd.exe", "nginx.exe", "msedge.exe",
                   "chrome.exe", "firefox.exe", "acrord32.exe", "wscript.exe")
    for pid, p in procs.items():
        try:
            parent = procs.get(int(p["ppid"] or 0), {})
        except Exception:
            parent = {}
        pname = (parent.get("name") or "")
        if p["name"] in shell_names and any(b in pname for b in bad_parents):
            anom.append("[可疑父进程] %s(PID %s) 由 %s 派生: %s"
                        % (p["name"], pid, pname, p["cmd"][:200]))
        if p["name"] in ("svchost.exe", "lsass.exe", "services.exe") and pid not in (0, 4):
            try:
                if p["ppid"] and int(p["ppid"]) not in procs and p["ppid"] != "0":
                    anom.append("[父进程不存在] %s(PID %s) ppid=%s" % (p["name"], pid, p["ppid"]))
            except Exception as _e_r19:
                _degrade("win_process_anomaly", _e_r19)
        low = (p["name"] + " " + p["path"] + " " + p["cmd"]).lower()
        for hint in MINING_NAME_HINTS:
            if hint in low:
                mining.append("[挖矿家族特征] PID %s %s => %s" % (pid, p["name"], p["path"] or p["cmd"][:160]))
                break
        hits = match_rules(p["cmd"], MINING_CMD_PATTERNS)
        if hits:
            mining.append("[挖矿命令行] PID %s %s => %s [命中: %s]"
                          % (pid, p["name"], p["cmd"][:200], "/".join(hits)))
        lt = [x for x in LATERAL_TOOL_NAMES if re.search(r"(^|[\\/_\-\.])%s([\.\s]|$)" % re.escape(x), low)]
        if lt:
            anom.append("[渗透/横向工具] PID %s %s => %s [%s]" % (pid, p["name"], p["path"][:160], ",".join(set(lt))))
    if anom:
        c.add("高危", cat, "进程树/工具特征异常", detail="\n".join(anom[:25]), evidence=anom,
              advice="重点关注文档/Web 容器派生的 shell；先取证（内存、命令行、父子关系）再处置。")
    if mining:
        c.add("高危", cat, "发现挖矿程序特征", detail="\n".join(mining[:20]), evidence=mining,
              advice="杀进程→删除落地文件→清理计划任务/启动项→封禁矿池域名与端口→查杀全盘。")
    if not anom and not mining:
        c.add("提示", cat, "进程树与恶意家族特征未命中（共 %d 个进程）" % len(procs))

    # 矿池端口外联 + hosts 中的矿池域名（R22/P1：回环/本机与远程分开判定，单一上报点）
    ns, _ = win_cmd(["netstat", "-ano"])
    conns = _mine_port_conns(ns)
    local_ips = _win_local_addrs() if conns else set()   # 仅端口命中时才取本机地址（省时）
    hosts = safe_read(os.path.join(os.environ.get("SystemRoot", r"C:\Windows"),
                                   r"System32\drivers\etc\hosts")) or ""
    host_hits = ["hosts 中出现矿池域名: %s" % p for p in COIN_POOL_HINTS if p in hosts.lower()]
    _mine_port_report(c, cat, conns, local_ips, procs=procs, hosts_lines=host_hits)


def win_drivers_certs_firewall(c):
    """驱动签名/路径、近期新增根证书、防火墙状态与异常放行规则。"""
    cat = "驱动与信任链"
    out, _ = win_cmd(["driverquery", "/v", "/fo", "csv"], timeout=150)
    if out:
        rows = parse_csv_table(out)
        bad = []
        for r in rows:
            path = (r.get("Path") or r.get("路径") or "").strip()
            if path and not re.search(r"(?i)(\\(system32|syswow64|driverstore|winsxs)\\|"
                                      r"\\systemroot\\)", path) \
                    and not path.startswith("\\SystemRoot"):
                bad.append("%s => %s" % (r.get("Module Name") or r.get("模块名") or "?", path))
        if bad:
            c.add("中危", cat, "存在非系统目录加载的驱动",
                  detail="\n".join(bad[:15]), evidence=bad,
                  advice="驱动的内核级后门危害大：核对签名与厂商，非业务驱动立即停用/删除。")
        else:
            c.add("提示", cat, "驱动均来自系统目录（共 %d 个）" % len(rows))
    certs = ps_text("Get-ChildItem Cert:\\LocalMachine\\Root | Where-Object "
                    "{$_.NotBefore -gt (Get-Date).AddDays(-%d)} | "
                    "Select-Object Subject,Thumbprint,NotBefore | ConvertTo-Csv -NoTypeInformation"
                    % max(7, c.days))
    if certs and "Subject" in certs:
        c.add("中危", cat, "近期新增的可信根证书（%d 天内）" % max(7, c.days),
              detail=certs.strip()[:800], advice="攻击者安装自签根证书可实现流量解密/中间人；非业务证书删除。")
    fw = ps_text("Get-NetFirewallProfile | Select-Object Name,Enabled | ConvertTo-Csv -NoTypeInformation")
    if fw and "Name" in fw:
        rows = parse_csv_table(fw)
        off = [r.get("Name") for r in rows if str(r.get("Enabled", "")).lower() in ("false", "0")]
        if off:
            c.add("中危", cat, "防火墙配置被关闭: %s" % ", ".join(off),
                  advice="核对是人为操作还是攻击者关闭；恢复后检查放行规则。")
    rules = ps_text("Get-NetFirewallRule -Direction Inbound -Action Allow -Enabled True | "
                    "Where-Object {$_.RemoteAddress -eq 'Any'} | Select-Object DisplayName,"
                    "Profile | ConvertTo-Csv -NoTypeInformation")
    if rules and "DisplayName" in rules:
        rows = parse_csv_table(rules)
        if len(rows) > 30:
            c.raw_add("入站放行规则(Any)", "Get-NetFirewallRule", rules)
            c.add("中危", cat, "存在大量任意来源入站放行规则（%d 条）" % len(rows),
                  detail="\n".join(str(r.get("DisplayName")) for r in rows[:15]),
                  advice="攻击者常加规则放行后门端口；逐条核对业务必要性。")


def run_win_checks_extra(c, opts):
    win_wmi_subscription(c)
    win_hijack_points(c)
    win_bits(c)
    win_av_status(c)
    win_credentials_config(c)
    win_network_config(c)
    win_shares(c)
    win_process_anomaly(c)
    win_drivers_certs_firewall(c)

# ============================================================ 可疑程序取证画像（恶意程序一键排查）
# 依据：第01章 Windows 入侵排查 / 第03章 持久化 / 第05章 恶意样本分析
#
# 目标：一次运行就把「某个恶意程序」说清楚 —— 源文件在哪、什么时候落地、从哪下载的、
#       什么时候执行的、靠什么持久化、它做了什么（建账号、拉进程、装服务、连外网、丢文件）。
# 全部只读采集，不下发任何处置动作。
#
# 数据源（都只用系统自带组件）：
#   文件本体     Get-Item（NTFS 创建时间=落地时间）/ MD5+SHA256 / Authenticode 签名 / 备用数据流
#   下载来源     Zone.Identifier 流（HostUrl/ReferrerUrl）、浏览器下载库（Edge/Chrome History）、BITS
#   执行时间     Prefetch(.pf)、BAM/DAM、UserAssist、进程 CreationDate、4688
#   持久化       Run/RunOnce/Winlogon/IFEO/AppInit/LSA/启动夹/计划任务/服务/WMI 订阅/BITS
#   行为         4688 子进程、4720/4732 建账号、7045 装服务、Sysmon 1/3/11/13（若安装）
# 运行期需要管理员才能读到的项（安全日志、bam\State）读不到时写入「未完成的检查」，不静默放过。

