DOSSIER_SECURITY_EIDS = {
    "4688": "进程创建", "4720": "创建用户账号", "4722": "账号被启用", "4726": "删除用户账号",
    "4728": "加入全局安全组", "4732": "加入本地组", "7045": "安装系统服务", "4697": "安装服务(客户端)",
    "4698": "创建计划任务", "4719": "审计策略被修改", "1102": "安全日志被清空",
}


def _dsn_temp_json(prefix, data):
    """把数据落到 %TEMP% 的临时 JSON（给 PowerShell 读，避免命令行引号地狱）。

    R16/P5：固定 utf-8-sig（带 BOM）写出——Windows PowerShell 5.1 读无 BOM 文本时按系统
    本地代码页（中文机 cp936）解码，会把 UTF-8 中文路径解成「尘→灏榎」类乱码；带 BOM 时
    PS 一定按 UTF-8 读，中文路径原样往返。写入端只此一处，读取端（PS）不再有猜编码空间。
    """
    import tempfile
    fd, p = tempfile.mkstemp(prefix=prefix, suffix=".json")
    with os.fdopen(fd, "w", encoding="utf-8-sig") as fh:
        json.dump(data, fh, ensure_ascii=False)
    return p


def _ps_json(expr, timeout=180):
    """跑一段 PowerShell 并把输出里的 JSON 解析出来（对象/数组都能吃）。"""
    out = ps_text(expr, timeout=timeout)
    if not out or not out.strip():
        return None
    s = out.strip()
    for opener, closer in (("[", "]"), ("{", "}")):
        i, j = s.find(opener), s.rfind(closer)
        if 0 <= i < j:
            try:
                return json.loads(s[i:j + 1])
            except Exception:
                continue
    return None


def _ps_json_file(prefix, payload, expr, timeout=240):
    """写临时 JSON → 让 PowerShell 用 $paths/$names 读它 → 跑 expr → 清理。"""
    p = _dsn_temp_json(prefix, payload)
    try:
        return _ps_json(expr.replace("__JSONPATH__", p.replace("\\", "\\\\")), timeout=timeout)
    finally:
        try:
            os.remove(p)
        except Exception as _e_r19:
            _degrade("_ps_json_file", _e_r19)


def _as_list(v):
    if v is None:
        return []
    if isinstance(v, list):
        return v
    return [v]


def _ft_str(ft):
    """FILETIME(100ns since 1601) → 'YYYY-MM-DD HH:MM:SS'（本地时间，越界返回空）。"""
    try:
        ft = int(ft)
        if ft <= 0:
            return ""
        epoch = ft / 10000000.0 - 11644473600
        if epoch < 946684800 or epoch > time.time() + 86400 * 2:   # 2000-01-01 ~ 现在+2天
            return ""
        return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(epoch))
    except Exception:
        return ""


def _ft_epoch(ft):
    try:
        ft = int(ft)
        if ft <= 0:
            return 0
        epoch = int(ft / 10000000.0 - 11644473600)
        return epoch if 946684800 <= epoch <= time.time() + 86400 * 2 else 0
    except Exception:
        return 0


def _b2ft(b):
    """8 字节小端 FILETIME → epoch（无效返回 0）。"""
    try:
        return _ft_epoch(int.from_bytes(b[:8], "little"))
    except Exception:
        return 0


def _rot13(s):
    out = []
    for ch in s:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + 13) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + 13) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)


def _hexbytes(text):
    """reg query 输出的十六进制串 → bytes。"""
    h = re.sub(r"[^0-9a-fA-F]", "", text or "")
    if len(h) % 2:
        h = h[:-1]
    try:
        return bytes.fromhex(h)
    except Exception:
        return b""


def _dossier_norm(path):
    """路径归一：去引号、去设备前缀、正斜杠转反斜杠、转小写（仅用于比较）。"""
    p = str(path or "").strip().strip('"').strip("'")
    for pre in DOSSIER_DEV_PREFIX:
        if p.startswith(pre):
            p = p[len(pre):]
    return p.replace("/", "\\").lower()


def _dossier_base(path):
    """取文件名（路径可能带参数/引号/设备前缀）。"""
    p = _dossier_norm(path)
    if not p:
        return ""
    return p.rstrip("\\").split("\\")[-1]


def _dossier_is_sysdir(path):
    p = _dossier_norm(path)
    if not p:
        return False
    root = _dossier_norm(os.environ.get("SystemRoot") or "C:\\Windows").rstrip("\\")
    if p.startswith(root + "\\") and not any(h in p for h in DOSSIER_TEMP_HINTS):
        return True      # C:\Windows 及其子目录都算系统目录（临时/字体/任务目录除外）
    return any(h in p for h in DOSSIER_SYSDIRS)


def _dossier_is_temp(path):
    p = _dossier_norm(path)
    return bool(p) and any(h in p for h in DOSSIER_TEMP_HINTS)


def _dossier_is_windows_root(path):
    p = _dossier_norm(path)
    root = _dossier_norm(os.environ.get("SystemRoot") or "C:\\Windows").rstrip("\\")
    return p.startswith(root + "\\") and "\\" not in p[len(root) + 1:]


def _dossier_is_loose(path):
    """松散位置：桌面/文档/盘根 exe、Windows 根目录、用户目录与 AppData/ProgramData 根下直接放文件。"""
    p = _dossier_norm(path)
    if not p or _dossier_is_sysdir(p):
        return False
    if any(h in p for h in DOSSIER_LOOSE_HINTS):
        return True
    parts = [x for x in p.split("\\") if x]
    if len(parts) == 2 and parts[0].endswith(":"):
        return True
    joined = "\\" + "\\".join(parts) + "\\"
    for root in ("USERPROFILE", "LOCALAPPDATA", "APPDATA", "ProgramData"):
        v = os.environ.get(root)
        if not v:
            continue
        r = _dossier_norm(v).rstrip("\\")
        if joined.startswith(r + "\\"):
            rest = joined[len(r) + 1:].strip("\\")
            if rest and "\\" not in rest:
                return True
    return False


def _dossier_is_good(path):
    """标准安装位置：Windows 目录、Program Files、AppData\\Local\\Programs（用户级安装）。"""
    p = _dossier_norm(path)
    if not p or _dossier_is_temp(p):
        return False
    if _dossier_is_sysdir(p):
        return True
    if "\\program files\\" in p or "\\program files (x86)\\" in p:
        return True
    for root in ("LOCALAPPDATA", "APPDATA"):
        v = os.environ.get(root)
        if v:
            r = _dossier_norm(v).rstrip("\\") + "\\programs\\"
            if p.startswith(r):
                return True
    return False


def _pf_blank():
    """Prefetch 解析结果骨架（R15/A6：原先 _pf_parse 与 _dossier_pf 各写一份字面量，现共用一份）。"""
    return {"last": "", "last_epoch": 0, "runs": 0, "exe": "", "conf": ""}


def _pf_parse(blob):
    """解析 Prefetch 头部：返回 {last(filetimestr), last_epoch, runs, exe, conf}。

    Win10 的 .pf 常被 MAM 压缩（头 4 字节 'MAM'），压缩包解不开，此时返回 conf='压缩'，
    调用方退回用 .pf 文件自身的创建/修改时间（首跑/末跑）。偏移用「落在合理区间」来校验，
    避免把随机字节当成时间。
    """
    r = _pf_blank()
    if not blob or len(blob) < 0x100:
        return r
    if blob[:3] == b"MAM":
        r["conf"] = "压缩"
        return r
    if blob[4:8] != b"SCCA":
        r["conf"] = "格式"
        return r
    try:
        name = blob[0x10:0x4C].decode("utf-16-le", "ignore").split("\x00")[0]
        r["exe"] = name.strip()
    except Exception as _e_r19:
        _degrade("_pf_parse", _e_r19)
    for off in (0x80, 0x60, 0x98, 0xD0, 0x78):
        ft = int.from_bytes(blob[off:off + 8], "little")
        if _ft_epoch(ft):
            r["last"] = _ft_str(ft)
            r["last_epoch"] = _ft_epoch(ft)
            break
    for off in (0x98, 0xD0, 0x90, 0x9C):
        n = int.from_bytes(blob[off:off + 4], "little")
        if 0 < n < 1000000:
            r["runs"] = n
            break
    r["conf"] = "解析" if r["last_epoch"] else ""
    return r


def _dossier_globals(c, opts):
    """一次性批量采集所有目标相关的主机数据（避免逐个目标反复起 PowerShell）。"""
    bulk = {"files": {}, "pf": {}, "bam": {}, "dam": {}, "ua": [], "tasks": [], "services": [],
            "runkeys": [], "startup": [], "wmi": [], "procs": [], "net": {}, "evt": {},
            "apps": [], "dl": [], "bits": ""}

    # ---------- 进程快照（执行时间 + 父进程 + 关联端口的基础）
    procs = _ps_json(
        "Get-CimInstance Win32_Process | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,"
        "CommandLine,@{n='start_epoch';e={[long](Get-Date -Date ($_.CreationDate.ToUniversalTime()) -UFormat %s)}},"
        "@{n='start_local';e={$_.CreationDate.ToString('yyyy-MM-dd HH:mm:ss')}} | ConvertTo-Json -Depth 3",
        timeout=120)
    bulk["procs"] = _as_list(procs)

    # ---------- UserAssist（运行次数 + 最后运行；值名是 ROT13）
    ua = _ps_json("""
$ErrorActionPreference='SilentlyContinue'
$base='HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\UserAssist'
Get-ChildItem $base -ErrorAction SilentlyContinue | ForEach-Object {
  $g=$_.PSChildName
  $it=Get-Item (Join-Path $base ($g+'\\Count')) -ErrorAction SilentlyContinue
  if ($it) {
    foreach ($n in $it.GetValueNames()) {
      $d=$it.GetValue($n)
      if ($d -is [byte[]] -and $d.Length -ge 68) {
        $run=[BitConverter]::ToInt32($d,4)
        $t=''
        foreach ($off in 60,16) {
          try { $dt=[DateTime]::FromFileTime([BitConverter]::ToInt64($d,$off))
                if ($dt.Year -ge 2000 -and $dt.Year -le 2100) { $t=$dt.ToString('yyyy-MM-dd HH:mm:ss'); break } } catch {}
        }
        if ($t) { [pscustomobject]@{ guid=$g; name=$n; runs=$run; last=$t } }
      }
    }
  }
}
""", timeout=180)
    bulk["ua"] = _as_list(ua)

    # ---------- 持久化：注册表整表匹配
    for key, label in DOSSIER_REG_KEYS:
        extra = (DOSSIER_REG_NOSUB.get(key) or "/s").split()
        res = win_cmd(["reg", "query", key] + extra, timeout=25)
        out, err = res[0], res[1]
        if not out or cmd_failure(out, err, res.rc, what="reg query %s" % key) \
                or len(out) > 4 * 1024 * 1024:   # R20/P3：失败只看 rc/错误流
            continue
        for ln in out.splitlines():
            s = ln.strip()
            if not s or s.upper().startswith("HKEY_") or "REG_" not in s.upper():
                continue
            if len(bulk["runkeys"]) >= 800:
                break
            bulk["runkeys"].append({"kind": label, "key": key, "line": s})

    # ---------- 持久化：启动文件夹（含 .lnk 目标）
    startup = _ps_json("""
$ErrorActionPreference='SilentlyContinue'
$dirs=@("$env:APPDATA\\Microsoft\\Windows\\Start Menu\\Programs\\Startup",
        "$env:ProgramData\\Microsoft\\Windows\\Start Menu\\Programs\\Startup")
$sh=New-Object -ComObject WScript.Shell
foreach ($d in $dirs) {
  Get-ChildItem -LiteralPath $d -Force -ErrorAction SilentlyContinue | ForEach-Object {
    $t=''
    if ($_.Extension -eq '.lnk') { $t=$sh.CreateShortcut($_.FullName).TargetPath }
    [pscustomobject]@{ dir=$d; name=$_.Name; target=$t
      created_local=$_.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')
      created_epoch=[long](Get-Date -Date $_.CreationTimeUtc -UFormat %s) }
  }
}
""", timeout=120)
    bulk["startup"] = _as_list(startup)

    # ---------- 持久化：计划任务（任务 XML = 建立时间/作者/命令行）
    tasks = _ps_json(r"""
$ErrorActionPreference='SilentlyContinue'
$root=Join-Path $env:WINDIR 'System32\\Tasks'
Get-ChildItem -LiteralPath $root -Recurse -File -Force -ErrorAction SilentlyContinue | ForEach-Object {
  $t = Get-Content -LiteralPath $_.FullName -Raw -ErrorAction SilentlyContinue
  if ($t) {
    [pscustomobject]@{ rel=$_.FullName.Substring($root.Length+1); full=$_.FullName
      mtime_local=$_.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss')
      mtime_epoch=[long](Get-Date -Date $_.LastWriteTimeUtc -UFormat %s)
      ctime_local=$_.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')
      ctime_epoch=[long](Get-Date -Date $_.CreationTimeUtc -UFormat %s)
      text=$t }
  }
}
""", timeout=240)
    for it in _as_list(tasks):
        if not (isinstance(it, dict) and it.get("text")):
            continue
        if len(bulk["tasks"]) >= 400:
            break
        m = re.search(r"<Date>([^<]+)</Date>", it["text"], re.I)
        au = re.search(r"<Author>([^<]+)</Author>", it["text"], re.I)
        cm = re.findall(r"<Command>([^<]+)</Command>", it["text"], re.I)
        ag = re.findall(r"<Arguments>([^<]+)</Arguments>", it["text"], re.I)
        it["date"] = (m.group(1) if m else "").strip()
        it["author"] = (au.group(1) if au else "").strip()
        it["command"] = " / ".join([x.strip() for x in cm][:2])
        it["args"] = " ".join([x.strip() for x in ag][:2])
        bulk["tasks"].append(it)

    # ---------- 持久化：服务
    svc = _ps_json("Get-CimInstance Win32_Service | Select-Object Name,DisplayName,PathName,StartMode,"
                   "State,StartName | ConvertTo-Json -Depth 3", timeout=150)
    bulk["services"] = _as_list(svc)

    # ---------- 持久化：WMI 事件订阅
    wmi = _ps_json(r"""
$ErrorActionPreference='SilentlyContinue'
$ns='root\\subscription'
Get-CimInstance -Namespace $ns -ClassName __EventFilter -ErrorAction SilentlyContinue |
  Select-Object @{n='cls';e={'__EventFilter'}},Name,Query | ConvertTo-Json -Depth 3
""", timeout=120)
    wmi2 = _ps_json(r"""
$ErrorActionPreference='SilentlyContinue'
Get-CimInstance -Namespace root\subscription -ClassName CommandLineEventConsumer -ErrorAction SilentlyContinue |
  Select-Object @{n='cls';e={'CommandLineEventConsumer'}},Name,CommandLineTemplate,ExecutablePath | ConvertTo-Json -Depth 3
""", timeout=120)
    wmi3 = _ps_json(r"""
$ErrorActionPreference='SilentlyContinue'
Get-CimInstance -Namespace root\subscription -ClassName ActiveScriptEventConsumer -ErrorAction SilentlyContinue |
  Select-Object @{n='cls';e={'ActiveScriptEventConsumer'}},Name,ScriptText | ConvertTo-Json -Depth 3
""", timeout=120)
    bulk["wmi"] = _as_list(wmi) + _as_list(wmi2) + _as_list(wmi3)

    # ---------- 网络：当前连接（按 PID 归并，供“外联/监听”判定）
    conns = _ps_json("Get-NetTCPConnection -ErrorAction SilentlyContinue | "
                     "Select-Object LocalAddress,LocalPort,RemoteAddress,RemotePort,State,OwningProcess | "
                     "ConvertTo-Json -Depth 3", timeout=150)
    for it in _as_list(conns):
        try:
            bulk["net"].setdefault(int(it.get("OwningProcess") or 0), []).append(it)
        except Exception as _e_r19:
            _degrade("_dossier_globals", _e_r19)

    # ---------- BITS 后台传输（可被滥用为下载器/持久化）
    out, _ = win_cmd(["bitsadmin", "/list", "/allusers", "/verbose"], timeout=90)
    bulk["bits"] = out or ""

    # ---------- 已安装程序（给“落地时间是否等于安装时间”做旁证）
    apps = _ps_json(r"""
$ErrorActionPreference='SilentlyContinue'
$keys=@('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*')
Get-ItemProperty $keys -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName } |
  Select-Object DisplayName,DisplayVersion,Publisher,InstallLocation,InstallDate | ConvertTo-Json -Depth 3
""", timeout=180)
    bulk["apps"] = _as_list(apps)
    return bulk


def _dossier_filefacts(c, paths, bulk, opts):
    # ---------- 文件本体（大小/三种时间/属性/签名/数据流/Zone.Identifier）
    files = _ps_json_file("er_dsn_paths_", paths, r"""
$ErrorActionPreference='SilentlyContinue'
$paths = Get-Content -LiteralPath '__JSONPATH__' -Raw -Encoding UTF8 | ConvertFrom-Json
$res = foreach ($p in $paths) {
  $i = Get-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue
  if ($null -eq $i) { [pscustomobject]@{ path=$p; missing=$true }; continue }
  $sg = Get-AuthenticodeSignature -LiteralPath $p -ErrorAction SilentlyContinue
  $st = @(Get-Item -LiteralPath $p -Stream * -ErrorAction SilentlyContinue | ForEach-Object { $_.Stream })
  $z  = (Get-Content -LiteralPath $p -Stream Zone.Identifier -ErrorAction SilentlyContinue | Out-String)
  [pscustomobject]@{
    path = $i.FullName
    size = [long]$i.Length
    created_epoch  = [long](Get-Date -Date $i.CreationTimeUtc -UFormat %s)
    created_local  = $i.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')
    modified_epoch = [long](Get-Date -Date $i.LastWriteTimeUtc -UFormat %s)
    modified_local = $i.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss')
    accessed_local = $i.LastAccessTime.ToString('yyyy-MM-dd HH:mm:ss')
    attrs  = $i.Attributes.ToString()
    sig    = "$($sg.Status)"
    signer = "$($sg.SignerCertificate.Subject)"
    sig_valid_to = if ($sg.SignerCertificate) { $sg.SignerCertificate.NotAfter.ToString('yyyy-MM-dd') } else { '' }
    streams = ($st -join '|')
    zone = ($z -replace "`r?`n", ' ').Trim()
  }
}
$res | ConvertTo-Json -Depth 4
""", timeout=300)
    for it in _as_list(files):
        if isinstance(it, dict) and it.get("path"):
            bulk["files"][it["path"].lower()] = it


def _dossier_pf(c, names, bulk, opts):
    # ---------- Prefetch：文件时间 + 头部解析（首跑=文件创建，末跑=文件修改）
    pf = _ps_json_file("er_dsn_names_", names, r"""
$ErrorActionPreference='SilentlyContinue'
$names = Get-Content -LiteralPath '__JSONPATH__' -Raw -Encoding UTF8 | ConvertFrom-Json
$pfdir = Join-Path $env:WINDIR 'Prefetch'
foreach ($n in $names) {
  Get-ChildItem -LiteralPath $pfdir -Filter "$n-*.pf" -ErrorAction SilentlyContinue | ForEach-Object {
    [pscustomobject]@{
      name = $n; file = $_.FullName
      created_epoch = [long](Get-Date -Date $_.CreationTimeUtc -UFormat %s)
      created_local = $_.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')
      modified_epoch = [long](Get-Date -Date $_.LastWriteTimeUtc -UFormat %s)
      modified_local = $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss')
    }
  }
}
""", timeout=180)
    for it in _as_list(pf):
        if isinstance(it, dict) and it.get("file"):
            try:
                with open(it["file"], "rb") as fh:
                    hit = _pf_parse(fh.read(4096))
            except Exception as e:
                hit = _pf_blank()
            it.update(hit)
            bulk["pf"].setdefault((it.get("name") or "").lower(), []).append(it)


def _dossier_bam(c, names, bulk, opts):
    # ---------- BAM / DAM（最后执行时间，需管理员）
    for svc, slot in (("bam", "bam"), ("dam", "dam")):
        res = win_cmd(["reg", "query",
                       r"HKLM\SYSTEM\CurrentControlSet\Services\%s\State\UserSettings" % svc,
                       "/s"], timeout=90)
        out = res[0]
        fail = cmd_failure(out, res[1], res.rc, what="reg query %s\\State\\UserSettings" % svc)
        if fail:                             # R20/P3：失败只看 rc/错误流
            c.warn("BAM/DAM 执行历史不可读（需管理员权限）：%s\\State\\UserSettings（%s）"
                   % (svc, fail["text"]))
            continue
        cur = ""
        for ln in (out or "").splitlines():
            s = ln.strip()
            if s.lower().startswith("hkey_"):
                cur = s
                continue
            m = re.match(r"^(\S.*?)\s+(REG_BINARY|REG_SZ)\s+([0-9a-fA-F]+)\s*$", s)
            if not m:
                continue
            val, kind, data = m.group(1), m.group(2), m.group(3)
            base = _dossier_base(val).lower()
            if base in names or any(base == n for n in names):
                ep = _b2ft(_hexbytes(data)) or _b2ft(_hexbytes(data)[8:16])
                if ep:
                    bulk[slot][base] = {"path": val, "epoch": ep,
                                        "time": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ep))}

def _dossier_extract_path(line, name):
    """从注册表值/任务命令行里抠出可执行文件路径（带引号优先，其次 UNC/裸路径）。"""
    s = (line or "").strip()
    m = re.search(r'"([A-Za-z]:\\[^"]+\.(?:exe|dll|com|scr|bat|cmd|ps1|vbs|js|jse|wsf|hta|jar|py))"', s, re.I)
    if m:
        return m.group(1)
    m = re.search(r'"?(\\\\[^"<>|\r\n]+?\.(?:exe|dll|com|scr|bat|cmd|ps1|vbs|js|hta))"?', s, re.I)
    if m:
        return m.group(1).strip()
    m = re.search(r'([A-Za-z]:\\[^"<>|\r\n]*?\.(?:exe|dll|com|scr|bat|cmd|ps1|vbs|js|jse|wsf|hta))(?:\s|$|")', s, re.I)
    if m:
        return m.group(1).strip()
    if name and name.lower() in s.lower():
        return name
    return ""


def _dossier_persist_index(bulk):
    """把全机持久化位置整理成 {文件名: {reg/task/svc/startup/wmi/paths}}，供候选打分与证据引用。"""
    idx = {}

    def slot(path):
        n = _dossier_base(path)
        if not n or "." not in n:
            return None
        return idx.setdefault(n, {"reg": [], "task": [], "svc": [], "startup": [], "wmi": [], "paths": []})

    for r in bulk.get("runkeys") or []:
        p = _dossier_extract_path(r.get("line") or "", None)
        s = slot(p)
        if s:
            s["reg"].append(r)
            s["paths"].append(p)
    for t in bulk.get("tasks") or []:
        p = _dossier_extract_path(((t.get("command") or "") + " " + (t.get("args") or "")).strip(), None)
        s = slot(p)
        if s:
            s["task"].append(t)
            s["paths"].append(p)
    for sv in bulk.get("services") or []:
        p = _dossier_extract_path(sv.get("PathName") or "", None)
        s = slot(p)
        if s:
            s["svc"].append(sv)
            s["paths"].append(p)
    for st in bulk.get("startup") or []:
        p = st.get("target") or st.get("name") or ""
        s = slot(p)
        if s:
            s["startup"].append(st)
            s["paths"].append(p)
    for w in bulk.get("wmi") or []:
        blob = json.dumps(w, ensure_ascii=False)
        for p in re.findall(r'[A-Za-z]:\\\\?[^"\'<>\s|]{2,200}\.(?:exe|dll|ps1|vbs|js|bat|cmd)', blob, re.I):
            s = slot(p)
            if s:
                s["wmi"].append(w)
                s["paths"].append(p)
    return idx


def _dossier_drop_candidates(c, opts, days, limit=60):
    """近期落地在临时/松散目录的可执行文件——投放痕迹，也是恶意程序最常见的藏身处。"""
    exts = (".exe", ".dll", ".scr", ".com", ".bat", ".cmd", ".ps1", ".vbs", ".js", ".hta", ".jse",
            ".wsf", ".msi", ".hta", ".lnk")
    dirs = []
    for k in ("TEMP", "TMP", "PUBLIC", "USERPROFILE", "LOCALAPPDATA", "PROGRAMDATA"):
        v = os.environ.get(k)
        if v and os.path.isdir(v):
            dirs.append(v)
    home = os.environ.get("USERPROFILE") or ""
    for sub in ("Downloads", "Desktop", "AppData\\Local\\Temp"):
        d = os.path.join(home, sub)
        if os.path.isdir(d):
            dirs.append(d)
    cut = time.time() - max(1, days) * 86400
    hits = []
    for d in sorted(set(dirs)):
        try:
            names = os.listdir(d)
        except Exception:
            continue
        for n in names[:600]:
            if not n.lower().endswith(exts):
                continue
            p = os.path.join(d, n)
            if not os.path.isfile(p):
                continue
            try:
                st = os.stat(p)
            except Exception:
                continue
            newest = max(st.st_ctime, st.st_mtime)
            if newest < cut:
                continue
            hits.append((p, (time.time() - newest) / 86400.0))
    hits.sort(key=lambda x: -x[1] * -1)
    hits.sort(key=lambda x: x[1])
    return hits[:limit], len(hits)


def _dossier_candidate_paths(c, opts, bulk, pidx, days):
    """候选路径 = 运行中进程的可执行文件 + 持久化位置引用的文件 + 近期落地可执行文件。"""
    out = []
    for p in (bulk.get("procs") or []):
        ep = p.get("ExecutablePath") or ""
        if ep and ("\\" in ep):
            out.append(ep)
    for v in pidx.values():
        for p in (v.get("paths") or []):
            if p and "\\" in p:
                out.append(p)
    drops, dn = _dossier_drop_candidates(c, opts, days)
    ages = {}
    for p, age in drops:
        out.append(p)
        ages[_dossier_norm(p)] = age
    seen, cands = set(), []
    for p in out:
        k = _dossier_norm(p)
        if not k or k in seen:
            continue
        seen.add(k)
        cands.append(p)
    if len(cands) > 150:
        cands = cands[:150]
    return cands, ages, dn


def _dossier_signals(path, cmdline, pidx, facts, drop_age, opts):
    """打分：只认“位置异常 / 伪装 / 强命令行 / 下载标记 / 持久化指向异常位置”这些硬信号。"""
    k = _dossier_norm(path)
    name = _dossier_base(k)
    score, flags = 0, []
    tmp = _dossier_is_temp(k)
    loose = _dossier_is_loose(k)
    good = _dossier_is_good(k)
    unc = k.startswith("\\\\")
    refs = pidx.get(name) or {}
    nref = len(refs.get("reg") or []) + len(refs.get("task") or []) + len(refs.get("svc") or []) + \
        len(refs.get("startup") or [])
    dot = name.rfind(".")
    stem = name[:dot] if dot > 0 else name
    stem_img = (lambda s2: s2)(stem)
    masq = (name in DOSSIER_MASQ_NAMES or (stem_img in _DOSSIER_MASQ_STEMS)) and not _dossier_is_sysdir(k)
    missing = bool(facts.get("missing")) if facts else False
    sig = (facts.get("sig") or "") if facts else ""
    signer = (facts.get("signer") or "") if facts else ""
    signed = "valid" in sig.lower()
    ms = "microsoft" in signer.lower()
    zone = bool(_dossier_zone_info(facts.get("zone")).get("HostUrl")) if facts else False
    if tmp:
        score += 30
        flags.append("落在临时/落地目录")
    if loose:
        score += 12
        flags.append("落在松散位置")
    if unc:
        score += 40
        flags.append("网络路径(UNC)执行")
    if masq:
        score += 45
        flags.append("伪装系统进程名(%s)" % name)
    hits, strong, weak = cmdline_hits(cmdline or "")
    if strong:
        score += 35
        flags.append("强命令行特征(%s)" % "、".join(hits[:3]))
    elif weak:
        score += 6
        flags.append("命令行可疑(%s)" % "、".join(hits[:2]))
    if zone and not good:
        score += 22
        flags.append("带下载来源标记")
    if nref and tmp:
        score += 28
        flags.append("被持久化引用+落在临时目录")
    elif nref and unc:
        score += 34
        flags.append("被持久化引用+网络路径")
    elif nref and missing:
        score += 12
        flags.append("被持久化引用但文件已不存在")
    elif nref and not good and not signed and not ms:
        score += 15
        flags.append("被持久化引用+无签名非标准目录")
    if refs.get("wmi"):
        score += 35
        flags.append("被 WMI 事件订阅引用")
    if facts and not missing and not signed and not ms and not good:
        score += 6
        flags.append("无数字签名")
    if drop_age is not None and drop_age <= 7 and (tmp or loose):
        score += 18
        flags.append("近期落地(%.1f 天内)" % drop_age)
    return score, flags


# 只靠 exe 主干名就能判定的伪装（避免误伤，限定系统工具名）
_DOSSIER_MASQ_STEMS = tuple(set(n[:-4] for n in DOSSIER_MASQ_NAMES if n.endswith(".exe")))


def _dossier_level_hint(score, flags):
    f = " ".join(flags)
    if ("伪装系统进程名" in f) or ("WMI 事件订阅" in f) or ("被持久化引用+落在临时目录" in f) or \
            ("被持久化引用+网络路径" in f) or (("强命令行特征" in f) and ("被持久化引用" in f)):
        return "严重"
    if score >= 55 or (("带下载来源标记" in f) and ("临时" in f)) or ("强命令行特征" in f) or ("网络路径" in f):
        return "高危"
    if score >= 30:
        return "中危"
    return "提示"


def _r18_dossier_sources(facts, sig, persist, ev, zone, dl, missing, reason, exec_hint=""):
    """画像结论的独立证据来源清单（R18/P2，纯函数）：按采集来源域去重。

    来源域（互不相同的采集面，供通用严重级闸门计数）：
      1) 候选评分/命令行采集（进程列表 + 文件枚举时得到的路径/名称/命令行特征）；
      2) 文件本体事实（Get-Item 属性 / 数字签名 / 哈希——仅在文件本体可读时计入）；
      3) 持久化引用（注册表 / 计划任务 / 服务 / 启动夹 / WMI / BITS 的引用计数）；
      4) 行为事件（Sysmon/4688 的子进程、写文件、改注册表、外联等）；
      5) 执行痕迹（Prefetch / BAM / UserAssist / 进程启动时间）。
    文件本体不可读时不把「文件不存在」当作支持性来源（它不支撑恶意定性）。
    """
    src = [("候选评分/命令行采集（进程列表与文件枚举）",
            ("；".join(reason or []) or "无")[:220])]
    if facts and not missing:
        src.append(("文件本体事实（属性/数字签名/哈希）",
                    "签名=%s" % (sig or "无签名")))
    pref = (len((persist or {}).get("reg") or []) + len((persist or {}).get("task") or []) +
            len((persist or {}).get("svc") or []) + len((persist or {}).get("startup") or []) +
            len((persist or {}).get("wmi") or []) + len((persist or {}).get("bits") or []))
    if pref:
        src.append(("持久化引用", "注册表 %d / 任务 %d / 服务 %d / 启动夹 %d / WMI %d / BITS %d"
                    % (len(persist.get("reg") or []), len(persist.get("task") or []),
                       len(persist.get("svc") or []), len(persist.get("startup") or []),
                       len(persist.get("wmi") or []), len(persist.get("bits") or []))))
    ev = ev or {}
    nev = (len(ev.get("child") or []) + len(ev.get("files") or []) + len(ev.get("reg") or []) +
           len(ev.get("net") or []))
    if nev:
        src.append(("行为事件(Sysmon/4688)", "子进程 %d / 写文件 %d / 改注册表 %d / 外联 %d"
                    % (len(ev.get("child") or []), len(ev.get("files") or []),
                       len(ev.get("reg") or []), len(ev.get("net") or []))))
    if exec_hint:
        src.append(("执行痕迹(Prefetch/BAM/UserAssist/4688)", str(exec_hint)[:200]))
    if zone or dl:
        src.append(("下载来源标记(Zone.Identifier/浏览器下载记录)",
                    ("Zone.Identifier=%s" % ((zone or {}).get("HostUrl") or "有"))
                    if zone else ("浏览器下载记录 %d 条" % len(dl or []))))
    return src


def _dossier_resolve_explicit(c, opts, bulk, pidx):
    """把 --target（路径 / 进程名 / PID）解析成一个具体文件路径。"""
    tgt = str(opts.get("target") or "").strip()
    if not tgt:
        return None, ""
    if re.match(r"^\d+$", tgt):
        for p in (bulk.get("procs") or []):
            if str(p.get("ProcessId")) == tgt:
                return p.get("ExecutablePath") or "", "指定 PID %s（%s）" % (tgt, p.get("Name"))
        return None, "指定 PID %s 未找到对应进程" % tgt
    if "\\" in tgt or "/" in tgt:
        if not os.path.isfile(tgt):
            return None, "指定文件不存在：%s" % tgt
        return tgt, "指定文件"
    # 进程名 / 文件名
    hits = [p.get("ExecutablePath") for p in (bulk.get("procs") or [])
            if _dossier_base(p.get("ExecutablePath") or "") == tgt.lower()]
    hits = [h for h in hits if h]
    if hits:
        return hits[0], "指定进程名（运行中）"
    for v in pidx.values():
        for p in (v.get("paths") or []):
            if _dossier_base(p) == tgt.lower():
                return p, "指定文件名（持久化位置引用）"
    return None, "没有找到名为 %s 的运行中进程或持久化引用（可改用完整路径）" % tgt


def _dossier_select(c, opts, bulk, pidx, cands, ages, maxn):
    """打分 → 排序 → 取前 maxn 个（强制上限，防止报告被候选淹没）。"""
    procs = {}
    for p in (bulk.get("procs") or []):
        ep = p.get("ExecutablePath") or ""
        if ep:
            procs.setdefault(_dossier_norm(ep), []).append(p)
    explicit, exp_note = _dossier_resolve_explicit(c, opts, bulk, pidx)
    pool = []
    for path in cands:
        k = _dossier_norm(path)
        pr = procs.get(k) or []
        cmd = (pr[0].get("CommandLine") or "") if pr else ""
        facts = bulk["files"].get(str(path).lower()) or {}
        score, flags = _dossier_signals(path, cmd, pidx, facts, ages.get(k), opts)
        src = []
        if pr:
            src.append("运行中进程")
        nm = _dossier_base(k)
        refs = pidx.get(nm) or {}
        for kind, label in (("reg", "启动项"), ("task", "计划任务"), ("svc", "系统服务"), ("startup", "启动夹"),
                            ("wmi", "WMI 订阅")):
            if refs.get(kind):
                src.append(label)
        if k in ages:
            src.append("近期落地文件")
        if explicit and _dossier_norm(explicit) == k:
            src.append("指定目标")
        if not src and not score:
            continue
        pool.append({"path": path, "name": nm, "ext": nm.rsplit(".", 1)[-1] if "." in nm else "",
                     "score": score, "flags": flags,
                     "level_hint": _dossier_level_hint(score, flags),
                     "source": " / ".join(dict.fromkeys(src)) or "全机扫描",
                     "pid": pr[0].get("ProcessId") if pr else None,
                     "start_epoch": 0, "start_local": "",
                     "cmdline": cmd})
    pool.sort(key=lambda t: (-t["score"], t["path"]))
    scriptish = ("ps1", "js", "vbs", "vbe", "bat", "cmd", "hta", "jse", "wsf", "py", "jar")
    hot = []
    for t in pool:
        if t["score"] < 30:
            continue
        fl = " ".join(t["flags"])
        if t.get("ext") in scriptish and not any(
                key in fl for key in ("带下载来源标记", "被持久化引用", "强命令行", "伪装系统进程名",
                                      "WMI 事件订阅", "网络路径")):
            continue      # 脚本类只看硬信号：光“落在临时目录”不立案（临时目录里脚本太多了）
        hot.append(t)
    sel = hot[:maxn]
    if explicit:
        ek = _dossier_norm(explicit)
        if not any(_dossier_norm(t["path"]) == ek for t in sel):
            for t in pool:
                if _dossier_norm(t["path"]) == ek:
                    sel = [t] + sel[:maxn - 1] if maxn > 1 else [t]
                    break
            else:
                facts = bulk["files"].get(str(explicit).lower()) or {}
                sc, fl = _dossier_signals(explicit, "", pidx, facts, None, opts)
                sel = [{"path": explicit, "name": _dossier_base(explicit), "score": sc, "flags": fl,
                        "level_hint": _dossier_level_hint(sc, fl), "source": "指定目标",
                        "pid": None, "start_epoch": 0, "start_local": "", "cmdline": ""}] + sel[:maxn - 1]
        if exp_note:
            c.add("提示", "恶意程序画像", "已按指定目标画像", exp_note)
    more = max(0, len(hot) - len(sel))
    low = len(pool) - len(hot)
    # 当前进程启动时间（"正在运行"的直观证据）
    for t in sel:
        pr = procs.get(_dossier_norm(t["path"])) or []
        if pr:
            t["start_local"] = pr[0].get("start_local") or ""
            t["start_epoch"] = int(pr[0].get("start_epoch") or 0)
    return sel, low, more


def _evt_scope(days):
    return int(max(1, days) * 86400 * 1000)


def _evt_query(c, channel, ids, win_ms=None, count=60, timeout=240, tail="", label="", stat=True):
    """查事件日志（R16：并入统一分页取数机制）。返回 [(epoch, 时间串, {字段:值})] 或 None。

    旧实现接收裸 XPath；而画像里的字段过滤写在 XPath 里（contains()），事件过滤器并不支持该
    算子（实测 wevtutil 直接报 “This operator is unsupported”，静默查不到任何事件）。R16 起
    统一改为「ids + 时间窗」分页取数，字段过滤由调用方在内存完成——与 _adv_query 同一条路径，
    不再长期并存两套取数口径。
    """
    got, _why = _evt_fetch(c, channel, ids, win_ms=win_ms, count=count, timeout=timeout,
                           tail=tail, label=label or "画像事件", stat=stat)
    return got


def _dossier_events(c, t, opts, bulk):
    """事件日志侧的行为证据：执行记录、子进程、建账号、装服务、Sysmon 深挖。"""
    name = _dossier_base(t.get("path") or "").lower()
    ev = {"exec": [], "child": [], "accounts": [], "services": [], "behaviors": [], "files": [],
          "net": [], "reg": [], "channel": {}}
    if not name:
        return ev
    chans, _ = win_cmd(["wevtutil", "el"], timeout=60)
    chans = chans or ""
    has_security = "Security" in chans
    sysmon = "Microsoft-Windows-Sysmon/Operational"
    has_sysmon = sysmon in chans
    ev["channel"] = {"security": has_security, "sysmon": has_sysmon}

    # 进程创建：本程序的执行记录（首/末跑）+ 它拉起/被谁拉起
    if has_security:
        win = _evt_scope(c.days)
        got = _evt_query(c, "Security", ("4688",), win, count=1500,
                         label="画像-4688 进程创建") or []
        ev["exec"] = [x for x in got if name in (x[2].get("NewProcessName") or "").lower()]
        pid = t.get("pid")
        if pid:
            got2 = _evt_query(c, "Security", ("4688",), win, count=1500,
                              label="画像-4688 进程创建") or []
            ev["child"] = [x for x in got2
                           if str(pid) == str(x[2].get("CreatorProcessId") or "").strip()]

    # 账号 / 服务 / 任务：按天数窗口取，关联到时间线
    if has_security:
        win = _evt_scope(c.days)
        got = _evt_query(c, "Security",
                         ("4720", "4722", "4724", "4726", "4728", "4732", "4735",
                          "7045", "4697", "4698"), win, count=1200,
                         label="画像-账号/服务/任务事件")
        for ep, iso, d in (got or []):
            eid = (d.get("_EventID") or "").strip()
            blob = " ".join("%s=%s" % (k, v) for k, v in sorted(d.items())
                            if v and not k.startswith("_"))[:400]
            rec = {"epoch": ep, "time": iso, "eid": eid, "data": d, "blob": blob}
            if eid in ("4720", "4722", "4724", "4726", "4728", "4732", "4735"):
                ev["accounts"].append(rec)
            elif eid in ("7045", "4697", "4698", "4699", "4700", "4701", "4702"):
                ev["services"].append(rec)
            else:
                ev["behaviors"].append(rec)

    # Sysmon：1 进程创建 / 3 网络 / 11 文件落地 / 13 注册表写入
    if has_sysmon:
        win = _evt_scope(c.days)
        s1 = _evt_query(c, sysmon, ("1",), win, count=20000, timeout=300,
                        label="归因-Sysmon 1 进程创建") or []
        ev["child"] += [x for x in s1 if name in (x[2].get("ParentImage") or "").lower()]
        s3 = _evt_query(c, sysmon, ("3",), win, count=6000, label="画像-Sysmon 3 网络连接") or []
        ev["net"] = [x for x in s3 if name in (x[2].get("Image") or "").lower()]
        s11 = _evt_query(c, sysmon, ("11",), win, count=8000, label="归因-Sysmon 11 文件创建") or []
        ev["files"] = [x for x in s11 if name in (x[2].get("Image") or "").lower()]
        s13 = _evt_query(c, sysmon, ("13",), win, count=8000, label="画像-Sysmon 13 注册表写入") or []
        ev["reg"] = [x for x in s13 if name in (x[2].get("Image") or "").lower()]
    else:
        c.warn("未安装/未运行 Sysmon：子进程、文件落地、注册表写入只能靠 4688 与文件时间推断")
    return ev


def _dossier_browser_downloads(path, name):
    """从 Edge/Chrome 下载库找这个文件的下载时间与来源 URL（拷副本再读，不动原库）。"""
    found = []
    try:
        import sqlite3
        import shutil
        import tempfile
    except Exception:
        return found
    roots = []
    for env, sub in (("LOCALAPPDATA", r"Microsoft\Edge\User Data"),
                     ("LOCALAPPDATA", r"Google\Chrome\User Data"),
                     ("LOCALAPPDATA", r"BraveSoftware\Brave-Browser\User Data"),
                     ("LOCALAPPDATA", r"360Chrome\Chrome\User Data")):
        v = os.environ.get(env)
        if v:
            roots.append(os.path.join(v, sub))
    for root in roots:
        if not os.path.isdir(root):
            continue
        try:
            profs = [d for d in os.listdir(root) if d == "Default" or d.startswith("Profile")]
        except Exception:
            continue
        for prof in profs:
            hist = os.path.join(root, prof, "History")
            if not os.path.isfile(hist):
                continue
            tmp = os.path.join(tempfile.gettempdir(), "er_hist_%d_%s.db" % (os.getpid(), abs(hash(hist)) % 9999))
            try:
                shutil.copy2(hist, tmp)
                con = sqlite3.connect(tmp)
                cur = con.cursor()
                cur.execute("SELECT target_path, tab_url, start_time, total_bytes, mime_type "
                            "FROM downloads ORDER BY start_time DESC LIMIT 400")
                for tp, url, st, size, mime in cur.fetchall():
                    tp = tp or ""
                    if not tp:
                        continue
                    if (name and _dossier_base(tp).lower() == name) or (path and tp.lower() == path.lower()):
                        ep = int((st or 0) // 1000000 - 11644473600) if st else 0
                        found.append({"browser": os.path.basename(root.split("User Data")[0].rstrip("\\")) or root,
                                      "profile": prof, "target": tp, "url": url or "", "epoch": ep,
                                      "time": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ep)) if ep else "",
                                      "size": size, "mime": mime or ""})
                con.close()
            except Exception:
                continue
            finally:
                try:
                    os.remove(tmp)
                except Exception as _e_r19:
                    _degrade("_dossier_browser_downloads", _e_r19)
    return found


def _dossier_siblings(path, created_epoch, window=900):
    """同目录里与目标几乎同时落地的文件（一批投放的同伴）。"""
    out = []
    d = os.path.dirname(path)
    if not d or not os.path.isdir(d) or not created_epoch:
        return out
    try:
        for fn in os.listdir(d):
            fp = os.path.join(d, fn)
            try:
                if not os.path.isfile(fp):
                    continue
                ctime = os.path.getctime(fp)
            except Exception:
                continue
            if fp.lower() == path.lower():
                continue
            if abs(ctime - created_epoch) <= window:
                out.append("%s（%s）" % (fp, time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ctime))))
    except Exception as _e_r19:
        _degrade("_dossier_siblings", _e_r19)
    return out[:20]

def _dossier_zone_info(txt):
    """解析 Zone.Identifier 文本 → {ZoneId, HostUrl, ReferrerUrl}。"""
    out = {}
    for k in ("ZoneId", "HostUrl", "ReferrerUrl"):
        m = re.search(k + r"\s*=\s*(.*?)(?:\s+(?:ZoneId|HostUrl|ReferrerUrl)\s*=|$)", txt or "", re.S)
        if m and m.group(1).strip():
            out[k] = m.group(1).strip()[:300]
    return out


def _dsn_size(n):
    try:
        n = float(n)
    except Exception:
        return "-"
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return ("%.0f%s" % (n, unit)) if unit == "B" else ("%.1f%s" % (n, unit))
        n /= 1024.0
    return "-"


def _dossier_persist_hits(bulk, name):
    """目标文件名命中的全部持久化位置。"""
    n = (name or "").lower()
    out = {"reg": [], "task": [], "svc": [], "startup": [], "wmi": [], "bits": []}
    if not n:
        return out
    for r in bulk.get("runkeys") or []:
        if n in (r.get("line") or "").lower():
            out["reg"].append(r)
    for t in bulk.get("tasks") or []:
        if n in (t.get("text") or "").lower():
            out["task"].append(t)
    for s in bulk.get("services") or []:
        if n in (s.get("PathName") or "").lower():
            out["svc"].append(s)
    for s in bulk.get("startup") or []:
        blob = ((s.get("target") or "") + " " + (s.get("name") or "")).lower()
        if n in blob:
            out["startup"].append(s)
    for w in bulk.get("wmi") or []:
        if n in json.dumps(w, ensure_ascii=False).lower():
            out["wmi"].append(w)
    if n in (bulk.get("bits") or "").lower():
        out["bits"].append("BITS 后台传输任务中出现该文件名")
    return out


def _beh_blank():
    """全机行为关联骨架（R15/A6：原先 _dossier_behaviors 与 win_malware_dossier 各写一份字面量，现共用一份）。"""
    return {"accounts": [], "services": [], "other": [], "channel": {}, "audited": {}}


def _dossier_behaviors(c, opts):
    """全机行为事件（一次采集）：建账号、装服务/建任务、审计策略与日志清空。"""
    cat = "恶意程序画像"
    beh = _beh_blank()
    chans, _ = win_cmd(["wevtutil", "el"], timeout=60)
    chans = chans or ""
    if "Security" not in chans:
        c.warn("安全日志通道不可用：账号/服务/任务类行为无法从事件日志确认")
        return beh
    beh["channel"]["security"] = True
    win = _evt_scope(c.days)
    got = _evt_query(c, "Security",
                     ("4720", "4722", "4724", "4726", "4728", "4732", "4735", "7045",
                      "4697", "4698", "4702", "4794", "1102"), win, count=1200, timeout=300,
                     label="画像-账号/服务/任务行为")
    if got is None:
        c.warn("安全日志查询失败（多半是权限不足）：请用管理员身份重跑，才能拿到创建账号/安装服务等行为证据")
        return beh
    for ep, iso, d in got:
        eid = (d.get("_EventID") or "").strip()
        blob = " ".join("%s=%s" % (k, v) for k, v in sorted(d.items())
                        if v and not k.startswith("_"))[:400]
        rec = {"epoch": ep, "time": iso, "eid": eid, "data": d, "blob": blob}
        if eid in ("4720", "4722", "4724", "4726", "4728", "4732", "4735", "4794"):
            beh["accounts"].append(rec)
        elif eid in ("7045", "4697", "4698", "4702"):
            beh["services"].append(rec)
        else:
            beh["other"].append(rec)
    # 有没有开进程创建审核（4688）——没有的话“它拉起了什么进程”只能靠现场快照
    chk = _evt_query(c, "Security", ("4688",), win, count=1, timeout=180,
                     label="画像-4688 审核探测", stat=False)
    beh["audited"]["4688"] = bool(chk)
    if not chk:
        c.warn("安全日志中没有 4688 进程创建事件：说明未开启“审核进程创建”，"
               "历史进程拉起关系无法还原（建议先开审核：auditpol /set /subcategory:\"进程创建\" /success:enable）")
    return beh


def _dossier_one(c, t, bulk, opts, beh):
    """给一个程序出画像：源文件 / 落地 / 下载 / 执行 / 持久化 / 行为 / 时间线。"""
    cat = "恶意程序画像"
    path = t.get("path") or ""
    name = t.get("name") or _dossier_base(path)
    lname = name.lower()
    facts = bulk["files"].get(path.lower()) or bulk["files"].get(_dossier_norm(path)) or {}
    missing = bool(facts.get("missing"))
    tmp = _dossier_is_temp(path)
    good = _dossier_is_good(path)
    masq = lname in DOSSIER_MASQ_NAMES and not good
    unc = path.lower().startswith("\\\\")
    sig = (facts.get("sig") or "").strip()
    signer = (facts.get("signer") or "").strip()
    ms_signed = ("microsoft" in signer.lower()) and ("valid" in sig.lower())
    zone = _dossier_zone_info(facts.get("zone"))
    persist = _dossier_persist_hits(bulk, name)
    pf = (bulk["pf"].get(lname) or [])
    bam = bulk["bam"].get(lname) or {}
    dam = bulk["dam"].get(lname) or {}
    ua = [u for u in bulk["ua"] if lname and lname in _rot13(u.get("name") or "").lower()]
    dl = _dossier_browser_downloads(path, lname) if (opts.get("deep") or t.get("score")) else []
    ev = _dossier_events(c, t, opts, bulk) if not missing else \
        {"exec": [], "child": [], "accounts": [], "services": [], "behaviors": [], "files": [],
         "net": [], "reg": [], "channel": {}}
    siblings = _dossier_siblings(path, int(facts.get("created_epoch") or 0))

    # ---------- 时间线 ----------
    tl = []

    def ev_add(ep, text):
        if ep:
            tl.append((int(ep), text))

    if facts.get("created_epoch"):
        ev_add(facts["created_epoch"], "文件落地（NTFS 创建时间）%s" % facts.get("created_local"))
    for d in dl:
        ev_add(d.get("epoch"), "浏览器下载记录：%s ← %s" % (d.get("time"), (d.get("url") or "")[:120]))
    if zone.get("HostUrl"):
        tl.append((0, "下载来源（Zone.Identifier）：%s%s" % (
            zone.get("HostUrl"), "  引用页=%s" % zone["ReferrerUrl"] if zone.get("ReferrerUrl") else "")))
    first, last = 0, 0
    for p in pf:
        if p.get("created_epoch"):
            first = p["created_epoch"] if not first else min(first, p["created_epoch"])
            ev_add(p["created_epoch"], "首次执行（Prefetch 文件创建）%s" % p.get("created_local"))
        lep = p.get("last_epoch") or p.get("modified_epoch")
        if lep:
            last = max(last, lep)
    if pf:
        note = []
        for p in pf[:2]:
            note.append("%s 运行 %s 次，末次 %s%s" % (os.path.basename(p.get("file") or ""),
                                                     p.get("runs") or "?", p.get("last") or p.get("modified_local"),
                                                     "（Prefetch 压缩，运行次数不可解析）" if p.get("conf") == "压缩" else ""))
        if last:
            ev_add(last, "最近执行（Prefetch）%s" % time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(last)))
    for b, label in ((bam, "BAM"), (dam, "DAM")):
        if b.get("epoch"):
            ev_add(b["epoch"], "最近执行（%s 注册表）%s  %s" % (label, b.get("time"), b.get("path"))[:200])
            last = max(last, b["epoch"])
    if ua:
        u = max(ua, key=lambda x: x.get("last") or "")
        tl.append((0, "UserAssist：运行 %s 次，末次 %s" % (u.get("runs"), u.get("last"))))
        for e in (ev.get("exec") or []):
            if e[0]:
                first = e[0] if not first else min(first, e[0])
                last = max(last, e[0])
    if ev.get("exec"):
        ex = ev["exec"]
        ev_add(ex[0][0], "首次执行（安全日志 4688）%s" % ex[0][1])
        ev_add(ex[-1][0], "最近执行（安全日志 4688）%s（共 %d 条）" % (ex[-1][1], len(ex)))
        first = min([x for x in (first, ex[0][0]) if x] or [ex[0][0]])
        last = max(last, ex[-1][0])
    if t.get("start_epoch"):
        ev_add(t["start_epoch"], "当前进程启动时间 %s（PID %s）" % (t.get("start_local"), t.get("pid")))
    for r in persist["task"]:
        for src, label in ((r.get("date"), "任务定义时间"), (r.get("ctime_epoch"), "任务文件创建")):
            if src:
                ep = 0
                try:
                    ep = int(datetime.datetime.strptime(str(src)[:19], "%Y-%m-%dT%H:%M:%S").replace(
                        tzinfo=datetime.timezone.utc).timestamp())
                except Exception:
                    ep = int(src) if str(src).isdigit() else 0
                ev_add(ep, "持久化建立（%s）%s" % (label, r.get("rel")))
                break
    for s in persist["startup"]:
        ev_add(s.get("created_epoch"), "持久化建立（启动文件夹）%s" % s.get("name"))
    for s in persist["svc"]:
        tl.append((0, "持久化：服务 %s（ImagePath=%s）" % (s.get("Name"), s.get("PathName"))[:200]))
    for a in (beh.get("accounts") or []):
        ev_add(a["epoch"], "行为[%s] 账号变更：%s" % (a["eid"], a["blob"][:180]))
    for sv in (beh.get("services") or []):
        ev_add(sv["epoch"], "行为[%s] 服务/任务：%s" % (sv["eid"], sv["blob"][:180]))
    for ch in (ev.get("child") or [])[:20]:
        ev_add(ch[0], "它拉起的进程：%s" % ((ch[2] or {}).get("NewProcessName") or (ch[2] or {}).get("Image") or ch[1]))
    for f in (ev.get("files") or [])[:20]:
        ev_add(f[0], "它写下的文件（Sysmon 11）：%s" % ((f[2] or {}).get("TargetFilename") or f[1]))
    for r in (ev.get("reg") or [])[:20]:
        ev_add(r[0], "它改的注册表（Sysmon 13）：%s = %s" % ((r[2] or {}).get("TargetObject"),
                                                          (r[2] or {}).get("Details")))
    for n in (ev.get("net") or [])[:20]:
        ev_add(n[0], "它发起的外联（Sysmon 3）：%s:%s" % ((n[2] or {}).get("DestinationIp"),
                                                       (n[2] or {}).get("DestinationPort")))

    # 当前网络（按 PID）
    net_now = []
    for pid in [t.get("pid")] + [p.get("ProcessId") for p in (bulk.get("procs") or [])
                                 if _dossier_base(p.get("ExecutablePath") or "").lower() == lname]:
        for cn in bulk["net"].get(int(pid or 0), []) if str(pid or 0).isdigit() else []:
            net_now.append("%s:%s → %s:%s  %s" % (cn.get("LocalAddress"), cn.get("LocalPort"),
                                                  cn.get("RemoteAddress"), cn.get("RemotePort"), cn.get("State")))
    net_now = sorted(set(net_now))[:30]

    # ---------- 定性（候选选择阶段已按硬信号打分；这里只用文件事实做升降级）----------
    level = t.get("level_hint") or "提示"
    reason = list(t.get("flags") or [])
    if not missing:
        if zone.get("HostUrl") and tmp and level in ("中危", "高危"):
            level = "高危"
            reason.append("带下载来源标记的可执行文件落在临时目录")
        if (persist["reg"] or persist["task"] or persist["svc"]) and tmp and level != "严重":
            level = "高危"
            reason.append("持久化位置引用指向临时/落地目录")
        if sig and "valid" not in sig.lower() and level == "中危" and \
                (persist["reg"] or persist["task"] or persist["svc"] or persist["wmi"]):
            reason.append("签名状态为「%s」，但被持久化位置引用" % sig)
    else:
        if level == "提示":
            level = "中危"
        reason.append("文件本体已不存在（自删除或路径失效）")
    if not reason:
        reason = ["未见明显恶意特征（保留画像供时间线比对）"]

    # ---------- 证据 ----------
    evd = []
    evd.append("[源文件] %s" % (path or "(路径不可读)"))
    if facts and not missing:
        evd.append("[文件属性] 大小=%s 属性=%s 创建(落地)=%s 修改=%s 访问=%s" % (
            _dsn_size(facts.get("size")), facts.get("attrs"), facts.get("created_local"),
            facts.get("modified_local"), facts.get("accessed_local")))
        evd.append("[数字签名] %s%s" % (sig or "无签名", ("  签名者=%s" % signer[:200]) if signer else ""))
        evd.append("[数据流] %s" % (facts.get("streams") or ""))
        for s in _dossier_hashes(path):
            evd.append("[哈希] %s" % s)
    elif missing:
        evd.append("[文件属性] 文件已不存在（进程仍在运行/记录残留）：可能是自删除或权限不足")
    evd.append("[候选理由/评分] %s（来源：%s，评分 %s）" % (
        "；".join(t.get("flags") or []) or "未见硬信号（人工指定目标）", t.get("source"), t.get("score")))
    if t.get("cmdline"):
        evd.append("[命令行] %s" % t["cmdline"])
    if zone:
        evd.append("[下载来源 Zone.Identifier] %s" % json.dumps(zone, ensure_ascii=False))
    for d in dl[:6]:
        evd.append("[浏览器下载] %s ← %s（%s，%s）" % (d.get("target"), d.get("url"), d.get("time"), d.get("mime")))
    if not dl and not zone and not missing:
        evd.append("[下载来源] 未找到 Zone.Identifier / 浏览器下载记录（可能是本地投放、打包内置或已清理）")
    exec_note = list(note) if pf else []
    if not pf:
        pt = bulk.get("pf_total")
        if pt == 0:
            exec_note.append("本机未启用 Prefetch（无 .pf 文件）")
        elif pt is None or pt < 0:
            exec_note.append("Prefetch 目录不可读（需管理员）")
        else:
            exec_note.append("Prefetch 中无该程序记录")
    if t.get("start_epoch"):
        if not last or t["start_epoch"] > last:
            last = t["start_epoch"]
        exec_note.append("运行中进程 PID %s 启动于 %s" % (t.get("pid"), t.get("start_local")))
    evd.append("[执行时间] 首次=%s 最近=%s（%s）" % (
        time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(first)) if first else "未确认",
        time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(last)) if last else "未确认",
        "；".join(exec_note) if exec_note else "无 Prefetch/BAM/UserAssist/4688 记录"))
    if bam:
        evd.append("[BAM 最后执行] %s  %s" % (bam.get("time"), bam.get("path")))
    if dam:
        evd.append("[DAM 最后执行] %s  %s" % (dam.get("time"), dam.get("path")))
    for u in ua[:6]:
        evd.append("[UserAssist] %s 运行 %s 次 末次 %s" % (_rot13(u.get("name") or ""), u.get("runs"), u.get("last")))
    for r in persist["reg"]:
        evd.append("[持久化-注册表:%s] %s => %s" % (r.get("kind"), r.get("key"), r.get("line")))
    for r in persist["task"]:
        evd.append("[持久化-计划任务] %s  定义时间=%s 作者=%s  命令=%s %s" % (
            r.get("rel"), r.get("date"), r.get("author"), r.get("command"), r.get("args")))
    for s in persist["svc"]:
        evd.append("[持久化-服务] %s(%s) 启动=%s 账号=%s ImagePath=%s" % (
            s.get("Name"), s.get("DisplayName"), s.get("StartMode"), s.get("StartName"), s.get("PathName")))
    for s in persist["startup"]:
        evd.append("[持久化-启动夹] %s -> %s" % (s.get("name"), s.get("target")))
    for w in persist["wmi"]:
        evd.append("[持久化-WMI 订阅] %s" % json.dumps(w, ensure_ascii=False)[:300])
    for b in persist["bits"]:
        evd.append("[持久化/下载-BITS] %s" % b)
    for ch in (ev.get("child") or [])[:15]:
        d = ch[2] or {}
        evd.append("[行为-拉起进程] %s  %s %s（父=%s）" % (ch[1], d.get("NewProcessName") or d.get("Image"),
                                                    d.get("CommandLine") or "", d.get("ParentImage") or ""))
    for f in (ev.get("files") or [])[:15]:
        evd.append("[行为-写文件] %s  %s（%s 字节）" % (f[1], (f[2] or {}).get("TargetFilename"),
                                                    (f[2] or {}).get("FileSize")))
    for r in (ev.get("reg") or [])[:15]:
        evd.append("[行为-改注册表] %s  %s = %s" % (r[1], (r[2] or {}).get("TargetObject"),
                                                  (r[2] or {}).get("Details")))
    for n in (ev.get("net") or [])[:15]:
        evd.append("[行为-外联] %s  %s:%s（%s）" % (n[1], (n[2] or {}).get("DestinationIp"),
                                                 (n[2] or {}).get("DestinationPort"), (n[2] or {}).get("DestinationHostname") or ""))
    for s in sorted(set(_dossier_siblings(path, int(facts.get("created_epoch") or 0))))[:12]:
        evd.append("[同批落地文件] %s" % s)
    if net_now:
        evd.append("[当前连接] " + "；".join(net_now))
    for line in sorted(tl):
        evd.append("[时间线] %s  %s" % (
            time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(line[0])) if line[0] else "时间未知", line[1]))
    if not (ev.get("channel") or {}).get("sysmon"):
        evd.append("[备注] 未检测到 Sysmon：子进程/文件写入/注册表写入的证据仅来自 4688 与文件时间")
    if missing:
        evd.append("[备注] 文件本体不可读，无法给哈希与签名——建议内存取证（导出进程镜像/句柄）")

    title = "%s：%s%s" % ("可疑程序画像" if level in ("严重", "高危") else "程序画像",
                        name, ("（%s）" % t.get("source") if t.get("source") else ""))
    detail = ("程序：%s\n落地(创建)时间：%s\n下载来源：%s\n执行时间：%s ~ %s\n"
              "持久化：注册表 %d 项 / 计划任务 %d 项 / 服务 %d 项 / 启动夹 %d 项 / WMI %d 项\n"
              "已确认行为：拉起进程 %d 起、写文件 %d 个、改注册表 %d 次、外联 %d 次、账号变更 %d 起、服务/任务 %d 起\n"
              "判定依据：%s" % (
                  path, facts.get("created_local") or "未确认",
                  (zone.get("HostUrl") or (dl[0].get("url") if dl else "未发现下载记录")),
                  time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(first)) if first else "未确认",
                  time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(last)) if last else "未确认",
                  len(persist["reg"]), len(persist["task"]), len(persist["svc"]), len(persist["startup"]),
                  len(persist["wmi"]), len(ev.get("child") or []), len(ev.get("files") or []),
                  len(ev.get("reg") or []), len(ev.get("net") or []), len(beh.get("accounts") or []),
                  len(beh.get("services") or []), "；".join(reason)))
    advice = ("样本优先：先隔离该文件（复制留证：样本+内存镜像），不要直接删除；"
              "按上面的时间线回溯同批落地文件与同时间段的账号/服务/任务改动；"
              "核对持久化位置逐条清除，改掉该程序接触过的账号口令；"
              "若确认是下载投放，封禁上面的 HostUrl/外联 IP 并排查同一来源的其他主机。")
    if level == "提示":
        advice = "当前未见明显恶意特征；如仍有怀疑，可按时间线比对它落地时的同批文件与网络连接。"
    exec_hint = ""
    if first or last or t.get("start_epoch") or bam or dam or ua:
        exec_hint = "首次=%s 最近=%s%s" % (
            time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(first)) if first else "未确认",
            time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(last)) if last else "未确认",
            "（BAM/UserAssist/进程启动时间有记录）" if (bam or dam or ua or t.get("start_epoch")) else "")
    c.add_verified(level, cat, title, detail, evidence=evd, advice=advice,
                   sources=_r18_dossier_sources(facts, sig, persist, ev, zone, dl, missing,
                                                reason, exec_hint))
    return {"level": level, "today": int(facts.get("created_epoch") or 0), "first": first, "last": last,
            "persist": persist, "net": net_now, "facts": facts, "path": path, "name": name}


def _dossier_hashes(path):
    """给样本算哈希（大文件跳过，避免拖垮排查）。"""
    out = []
    if not path or not os.path.isfile(path):
        return out
    try:
        if os.path.getsize(path) > 200 * 1024 * 1024:
            return ["文件过大(>200MB)已跳过哈希"]
    except Exception:
        return out
    try:
        out.append("MD5=%s" % md5_file(path))
    except Exception as _e_r19:
        _degrade("_dossier_hashes", _e_r19)
    try:
        out.append("SHA256=%s" % sha256_file(path))
    except Exception as _e_r19:
        _degrade("_dossier_hashes", _e_r19)
    return out


def win_malware_dossier(c, opts):
    """一键恶意程序取证画像：源文件 / 落地时间 / 下载来源 / 执行时间 / 持久化 / 它做了什么。
    malware 模式 = 深挖档；win 模式以精简档附带调用（只出画像，不做全机行为关联）。"""
    cat = "恶意程序画像"
    if not IS_WIN:
        c.warn("恶意程序取证画像只支持 Windows（当前系统：%s）" % platform.system())
        return
    opts = opts or {}
    maxn = int(opts.get("max_targets") or (_R21_DEEP_MAX_TARGETS if opts.get("deep") else 3))
    c.r21_dossier = {"max": maxn, "n": None}   # R21/P1-4：档位声明用（画像目标数 N / 实际展开数）
    c.add("提示", cat, "开始采集可疑程序画像数据",
          "数据源：进程快照 / 启动项 / 计划任务 / 服务 / WMI 订阅 / Prefetch / BAM / DAM / UserAssist / "
          "Zone.Identifier / 浏览器下载库 / 安全日志与 Sysmon（若安装）。全部只读，不做任何删除或禁用。")

    print("[*] 画像：采集全机数据（进程/启动项/计划任务/服务/WMI/网络/执行历史）…")
    bulk = _dossier_globals(c, opts)
    try:
        bulk["pf_total"] = len(os.listdir(os.path.join(
            os.environ.get("SystemRoot") or "C:\\Windows", "Prefetch")))
    except Exception:
        bulk["pf_total"] = -1
    pidx = _dossier_persist_index(bulk)
    cands, ages, drop_n = _dossier_candidate_paths(c, opts, bulk, pidx, c.days)
    tgt_path, tgt_note = _dossier_resolve_explicit(c, opts, bulk, pidx)
    if tgt_path:
        cands = [tgt_path]      # 指定了目标：只对它做取证，秒级出结果
    print("[*] 画像：候选来源 %d 个运行中进程、%d 个持久化引用、近期落地可执行 %d 个；"
          "对 %d 个候选文件做签名/时间/下载标记取证…%s" % (
              len(bulk.get("procs") or []), sum(len(v.get("paths") or []) for v in pidx.values()),
              drop_n, len(cands), ("（定向：%s）" % tgt_path) if tgt_path else ""))
    _dossier_filefacts(c, cands, bulk, opts)
    targets, low, more = _dossier_select(c, opts, bulk, pidx, cands, ages, maxn)
    if not targets:
        c.r21_dossier["n"] = 0                 # R21/P1-4：未发现目标也要写进档位声明（不静默）
        c.add("提示", cat, "未发现可疑程序候选",
              "进程、启动项、计划任务、服务、WMI 订阅、近期落地文件里都没有命中硬信号的项目"
              "（临时目录、伪装系统进程名、强命令行、下载标记、持久化指向异常位置）。\n"
              "如已知可疑程序：python er_check.py malware --target <文件路径|进程名|PID> 直接画像。",
              evidence=["已检查：运行中进程 %d 个、持久化位置引用 %d 个、候选文件 %d 个、"
                        "低分未展开候选 %d 个" % (len(bulk.get("procs") or []),
                                            sum(len(v.get("paths") or []) for v in pidx.values()),
                                            len(cands), low)])
        return
    c.r21_dossier["n"] = len(targets)          # R21/P1-4：实际展开数（档位声明用）
    names = sorted(set(_dossier_base(t["path"]) for t in targets))
    print("[*] 画像：采集执行历史（Prefetch / BAM / DAM）…")
    _dossier_pf(c, names, bulk, opts)
    _dossier_bam(c, names, bulk, opts)
    if opts.get("deep"):
        print("[*] 画像：关联安全日志行为（建账号 / 装服务 / 建任务 / Sysmon）…")
        beh = _dossier_behaviors(c, opts)
    else:
        beh = _beh_blank()
        c.warn("精简档未做全机行为关联（建账号/装服务/建任务），需要完整画像请用：python er_check.py malware")

    summary = []
    for t in targets:
        try:
            summary.append(_dossier_one(c, t, bulk, opts, beh))
        except Exception as e:
            c.warn("程序画像失败：%s（%s）" % (t.get("path"), e))
    if more:
        c.add("提示", cat, "另有 %d 个候选未展开" % more,
              "已展开评分最高的 %d 个（同分按路径排序）；提高上限：--max-targets <N>" % len(targets))

    # ---------- 全机行为汇总（账号 / 服务 / 任务）----------
    accts = beh.get("accounts") or []
    svcs = beh.get("services") or []
    tpaths = [_dossier_norm(s["path"]) for s in summary if s.get("path")]
    hit_acct = [a for a in accts if any(p and p in a["blob"].lower() for p in tpaths)]
    hit_svc = [s for s in svcs if any(p and p in s["blob"].lower() for p in tpaths)]
    if hit_acct:
        # R18/P2：两类独立证据——①Security 通道的账号/组变更事件原文含画像程序路径；
        # ②该程序自身的画像定性（文件事实/持久化引用/行为，见对应画像条目）。
        linked = sorted(set(s.get("path") for s in summary if s.get("path") and
                            any(_dossier_norm(s.get("path")) in a["blob"].lower()
                                for a in hit_acct)))
        c.add_verified("严重", cat, "画像目标相关：窗口内发生账号创建/提权",
              "以下账号变更事件的原始数据里出现了本次画像的程序路径，时间也吻合——这是“它做了什么”的直接证据。",
              evidence=[("%s [%s] %s" % (a["time"], a["eid"], a["blob"])) for a in hit_acct[:20]],
              advice="立即核对账号清单（net user / net localgroup administrators），禁用并删除未知账号，"
                     "改掉相关口令，排查该账号登录记录（4624 类型 3/10 与远程连接）。",
              sources=[("账号/组变更事件原文（Security/System 通道）",
                        "命中 %d 条：%s" % (len(hit_acct), "、".join(sorted(set(a["eid"] for a in hit_acct))))),
                       ("画像程序定性（文件事实/持久化引用/行为事件）",
                        "关联画像程序 %d 个：%s" % (len(linked), "；".join(linked[:3])))])
    elif accts:
        c.add("中危", cat, "窗口内存在账号/组变更事件（需人工确认）",
              "近 %d 天安全日志里有账号创建/启用/加组事件，但没有直接关联到本次画像的程序。" % c.days,
              evidence=[("%s [%s] %s" % (a["time"], a["eid"], a["blob"])) for a in accts[:20]],
              advice="逐个核对账号来源与时间；时间点若与画像程序吻合，按账号失陷处置。")
    elif opts.get("deep"):
        c.add("提示", cat, "窗口内未发现创建账号/加组事件（近 %d 天）" % c.days)
    if hit_svc:
        c.add("高危", cat, "画像目标相关：窗口内安装服务/创建任务",
              "服务安装或计划任务创建事件的原始数据里出现了画像程序的路径。",
              evidence=[("%s [%s] %s" % (s["time"], s["eid"], s["blob"])) for s in hit_svc[:20]],
              advice="删除对应服务/任务，核对 ImagePath 与命令行，确认是否为持久化。")
    elif svcs:
        c.add("中危", cat, "窗口内存在服务安装/任务创建事件（需人工确认）",
              "近 %d 天安装了服务或创建了任务，未与画像程序直接关联。" % c.days,
              evidence=[("%s [%s] %s" % (s["time"], s["eid"], s["blob"])) for s in svcs[:20]])
    elif opts.get("deep"):
        c.add("提示", cat, "窗口内未发现服务安装/任务创建事件（近 %d 天）" % c.days)

    # ---------- 原始数据（报告附录）----------
    try:
        c.raw_add("恶意程序画像：候选评分明细", "画像目标选择",
                  "\n".join("%3d  %-22s %s\n     理由：%s" % (t.get("score") or 0, t.get("source") or "",
                                                          t.get("path") or "", "；".join(t.get("flags") or []))
                            for t in targets) or "(无)")
        c.raw_add("恶意程序画像：运行中进程与端口", "进程快照 / Get-NetTCPConnection",
                  "\n".join("%-6s %-22s %-48s %s" % (
                      p.get("ProcessId"), p.get("Name"), (p.get("ExecutablePath") or "")[:48],
                      "; ".join("%s:%s->%s:%s" % (c0.get("LocalAddress"), c0.get("LocalPort"),
                                                  c0.get("RemoteAddress"), c0.get("RemotePort"))
                                for c0 in (bulk["net"].get(int(p.get("ProcessId") or 0)) or [])[:3]))
                            for p in (bulk.get("procs") or [])[:200]) or "(无)")
        c.raw_add("恶意程序画像：启动项命中", "注册表 Run/RunOnce/Winlogon/IFEO 等",
                  "\n".join("[%s] %s => %s" % (r.get("kind"), r.get("key"), r.get("line"))
                            for r in (bulk.get("runkeys") or [])[:200]) or "(无)")
        c.raw_add("恶意程序画像：计划任务", "任务 XML（建立时间/作者/命令行）",
                  "\n".join("%s  定义时间=%s 作者=%s 命令=%s %s" % (
                      t.get("rel"), t.get("date"), t.get("author"), t.get("command"), t.get("args"))
                            for t in (bulk.get("tasks") or [])[:200]) or "(无)")
        c.raw_add("恶意程序画像：系统服务清单", "Win32_Service",
                  "\n".join("%-30s %-10s %-12s %s" % (s.get("Name"), s.get("State"), s.get("StartMode"),
                                                      s.get("PathName"))
                            for s in (bulk.get("services") or [])[:250]) or "(无)")
    except Exception as _e_r19:
        _degrade("win_malware_dossier", _e_r19)


