APP_JAR_NAME_RE = re.compile(r"(?i)^(webshell|shell|cmd|evil|backdoor|memshell|inject|bypass|"
                             r"exploit|godzilla|behinder|antsword|冰蝎|哥斯拉)(\.jar$|[-_.])")
