@_case("B._priv_acl_verdict.正例1-Users可写/仅管理员与只读不判/DENY优先/(IO)与(AD)不算/空输出unknown")
def _st_priv_acl_cases(ctx):
    w, _ = _priv_acl_verdict("D:\\Users\\App BUILTIN\\Users:(I)(F)\n"
                             "            NT AUTHORITY\\SYSTEM:(I)(F)\n", "D:\\Users\\App")
    n, _ = _priv_acl_verdict("D:\\Users\\App BUILTIN\\Administrators:(F)\n"
                             "            BUILTIN\\Users:(RX)\n", "D:\\Users\\App")
    d, _ = _priv_acl_verdict("D:\\Users\\App BUILTIN\\Users:(DENY)(W)\n"
                             "            BUILTIN\\Users:(F)\n", "D:\\Users\\App")
    io_case, _ = _priv_acl_verdict("D:\\Users\\App NT AUTHORITY\\Authenticated Users:(OI)(CI)(IO)(M)\n",
                                   "D:\\Users\\App")
    ad_case, _ = _priv_acl_verdict("D:\\Users\\App NT AUTHORITY\\Authenticated Users:(AD)\n",
                                   "D:\\Users\\App")
    u, _ = _priv_acl_verdict("", "D:\\Users\\App")
    got = (w, n, d, io_case, ad_case, u)
    return got == ("writable", "not", "not", "not", "not", "unknown"), got


