_section("== E 组 | R11 规则/白名单/哈希库/PE/字符串（纯函数与容错路径）==")


def _st_pe_fixture():
    """最小 PE 夹具（PE32+，1 节 .text 熵≈8，导入 KERNEL32.dll）。纯内存构造。"""
    data = bytearray(0x800)
    pe = 0x80
    data[0:2] = b"MZ"
    data[0x3C:0x40] = pe.to_bytes(4, "little")
    data[pe:pe + 4] = b"PE\0\0"
    data[pe + 4:pe + 6] = (0x8664).to_bytes(2, "little")
    data[pe + 6:pe + 8] = (1).to_bytes(2, "little")
    data[pe + 8:pe + 12] = (1700000000).to_bytes(4, "little")
    data[pe + 20:pe + 22] = (0xF0).to_bytes(2, "little")
    opt = pe + 24
    data[opt:opt + 2] = (0x20B).to_bytes(2, "little")
    data[opt + 108:opt + 112] = (16).to_bytes(4, "little")
    dd = opt + 112
    data[dd + 8:dd + 12] = (0x1000).to_bytes(4, "little")
    data[dd + 12:dd + 16] = (0x28).to_bytes(4, "little")
    s = pe + 24 + 0xF0
    data[s:s + 8] = b".text\x00\x00\x00"
    data[s + 8:s + 12] = (0x100).to_bytes(4, "little")
    data[s + 12:s + 16] = (0x1000).to_bytes(4, "little")
    data[s + 16:s + 20] = (0x400).to_bytes(4, "little")
    data[s + 20:s + 24] = (0x400).to_bytes(4, "little")
    body = bytearray(bytes(range(256)) * 4)
    body[0:20] = ((0).to_bytes(4, "little") + (0).to_bytes(4, "little")
                  + (0).to_bytes(4, "little") + (0x1040).to_bytes(4, "little")
                  + (0).to_bytes(4, "little"))
    body[20:40] = b"\x00" * 20
    body[0x40:0x4D] = b"KERNEL32.dll\x00"
    data[0x400:0x800] = body
    return bytes(data)


