_section("== F 组 | R13 规则引擎（YARA-like / Sigma 最小子集：解析/匹配/坏规则隔离/报告声明）==")


@_case("F._r13_yara_parse.正例1-文本/正则/nocase+wide/meta.level(高→高危) 解析")
def _st_r13_yara_parse_case(ctx):
    text = ('rule Demo1 {\n'
            '    meta:\n'
            '        level = "高"\n'
            '        desc = "自检样例"\n'
            '    strings:\n'
            '        $a = "cmd /c whoami" nocase wide\n'
            '        $b = /powershell\\s+-enc/ nocase\n'
            '    condition:\n'
            '        all of them and filesize < 1KB\n'
            '}\n')
    rules, problems = _r13_yara_parse_text(text, "自检")
    r = rules[0] if rules else {}
    strs = r.get("strings") or []
    ok = (len(rules) == 1 and not problems and r.get("level") == "高危"
          and len(strs) == 2 and bool(strs[0]["mods"]["nocase"]) and bool(strs[0]["mods"]["wide"]))
    return ok, {"rules": len(rules), "problems": problems, "level": r.get("level")}


@_case("F._r13_yara_eval.正例1-文本/宽字符/正则+括号与 filesize；负例-断串与超限")
def _st_r13_yara_eval_case(ctx):
    text = ('rule Demo2 {\n'
            '    strings:\n'
            '        $a = "EVIL-MARKER"\n'
            '        $b = "WIDE-ONLY" wide\n'
            '        $c = /tok.n/\n'
            '    condition:\n'
            '        ($a or $b) and $c and filesize < 1MB\n'
            '}\n')
    rules, _pr = _r13_yara_parse_text(text, "自检")
    data = b"xx EVIL-MARKER yy " + "WIDE-ONLY".encode("utf-16-le") + b" zz token zz"
    got = _r13_yara_eval(rules[0], data, len(data))
    ids = (got or {}).get("ids")
    data2 = data.replace(b" token ", b" nope ")
    got2 = _r13_yara_eval(rules[0], data2, len(data2))
    got3 = _r13_yara_eval(rules[0], data, 2 * 1024 * 1024)
    ok = (ids == ["a", "b", "c"]) and (got2 is None) and (got3 is None)
    return ok, {"ids": ids, "断串不命中": got2 is None, "超限不命中": got3 is None}


@_case("F._r13_yara_parse.负例1-坏正则/坏 condition 逐条隔离（好规则保留）")
def _st_r13_yara_bad_isolate_case(ctx):
    text = ('rule Good1 {\n    strings:\n        $a = "OK-MARKER"\n    condition:\n        $a\n}\n'
            'rule BadRegex {\n    strings:\n        $b = /([unclosed/\n    condition:\n        $b\n}\n'
            'rule BadCond {\n    strings:\n        $c = "x"\n    condition:\n        $c and unknown_fn(1)\n}\n')
    rules, problems = _r13_yara_parse_text(text, "自检")
    names = [r.get("name") for r in rules]
    ok = (names == ["Good1"] and len(problems) == 2)
    return ok, {"rules": names, "problems": problems}


@_case("F._r13_yara_scan.正例1-命中产出「文件内容特征」结论（路径+规则名+命中串）")
def _st_r13_yara_scan_case(ctx):
    d = ctx.tmpdir()
    p = os.path.join(d, "sample_r13.bin")
    with open(p, "wb") as fh:
        fh.write(b"AAAA R13-SCAN-MARKER BBBB")
    c = Collector()
    try:
        _R13.reset()
        rules, _pr = _r13_yara_parse_text(
            'rule ScanHit {\n    meta:\n        desc = "自检扫描"\n    strings:\n'
            '        $a = "R13-SCAN-MARKER"\n    condition:\n        $a\n}\n', "自检")
        _R13["yara"] = rules
        n = _r13_yara_scan(c, None, files=[(p, os.path.getsize(p), 0)])
        rec = c.findings[-1].to_dict() if c.findings else {}
        ok = (n == 1 and rec.get("category") == "文件内容特征" and rec.get("level") == "高危"
              and "R13-SCAN-MARKER" in rec.get("detail", "") and p in rec.get("detail", "")
              and len(rec.get("evidence") or []) >= 2)
        return ok, {"n": n, "cat": rec.get("category"), "level": rec.get("level")}
    finally:
        _R13.reset()


