@_case("F.build_parser.正例1-R13 三个新参数各只定义一次且覆盖率声明进入 --help")
def _st_r13_parser_case(ctx):
    p = build_parser()
    acts = p._actions
    names = ["--yara", "--yara-root", "--sigma"]
    got = dict((n, sum(1 for a in acts for s in a.option_strings if s == n)) for n in names)
    helptext = p.format_help()
    ok = (all(v == 1 for v in got.values())
          and all(n in helptext for n in names)
          and "仅支持简单子集" in helptext and "不含聚合(count/near)" in helptext)
    return ok, {"定义次数": got, "覆盖声明": "仅支持简单子集" in helptext}


