_section("== G 组 | R14 内置规则库（银狐族）+ UI 参数面板（payload 键/CLI 对齐/等效命令行）==")


@_case("G._r14_builtin_yara.正例1-内置 YARA-like 库解析全绿（内容/文件名/伴生三类齐备、来源标注完整）")
def _st_r14_builtin_yara_case(ctx):
    rules, problems = _r13_yara_parse_text(_R14_BUILTIN_YARA_TEXT, "内置自检", origin="builtin")
    bad = [r.get("name") for r in rules
           if r.get("origin") != "builtin" or not r.get("family") or not r.get("variant")
           or not r.get("ref") or r.get("level") not in LEVEL_ORDER]
    kinds = sorted(set(r.get("kind") for r in rules))
    ok = (len(rules) >= 6 and not problems and not bad
          and "pair" in kinds and "name" in kinds and "content" in kinds)
    return ok, {"rules": len(rules), "problems": problems[:4], "bad": bad[:6], "kinds": kinds}


@_case("G._r14_builtin_sigma.正例1-内置 Sigma 多文档库条数≥14 且 origin/family/source 齐备（windows+linux 双平台）")
def _st_r14_builtin_sigma_case(ctx):
    rules, problems = _r14_parse_builtin_sigma(_R14_BUILTIN_SIGMA_TEXT)
    bad = [r.get("title") for r in rules
           if r.get("origin") != "builtin" or not r.get("family") or not r.get("ref")
           or r.get("level") not in LEVEL_ORDER]
    plat = sorted(set(r.get("platform") for r in rules))
    ok = (len(rules) >= 14 and not problems and not bad
          and set(plat) == {"windows", "linux"})
    return ok, {"rules": len(rules), "problems": problems[:4], "bad": bad[:4], "platform": plat}


@_case("G._r13_load_builtin.正例1-缺省即开（总数≥10：YARA-like≥6/Sigma≥4）+ 幂等不叠加 + 零告警")
def _st_r14_load_builtin_default_on_case(ctx):
    c = Collector()
    try:
        _R13.reset()
        _r11_load_cfg({"yara": None, "yara_root": None, "sigma": None}, c, phase="r13")
        _r13_load_builtin({}, c)                 # 缺 builtin_rules 键 = 开（A5）
        n1 = (len(_R13["yara"]), len(_R13["sigma"]))
        _r13_load_builtin({}, c)                 # 幂等：重复调用不叠加
        n2 = (len(_R13["yara"]), len(_R13["sigma"]))
        nb = int(_R13.get("builtin_yara") or 0)
        ns = int(_R13.get("builtin_sigma") or 0)
        ok = (bool(_R13.get("builtin")) and nb >= 6 and ns >= 4 and (nb + ns) >= 10
              and n1 == n2 and not c.warnings)
        return ok, {"builtin": _R13.get("builtin"), "n": n1, "after2": n2,
                    "builtin_yara": _R13.get("builtin_yara"),
                    "builtin_sigma": _R13.get("builtin_sigma"), "warnings": c.warnings[:3]}
    finally:
        _R13.reset()


@_case("G._r13_load_builtin.负例1---no-builtin-rules 零加载零告警且覆盖段保持 R13 旧格式（E2 闸门）")
def _st_r14_load_builtin_off_case(ctx):
    c = Collector()
    try:
        _R13.reset()
        _r13_load_builtin({"no_builtin_rules": True}, c)
        ok1 = (not c.warnings and not _R13.get("builtin")
               and _R13["yara"] == [] and _R13["sigma"] == [])
        args = build_parser().parse_args(["win", "--no-builtin-rules"])
        c2 = Collector()
        _R13.reset()
        _r13_load_builtin(args, c2)
        ok2 = (not c2.warnings and not _R13.get("builtin") and _R13["yara"] == []
               and getattr(args, "no_builtin_rules", False) is True)
        legacy = _r13_coverage_lines()
        ok3 = (legacy == ["规则能力与覆盖范围（R13 规则引擎）:",
                          "  * " + _R13_COVERAGE,
                          "  * 本次加载: YARA-like 0 条 / Sigma 0 条；三个参数默认关闭，不给参数即零额外行为。"])
        return (ok1 and ok2 and ok3), {"ok": [ok1, ok2, ok3], "warnings": c.warnings[:2]}
    finally:
        _R13.reset()


@_case("G._r13_coverage_lines.正例1-启用后 A3/E5 新格式（内置/自定义/命中分开统计 + 来源 + 合并标注）")
def _st_r14_coverage_lines_case(ctx):
    c = Collector()
    try:
        _R13.reset()
        _r13_load_builtin({}, c)
        ny = int(_R13.get("builtin_yara") or 0)
        ns = int(_R13.get("builtin_sigma") or 0)
        line1 = "内置规则 %d 条（YARA-like %d / Sigma %d）· 自定义规则 0 条 · 本次命中 0 条" % (ny + ns, ny, ns)
        s1 = "\n".join(_r13_coverage_lines())
        _R13["hits"] = 3
        _R13["hits_merged"] = 1
        s2 = "\n".join(_r13_coverage_lines())
        ok = (line1 in s1 and "内置规则来源" in s1 and "本次命中 3 条" in s2 and "已合并" in s2
              and _R14_BUILTIN_VERSION in s1)
        return ok, {"line1": line1 in s1, "src": "内置规则来源" in s1,
                    "hit3": "本次命中 3 条" in s2, "merged": "已合并" in s2}
    finally:
        _R13.reset()


@_case("G._r14_fixture.正例1-ValleyRAT 配置串 + NVSmart 侧载对 + 伪装 UpdateOrchestrator 任务 XML 三夹具命中")
def _st_r14_fixture_hit_case(ctx):
    d = ctx.tmpdir()
    f1 = os.path.join(d, "valley_cfg.txt")
    with open(f1, "w", encoding="utf-8") as fh:
        fh.write("cfg |p1:101.33.117.200|o1:6666|t1:1|p2:101.33.117.200|o2:8888|t2:1|"
                 "p3:127.0.0.1|o3:80|t3:1|dd:1|cl:1|fz:默认|bb:1.0|bz:2024.3.20|jp:0|bh:0|")
    pe = os.path.join(d, "nvsmartmaxapp64.exe")
    dl = os.path.join(d, "NvSmartMax64.dll")
    for one in (pe, dl):
        with open(one, "wb") as fh:
            fh.write(b"MZ-selftest-placeholder")
    tx = os.path.join(d, "XyUpdateTask.xml")
    with open(tx, "w", encoding="utf-8") as fh:
        fh.write("<Task><RegistrationInfo><URI>\\Microsoft\\Windows\\UpdateOrchestrator\\XyUpdateTask"
                 "</URI></RegistrationInfo><Actions><Exec><Command>powershell.exe -w hidden -enc SQBFAFgA"
                 "</Command></Exec></Actions></Task>")
    c = Collector()
    try:
        _R13.reset()
        _r13_load_builtin({}, c)
        files = [(one, os.path.getsize(one), 0) for one in (f1, pe, dl, tx)]
        n = _r13_yara_scan(c, None, files=files)
        titles = [x.title for x in c.findings]
        sf = [x for x in c.findings if "family=silverfox" in (x.detail or "")]
        ok = (n >= 3 and any("SF_ValleyRAT_ConfigMarkers" in t for t in titles)
              and any("SF_NVSmart_SideloadPair" in t for t in titles)
              and any("SF_Fake_UpdateOrchestrator_TaskXML" in t for t in titles)
              and len(sf) >= 3 and not c.warnings)
        return ok, {"n": n, "titles": titles[:6], "sf": len(sf), "warnings": c.warnings[:2]}
    finally:
        _R13.reset()


