@_case("G._r14_dedup.正例1-同目标重复命中不刷成两倍：同级合并标注 / 更高级保留并标注")
def _st_r14_dedup_case(ctx):
    d = ctx.tmpdir()
    f1 = os.path.join(d, "dup_cfg_a.txt")
    f2 = os.path.join(d, "dup_cfg_b.txt")
    for one in (f1, f2):
        with open(one, "w", encoding="utf-8") as fh:
            fh.write("|p1:10.0.0.1|o1:1|t1:1|bb:1.0|bh:0|")
    c = Collector()
    try:
        _R13.reset()
        _r13_load_builtin({}, c)
        c.add("高危", "异常文件", "既有检查（同级占位）", detail="路径: %s" % f1, evidence=[f1])
        c.add("中危", "异常文件", "既有检查（低级别占位）", detail="路径: %s" % f2, evidence=[f2])
        n1 = _r13_yara_scan(c, None, files=[(f1, os.path.getsize(f1), 0)])
        n2 = _r13_yara_scan(c, None, files=[(f2, os.path.getsize(f2), 0)])
        merged_note = "[内置规则去重]" in (c.findings[0].detail or "")
        new_hits = [x for x in c.findings if x.title.startswith("文件命中内容特征规则")]
        keep_higher = (len(new_hits) == 1 and "与既有检查重复" in (new_hits[0].detail or "")
                       and new_hits[0].level == "高危")
        ok = (n1 == 1 and n2 == 1 and merged_note and keep_higher
              and int(_R13.get("hits_merged") or 0) == 1 and len(c.findings) == 3)
        return ok, {"n1": n1, "n2": n2, "merged_note": merged_note, "keep_higher": keep_higher,
                    "findings": len(c.findings), "merged": _R13.get("hits_merged")}
    finally:
        _R13.reset()


@_case("G.UI.正例1-新增控件 id、CLI 参数名、payload 引用三处齐全（页面自证）")
def _st_r14_ui_wiring_case(ctx):
    head, js = WEB_UI_HEAD, WEB_UI_JS
    pairs = [("p-builtin", "--no-builtin-rules"), ("p-yara", "--yara"), ("p-yara-root", "--yara-root"),
             ("p-sigma", "--sigma"), ("p-rules", "--rules"), ("p-allow", "--allow"),
             ("p-hash-db", "--hash-db"), ("p-k8s", "--k8s-live"), ("p-pkg", "--pkg-verify"),
             ("p-ioc", "--ioc-file")]
    miss_html = [i for i, f in pairs if ('id="%s"' % i) not in head]
    miss_cli = [f for i, f in pairs if f not in head]
    miss_js = [i for i, f in pairs if i not in js]
    ok = not miss_html and not miss_cli and not miss_js
    return ok, {"miss_html": miss_html, "miss_cli": miss_cli, "miss_js": miss_js}


@_case("G.UI.正例2-默认值（内置开/k8s/pkg 关）+ payload 新键 + 等效命令行预览 + chips")
def _st_r14_ui_defaults_case(ctx):
    head, js = WEB_UI_HEAD, WEB_UI_JS
    ok1 = ('id="p-builtin" checked' in head and 'id="p-k8s" checked' not in head
           and 'id="p-pkg" checked' not in head)
    seg = js[js.find("function payload()"):js.find("function start")]
    keys = ["builtin_rules", "yara_root", "yara", "sigma", "rules", "allow", "hash_db", "k8s_live"]
    ok2 = bool(seg) and all(k in seg for k in keys)
    ok3 = ('cmd-preview' in head) and ('renderCmdPreview' in js) and ('--no-builtin-rules' in js)
    ok4 = ('id="p-yara-root-chips"' in head) and ('yaraRootChips' in js)
    ok = ok1 and ok2 and ok3 and ok4
    return ok, {"defaults": ok1, "payload_keys": ok2, "preview": ok3, "chips": ok4}


@_case("G.UI.正例3-Web payload 键（rules/yara/sigma）经既有装载链实际生效")
def _st_r14_payload_backend_case(ctx):
    d = ctx.tmpdir()
    yar = os.path.join(d, "ui_probe.yar")
    with open(yar, "w", encoding="utf-8") as fh:
        fh.write('rule UiProbe {\n    strings:\n        $a = "UI-PROBE-MARKER"\n    condition:\n        $a\n}\n')
    rul = os.path.join(d, "ui_rules.json")
    with open(rul, "w", encoding="utf-8") as fh:
        json.dump({"name": "UI自检规则", "level": "中危", "category": "自定义规则",
                   "scope": "cmdline", "match": ["(?i)ui-probe"]}, fh, ensure_ascii=False)
    sig = os.path.join(d, "ui_sigma.yml")
    with open(sig, "w", encoding="utf-8") as fh:
        fh.write("title: UI自检-Sigma\nlogsource:\n  product: linux\n  service: sshd\n"
                 "detection:\n  selection:\n    line|contains: UI-PROBE\n  condition: selection\n")
    c = Collector()
    try:
        _r11_cfg_reset()
        _R13.reset()
        _r11_load_cfg({"rules": rul, "allow": None, "hash_db": None}, c)
        _r11_load_cfg({"yara": yar, "yara_root": None, "sigma": sig}, c, phase="r13")
        ok = (len(_R11.get("rules") or []) == 1 and len(_R13.get("yara") or []) == 1
              and len(_R13.get("sigma") or []) == 1)
        return ok, {"r11": len(_R11.get("rules") or []), "yara": len(_R13.get("yara") or []),
                    "sigma": len(_R13.get("sigma") or []), "warnings": c.warnings[:3]}
    finally:
        _r11_cfg_reset()
        _R13.reset()


@_case("G.build_parser.正例1---no-builtin-rules 只定义一次、默认未置位且 help 明确默认启用")
def _st_r14_parser_case(ctx):
    p = build_parser()
    got = sum(1 for a in p._actions for s in a.option_strings if s == "--no-builtin-rules")
    helptext = p.format_help()
    args = p.parse_args(["win"])
    ok = (got == 1 and "--no-builtin-rules" in helptext and "默认启用" in helptext
          and getattr(args, "no_builtin_rules", None) is False)
    return ok, {"defined": got, "default": getattr(args, "no_builtin_rules", None)}


@_case("G._r13_load_builtin.容错1-内置库解析失败只告警不崩、计数兜底为 0")
def _st_r14_builtin_tolerant_case(ctx):
    c = Collector()
    g = globals()
    oy, osg = _R14_BUILTIN_YARA_TEXT, _R14_BUILTIN_SIGMA_TEXT
    try:
        g["_R14_BUILTIN_YARA_TEXT"] = ("rule Broken {\n    strings:\n        $a = /([bad/\n"
                                       "    condition:\n        $a\n}\n")
        g["_R14_BUILTIN_SIGMA_TEXT"] = "title: 坏文档\nlogsource: [broken\n"
        _R13.reset()
        _r13_load_builtin({}, c)
        ok = (bool(c.warnings) and _R13.get("builtin") is True
              and isinstance(_R13.get("builtin_yara"), int)
              and isinstance(_R13.get("builtin_sigma"), int))
        return ok, {"warnings": c.warnings[:3], "builtin_yara": _R13.get("builtin_yara"),
                    "builtin_sigma": _R13.get("builtin_sigma")}
    finally:
        g["_R14_BUILTIN_YARA_TEXT"] = oy
        g["_R14_BUILTIN_SIGMA_TEXT"] = osg
        _R13.reset()


_section("== H 组 | R15 去冗余与类化（ConditionParser / WebAppScanner / FixScriptGenerator / RuleSet / CheckStep / Collector 线程安全）==")


@_case("H.ConditionParser.正例1-YARA 与 Sigma 两条解析路径共用同一份骨架")
def _st_r15_cond_parser_case(ctx):
    yara = _YaraConditionParser(_r13_cond_tokens("$a and ($b or not $c)")).parse()
    sigma = _SigmaConditionParser(_R13_SIG_TOKEN_RE.findall("selection and not filter"),
                                  ["selection", "filter"]).parse()
    ok = (yara == ("and", ("str", "a"), ("or", ("str", "b"), ("not", ("str", "c"))))
          and sigma == ("and", ("sel", "selection"), ("not", ("sel", "filter")))
          and issubclass(_YaraConditionParser, ConditionParser)
          and issubclass(_SigmaConditionParser, ConditionParser)
          and callable(_r13_cond_parse) and callable(_r13_sigma_cond_parse))
    return ok, {"yara": yara, "sigma": sigma}


@_case("H.ConditionParser.负例1-空条件/多余片段/括号不配对/集合模式无匹配逐条隔离")
def _st_r15_cond_parser_bad_case(ctx):
    cases = ["", "$a $b", "$a and", "all of nonexistent*"]
    outs = []
    for i, txt in enumerate(cases):
        try:
            if i == 3:
                _r13_sigma_cond_parse(txt, ["selection"])
            else:
                _r13_cond_parse(txt)
            outs.append("")
        except Exception as e:
            outs.append(type(e).__name__)
    ok = all(x == "ValueError" for x in outs)
    return ok, outs


@_case("H.WebAppScanner.正例1-限量遍历/深度裁剪/提前收工（win 与 linux 口径同一实现）")
def _st_r15_webapp_scanner_case(ctx):
    d = ctx.tmpdir()
    jsp = _st_write(os.path.join(d, "webapps", "ROOT", "shell.jsp"), "x")
    jar = _st_write(os.path.join(d, "webapps", "ROOT", "WEB-INF", "lib", "a.jar"), "x")
    deep = _st_write(os.path.join(d, "webapps", "a", "b", "c", "d", "e", "deep.jsp"), "x")
    recent = _wpd_webapps_recent([d], 30)
    jars = _wpd_webinf_jars([d])
    capped = WebAppScanner([os.path.join(d, "webapps")], walk_cap=0).scan(10)
    ok = (jsp in recent and deep not in recent and jars == [jar] and capped == [])
    return ok, {"recent": recent, "jars": jars, "deep_in": deep in recent}


@_case("H.FixScriptGenerator.正例1-两平台同骨架、模板差异只在子类钩子")
def _st_r15_fix_generator_case(ctx):
    rows = {"accounts": [{"name": "evil1", "src": "S"}],
            "ips": [{"ip": "10.0.0.1", "src": "S"}],
            "files": [{"path": "/tmp/x.sh", "src": "S", "exists": True}],
            "persist": [{"title": "待清理项", "src": "S"}]}
    meta = {"host": "H", "time": "T"}
    ps = _fx_ps1(rows, meta)
    sh_text = _fx_sh(rows, meta)
    shared = [FixScriptGenerator.SEC_ACCOUNT, FixScriptGenerator.SEC_FILE,
              FixScriptGenerator.SEC_PERSIST]
    body = [ln for ln in ps.splitlines() if ln.strip()]
    ok = (all(s in ps for s in shared) and all(s in sh_text for s in shared)
          and ps.splitlines()[0] == sh_text.splitlines()[0]
          and ps.splitlines()[-1] == sh_text.splitlines()[-1]
          and len(ps.splitlines()) == len(sh_text.splitlines())
          and "net user" in ps and "usermod" in sh_text
          and all(ln.lstrip().startswith("#") for ln in body))
    return ok, {"ps_lines": len(ps.splitlines()), "sh_lines": len(sh_text.splitlines())}


@_case("H.RuleSet.正例1-重置/追加/计数/覆盖段与 Rule 子类访问口")
def _st_r15_rule_set_case(ctx):
    rs = RuleSet(_ruleset_defaults())
    rs.reset()
    n0 = (len(rs["yara"]), len(rs["sigma"]), int(rs["hits"]), bool(rs["builtin"]))
    rs.add_rules("yara", [YaraLikeRule({"name": "x"})])
    rs.hit_count({"origin": "custom"})
    rs.hit_count({"origin": "builtin"}, merged=True)
    got = (len(rs["yara"]), int(rs["hits"]), int(rs["hits_custom"]),
           int(rs["hits_builtin"]), int(rs["hits_merged"]))
    pair = YaraLikeRule({"kind": "pair", "pair": ["a", "b"]})
    sig = SigmaRule({"selections": {"s": 1}})
    ok = (n0 == (0, 0, 0, False) and got == (1, 2, 1, 1, 1)
          and pair.matcher == {"pair": ["a", "b"]}
          and sig.matcher["selections"] == {"s": 1}
          and Rule({"level": "高危"}).level == "高危"
          and Rule({}).origin == "custom"
          and "规则能力与覆盖范围" in "\n".join(rs.coverage_lines()))
    return ok, {"n0": n0, "got": got}


@_case("H.CheckStep.正例1-步骤对象仍是 (str, callable) 二元组且表长≥27/30（R16 只做加法下限口径）")
def _st_r15_check_step_case(ctx):
    win = WIN_STEPS[0]
    ok = (isinstance(win, CheckStep) and isinstance(win, tuple) and len(win) == 2
          and win[0] == win.name and callable(win[1]) and win[1] is win.runner
          and len(WIN_STEPS) >= 27 and len(LINUX_STEPS) >= 30
          and all(isinstance(it, CheckStep) for it in WIN_STEPS + LINUX_STEPS))
    return ok, {"win": len(WIN_STEPS), "linux": len(LINUX_STEPS), "first": win.name,
                "note": "R16：27/30 为下限（新增步骤只做加法，既有名称与顺序不变）"}


@_case("H.Collector.正例1-多线程并发写入不丢结论、不重复（R15/B4 锁）")
def _st_r15_collector_threads_case(ctx):
    c = Collector()
    per = 120

    def worker(k):
        for i in range(per):
            c.add("提示", "自检", "并发-%d-%d" % (k, i))
            c.raw_add("raw-%d" % k, "selftest", "%d" % i)
            c.warn("warn-%d-%d" % (k, i))
            c.count_up("k")

    ts = [threading.Thread(target=worker, args=(k,)) for k in range(4)]
    for t in ts:
        t.start()
    for t in ts:
        t.join()
    titles = set(f.title for f in c.findings)
    ok = (len(c.findings) == 4 * per and len(c.raw) == 4 * per and len(c.warnings) == 4 * per
          and c.count_of("k") == 4 * per and len(titles) == 4 * per)
    return ok, {"findings": len(c.findings), "raw": len(c.raw),
                "warnings": len(c.warnings), "counter": c.count_of("k")}


_section("== I 组 | R16（持久化归因 / 解码 / 覆盖度 / 内置规则清单）==")


@_case("I.R16.decode.正例1-逐行解码：混合 UTF-8/GBK 缓冲不再整段回退（尘 不变成 灏榎）")
def _st_r16_decode_case(ctx):
    good = "C:\\Users\\尘\\AppData".encode("utf-8")
    gbk = "服务名: 测试服务".encode("gbk")
    mixed = good + b"\r\n" + gbk + b"\r\n" + good
    t = decode_bytes(mixed)
    ok = ("C:\\Users\\尘\\AppData" in t) and ("测试服务" in t) and ("灏" not in t)
    return ok, {"mixed_ok": ok, "sample": t.replace("\r", "").replace("\n", " | ")[:90]}


@_case("I.R16.json_bom.正例1-临时 JSON 固定 utf-8-sig（Windows PowerShell 读中文路径不错码）")
def _st_r16_dsn_bom_case(ctx):
    p = None
    try:
        p = _dsn_temp_json("r16st_", {"path": "C:\\Users\\尘\\x.ps1"})
        with open(p, "rb") as fh:
            raw = fh.read()
        ok_bom = raw.startswith(b"\xef\xbb\xbf")
        obj = json.loads(raw.decode("utf-8-sig"))
        return (ok_bom and "尘" in str(obj.get("path"))), {"bom": ok_bom, "path": obj.get("path")}
    finally:
        if p:
            try:
                os.remove(p)
            except Exception as _e_r19:
                _degrade("_st_r16_dsn_bom_case", _e_r19)


@_case("I.R16.evt_xpath.正例1-EventID+时间窗+游标+tail 组合；时间片两个边界谓词")
def _st_r16_evt_xpath_case(ctx):
    preds = _evt_time_preds(win_ms=2592000000)
    x = _evt_xpath(("4698", "4699"), preds, cursor=12345,
                   tail=" and *[EventData[Data[@Name='TaskName']]]")
    ok = ("(EventID=4698 or EventID=4699)" in x and "EventRecordID < 12345" in x
          and "timediff(@SystemTime) <= 2592000000" in x
          and x.endswith("]] and *[EventData[Data[@Name='TaskName']]]"))
    slice_preds = _evt_time_preds(t_min=1000, t_max=5000)
    x2 = _evt_xpath((), slice_preds)
    ok = ok and len(slice_preds) == 2 and x2.count("TimeCreated[") == 2
    return ok, {"xpath": x[:140], "slice_preds": len(slice_preds)}


@_case("I.R16.chan_probe.正例1-gl 解析：enabled 真/假 + 不存在/拒绝访问 文案识别")
def _st_r16_chan_parse_case(ctx):
    gl_ok = "name: System\nenabled: true\ntype: Admin\n"
    gl_off = "name: Microsoft-Windows-TaskScheduler/Operational\nenabled: false\n"
    miss = "Failed to read configuration for log X.\nThe specified channel could not be found.\n"
    denied = "Access is denied."
    ok = (_r16_chan_gl_parse(gl_ok) is True and _r16_chan_gl_parse(gl_off) is False
          and _r16_chan_missing(miss) and not _r16_chan_missing(gl_ok)
          and _r16_chan_denied(denied) and not _r16_chan_denied(gl_ok))
    return ok, {"enabled_true": _r16_chan_gl_parse(gl_ok), "enabled_false": _r16_chan_gl_parse(gl_off),
                "missing": _r16_chan_missing(miss), "denied": _r16_chan_denied(denied)}


@_case("I.R16.attr.正例1-任务创建事件+进程创建对齐出三元组；负例=无归因契约短语")
def _st_r16_attr_case(ctx):
    item = {"kind": "计划任务", "name": "\\Evil\\SchTask",
            "target": "C:\\Users\\Public\\evil.exe -run", "ts": 0, "reg": ""}
    tokens = _attr_tokens(item)      # R17：返回值升级为结构化匹配项（值,字段,相等方式,强度）
    task_ev = [(1760600000, "T", {"TaskName": "\\Evil\\SchTask", "SubjectUserName": "adm"})]
    proc_ev = [(1760599990, "T-10", {"Image": "C:\\Users\\Public\\evil.exe",
                                     "CommandLine": "evil.exe -run",
                                     "ParentImage": "C:\\Windows\\System32\\cmd.exe",
                                     "ParentCommandLine": "cmd /c start"})]
    task_hit = _attr_scan(task_ev, tokens, ("TaskName", "TaskContent"))
    creator = _attr_creator(proc_ev, _attr_process_terms(item, item.get("kind")),
                            anchor=task_hit[0][0]["ep"] if task_hit else 0,
                            label="Sysmon 1 进程创建")
    note = _attr_risk_note((creator[0], creator[1], creator[2], creator[4]) if creator else None)
    no_hit = not _attr_scan([], tokens, ("TaskName",))
    ok = (bool(task_hit) and creator is not None and bool(note) and no_hit
          and _R16_NO_ATTR == "无归因（仅见结果，未见创建过程）")
    return ok, {"task_hit": bool(task_hit), "hit_ep": task_hit[0][0]["ep"] if task_hit else None,
                "creator": (creator[2].get("Image") if creator else None),
                "risk_note": note, "no_attr": _R16_NO_ATTR,
                "terms": [(t[0], t[2], t[3]) for t in tokens]}


def _st_r17_attr_stub(items, pool, tier="default"):
    """R17 归因用例夹具：把事件查询换成给定事件池（不碰真机日志），其余走产品路径。

    pool 以「事件源键 → [(epoch, 时间串, 字段字典)]」给出；按查询的 EventID 集合路由
    （Security 通道同时承载 4698 任务与 4697/4688，故不能按通道名建字典）。
    """
    global _R17_TIER
    prev = _R17_TIER
    _R17_TIER = tier
    c = Collector(days=1)
    for it in items:
        c.persist_add(*it)
    chan2key = dict((s[1], s[0]) for s in _R16_ATTR_SOURCES)
    ids2key = dict((tuple(str(i) for i in s[2]), s[0]) for s in _R16_ATTR_SOURCES)
    orig = (_r16_chan_state, _adv_query)
    globals()["_r16_chan_state"] = lambda cc, ch: None
    globals()["_adv_query"] = lambda cc, ch, ids, win, count=0, timeout=0, label="", **kw: (
        (pool.get(ids2key.get(tuple(str(i) for i in (ids or ())))
                  or chan2key.get(ch), []), ""))
    try:
        win_persist_attribution(c)
    finally:
        globals()["_r16_chan_state"], globals()["_adv_query"] = orig
        _R17_TIER = prev
    return c


def _st_r17_verdict(c, kind, needle):
    """从结论里取「条目 → 归因等级」（标题形如 持久化归因：[种类] 名称（等级））。"""
    for f in c.findings:
        if f.category == "持久化归因" and f.title.startswith("持久化归因：[%s]" % kind) \
                and needle in f.title:
            for lv in _R17_ATTR_LEVELS:
                if f.title.endswith("（%s）" % lv):
                    return lv, f
    return "", None


@_case("I.R17.attr.反例1-条目路径全是通用片段+池中无关进程 ⇒ 必须无归因（不得猜创建者）")
def _st_r17_attr_neg1_case(ctx):
    lnk = ("C:\\Users\\u\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\"
           "Startup\\abc.lnk")
    pool = {"proc_create": [(1760600000, "T", {"Image": "C:\\Windows\\System32\\bash.exe",
                                               "ProcessId": "1", "CommandLine":
                                               'bash.exe -c "ls C:\\Program Files"'})],
            "file_create": [(1760600000, "T", {"TargetFilename":
                                               "C:\\Users\\u\\AppData\\Local\\Temp\\x.tmp"})]}
    c = _st_r17_attr_stub([("启动文件夹", lnk, "")], pool)
    lv, f = _st_r17_verdict(c, "启动文件夹", "abc.lnk")
    txt = (f.detail or "") if f else ""
    ok = lv == "无归因" and _R16_NO_ATTR in txt and "bash.exe" not in txt \
        and "appdata" not in txt.lower().replace("appdata\\roaming", "")
    return ok, {"verdict": lv, "detail": txt[:300]}


