def _r18_st_fw_run(ev, count_result):
    """公共桩：打桩 _adv_query（仅 2033 返回事件）与 _r18_fw_rule_count，跑 _adv_firewall。"""
    c = Collector(days=1)
    orig_q, orig_cnt = globals().get("_adv_query"), globals().get("_r18_fw_rule_count")

    def fake_q(c2, channel, ids, *a, **kw):
        if "2033" in [str(i) for i in (ids or ())]:
            return list(ev), ""
        return [], ""

    try:
        globals()["_adv_query"] = fake_q
        globals()["_r18_fw_rule_count"] = lambda: count_result
        _adv_firewall(c, None, _evt_scope(1))
    finally:
        globals()["_adv_query"] = orig_q
        globals()["_r18_fw_rule_count"] = orig_cnt
    return c


