# ============================================================ R10 取证与响应（增量）
# 依据：R10 任务书（2026-10-14）《取证与响应》需求 1-7；test.md 五、取证与响应。
# 语义：本节全部为增量能力，不改变“只读检测”语义——
#   * 默认运行（不带新参数）只在报告目录内新增两个产物：timeline.csv / manifest.sha256；
#   * 取证包（--collect-evidence）与处置脚本（--gen-fix）只在显式给出的目录里写盘，
#     且所有落盘都先经 _r10_write() 的 realpath + commonpath 越界校验，越界一律拒绝；
#   * 通知（--webhook / --mail-to）默认关闭（零出网），失败只 c.warn()，不阻塞、不影响退出码；
#   * 处置脚本只生成不执行：可执行行一律整行注释，首行固定“人工确认后手动执行”警告。
# 命名：本区新增符号统一使用 _r10_ / _atk_ / _tlx_ / _evp_ / _fx_ / _mgx_ / _ntf_ 前缀，
#       与既有符号（_nt_* 网络面、ATTACK_PATH、_app_collect 等）无重名。

R10_PLATFORM = "Windows" if IS_WIN else ("Linux/Unix" if os.name == "posix" else os.name)


# ---------------------------------------------------------------- 写盘守卫（越界即拒绝）

def _r10_realpath(p):
    try:
        return os.path.realpath(os.path.abspath(str(p)))
    except Exception:
        return ""


def _r10_under(base, path):
    """判断 path 是否位于 base 目录内（含 base 自身）。纯 realpath 计算，不落盘。"""
    b, t = _r10_realpath(base), _r10_realpath(path)
    if not b or not t:
        return False
    if b == t:
        return True
    try:
        return os.path.commonpath([b, t]) == b
    except Exception:                      # 不同盘符/异常输入
        return False


def _r10_mkdir(base, path):
    if not _r10_under(base, path):
        return False
    try:
        if not os.path.isdir(path):
            os.makedirs(path)
        return True
    except Exception:
        return False


def _r10_write(base, path, text, enc="utf-8"):
    """R10 统一落盘入口：写前校验目标位于 base 目录内，越界/失败返回 False。

    只被「报告目录 / 取证目录 / 处置脚本目录」这三处已授权范围调用。
    """
    if not _r10_under(base, path):
        return False
    try:
        d = os.path.dirname(os.path.abspath(path))
        if d and not os.path.isdir(d):
            os.makedirs(d)
        with open(path, "w", encoding=enc, errors="replace", newline="") as f:
            f.write(text)
        return True
    except Exception:
        return False


def _r10_csv_cell(v):
    """CSV 单元格转义：含逗号/引号加引号；换行折叠为空格，保证一行一记录。"""
    s = "" if v is None else str(v)
    s = s.replace("\r\n", " ").replace("\n", " ").replace("\r", " ")
    if any(ch in s for ch in ',"'):
        s = '"' + s.replace('"', '""') + '"'
    return s


def _r10_csv_text(header, rows):
    """生成 CSV 文本（CRLF 行尾；配合 utf-8-sig 便于 Excel 直接打开）。"""
    out = [",".join(_r10_csv_cell(h) for h in header)]
    for r in rows:
        out.append(",".join(_r10_csv_cell(c) for c in r))
    return "\r\n".join(out) + "\r\n"


def _r10_ts_from_epoch(epoch):
    try:
        return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(float(epoch)))
    except Exception:
        return ""


def _r10_dirs_for(platform_name):
    """关键“落地/持久化”目录（取证包与时间线素材共用的最小清单）。仅返回存在的目录。"""
    if platform_name == "win":
        e = os.environ
        home = e.get("USERPROFILE") or ""
        cand = [e.get("TEMP"), e.get("TMP"),
                os.path.join(home, "Downloads") if home else "",
                e.get("PUBLIC"), e.get("ProgramData"),
                os.path.join(e.get("APPDATA") or "",
                             r"Microsoft\Windows\Start Menu\Programs\Startup") if e.get("APPDATA") else ""]
    else:
        cand = ["/tmp", "/var/tmp", "/dev/shm", "/etc", "/var/spool/cron"]
    out = []
    for p in cand:
        try:
            if p and os.path.isdir(p) and _r10_realpath(p) not in [_r10_realpath(x) for x in out]:
                out.append(p)
        except Exception:
            continue
    return out


def _r10_recent_files(roots, days, per_dir=80, max_scan=4000):
    """只读扫描：返回 [(路径, 大小, mtime, 根目录)]，最近修改优先；带访问上限，绝不写盘。"""
    out = []
    cutoff = time.time() - max(1, int(days or DEFAULT_DAYS)) * 86400
    scanned = 0
    skip = ("windows", "winsxs", "node_modules", ".git", "__pycache__", "system32", "syswow64")
    for root in roots:
        try:
            if not root or not os.path.isdir(root):
                continue
        except Exception:
            continue
        real_root = _r10_realpath(root)
        got = 0
        try:
            walker = os.walk(real_root, onerror=lambda e: None)
        except Exception:
            continue
        for dirpath, dirnames, filenames in walker:
            dirnames[:] = [d for d in dirnames if d.lower() not in skip][:40]
            for fn in filenames:
                scanned += 1
                if scanned > max_scan or got >= per_dir:
                    break
                p = os.path.join(dirpath, fn)
                try:
                    st = os.stat(p)
                    if st.st_mtime >= cutoff:
                        out.append((p, int(st.st_size), st.st_mtime, real_root))
                        got += 1
                except Exception:
                    continue
            if scanned > max_scan or got >= per_dir:
                break
    out.sort(key=lambda t: t[2], reverse=True)
    return out


# ---------------------------------------------------------------- ATT&CK 映射（需求 4）
# 只按「分类 + 标题」中的高置信关键词映射；提示级与“未发现/未命中”类一律不标注，
# 避免给“未发现可疑计划任务”这类阴性结论打上 T1053.005。

