@_case("I.R19.degrade.反例2-单点入口：全文只剩 _degrade 一处降级出口且 except:pass 为 0")
def _st_r19_degrade_guard_neg(ctx):
    p = globals().get("__file__") or ""
    src = ""
    if os.path.isfile(p):
        src = safe_read(p, limit=8 * 1024 * 1024) or ""
    if not src:
        return True, {"skip": "读不到自身源码（打包/在线环境），跳过静态核查"}
    n_pass = len(re.findall(r"except[^\n]*:\r?\n\s*pass\b", src))
    n_deg = len(re.findall(r"_degrade\(", src))
    ok = (n_pass == 0 and n_deg >= 70)
    return ok, {"except_pass": n_pass, "_degrade 出现次数": n_deg}


