# ============================================================ J 组 | R20（Web 一键 · 模式同源 · 命令失败判定）

def _r20_self_src():
    """读自身源码（静态核查用）；读不到返回 ""（打包/在线环境自动跳过静态核查）。"""
    p = globals().get("__file__") or ""
    if os.path.isfile(p):
        return safe_read(p, limit=8 * 1024 * 1024) or ""
    return ""


def _r20_src_slice(name, src):
    """按函数名切源码片段（从 ^def name( 到下一个顶层 def）；找不到返回 ""。"""
    m = re.search(r"(?m)^def %s\(.*?(?=^def |\Z)" % re.escape(name), src or "", re.S)
    return m.group(0) if m else ""


def _r20_st_apache(ip, path, ua, hours_ago, status="200"):
    """R20 夹具：动态时间的 Apache/nginx combined 行（不依赖固定日期）。"""
    t = time.localtime(time.time() - float(hours_ago) * 3600)
    return '%s - - [%s +0800] "GET %s HTTP/1.1" %s 512 "-" "%s"' % (
        ip, time.strftime("%d/%b/%Y:%H:%M:%S", t), path, status, ua)


def _r20_st_fixture(ctx):
    """R20 夹具：logs/（当前 + .gz 轮转 + 窗口外）+ www/（马 + 干净文件）+ nginx root 配置。"""
    root = ctx.tmpdir()
    logs = os.path.join(root, "logs")
    site = os.path.join(root, "www")
    os.makedirs(logs)
    os.makedirs(site)
    with open(os.path.join(logs, "access.log"), "w", encoding="utf-8") as f:
        f.write(_r20_st_apache("10.9.9.9", "/index.php", "Mozilla/5.0", 2) + "\n")
        f.write(_r20_st_apache("10.9.9.9", "/shell.php?cmd=whoami", "sqlmap/1.7", 2) + "\n")
    import gzip
    with gzip.open(os.path.join(logs, "access.log.1.gz"), "wt", encoding="utf-8") as f:
        f.write(_r20_st_apache("10.9.9.8", "/marker_r20_gz", "Mozilla/5.0", 24) + "\n")
    with gzip.open(os.path.join(logs, "access.log.2.gz"), "wt", encoding="utf-8") as f:
        f.write(_r20_st_apache("10.9.9.7", "/marker_r20_old", "Mozilla/5.0", 24 * 45) + "\n")
    _st_write(os.path.join(site, "shell.php"), "<?php system($_POST['cmd']); ?>")
    _st_write(os.path.join(site, "clean.php"), "<?php echo 'ok'; ?>")
    _st_write(os.path.join(site, "pic.png"), "GIF89a" + "A" * 80)
    conf = os.path.join(root, "nginx_r20.conf")
    _st_write(conf, "server {\n  root %s;\n}\n" % site.replace("\\", "/"))
    specs = {"logs": (("自检nginx", logs, ("access.log*",), "自检夹具"),),
             "roots": (), "confs": (("自检配置", (conf,), "nginx", "解析 root"),),
             "sysdrive": "C:"}
    return root, logs, site, conf, specs


def _r20_ev_xml(rid, extra=""):
    """R20 夹具：一条 wevtutil /f:xml 事件（可带中文错误词样例数据）。"""
    return ('<Event xmlns="http://schemas.microsoft.com/win/2004/08/events/event">'
            '<System><EventID>1</EventID><EventRecordID>%s</EventRecordID>'
            '<TimeCreated SystemTime="2026-10-16T10:00:00.000000000Z"/>'
            '<Channel>Security</Channel></System>'
            '<EventData><Data Name="X">%s</Data></EventData></Event>' % (rid, extra))


_section("== J 组 | R20（Web 一键 · 模式同源 · 命令失败判定）==")


@_case("J.R20.discover.正例1-自动发现命中（换一组名字/路径仍成立：日志+gz+配置 root）")
def _st_r20_disc_pos(ctx):
    _root, _logs, site, _conf, specs = _r20_st_fixture(ctx)
    found, skips = r20_discover_logs("linux", specs=specs["logs"])
    roots, _rskips = r20_discover_site_roots("linux", specs=specs["roots"],
                                             conf_specs=specs["confs"])
    names = [os.path.basename(e["path"]) for e in found]
    ok = (names[:3] == ["access.log", "access.log.1.gz", "access.log.2.gz"]
          and any(r["path"] == site.replace("\\", "/") for r in roots))
    return ok, {"logs": names, "roots": [r["path"] for r in roots], "skips": skips[:2]}


@_case("J.R20.discover.负例1-无 Web 服务：结论区 0 条 + 覆盖度合并声明（含查找位置与上限）")
def _st_r20_disc_empty(ctx):
    root = ctx.tmpdir()
    # 机器上没有 Web 服务：目录不存在（自动发现表全部落空，声明跳过且不报错）
    specs = {"logs": (("空目录", os.path.join(root, "nologs"), ("access.log*",), "自检"),),
             "roots": (("空站点", os.path.join(root, "nosites"), "自检"),),
             "confs": (("缺失配置", (os.path.join(root, "no.conf"),), "nginx", "自检"),),
             "sysdrive": "C:"}
    c = Collector(days=30)
    run_weblog_step(c, {"days": 30, "r20_specs": specs}, platform="linux")
    run_webshell_step(c, {"days": 30, "r20_specs": specs}, platform="linux")
    cov = "\n".join(_r16_coverage_lines(c))
    # R22/P3 新口径：未发现 Web 资产不再产出结论级提示；合并声明进「数据源与覆盖度」段
    ok = (len(c.findings) == 0
          and "未发现 Web 访问日志与站点目录，跳过对应步骤" in cov
          and "查找位置：" in cov and "单日志尾部读取 256MB" in cov
          and "weblog --log" not in cov and "webshell --dir" not in cov)
