@_case("J.R20.limit.反例1-目录超限：窗口内 mtime 优先占名额 + 截断声明")
def _st_r20_dir_cap(ctx):
    root = ctx.tmpdir()
    cap_root = os.path.join(root, "wwwcap")
    os.makedirs(cap_root)
    old_t = time.time() - 40 * 86400
    for name in ("a1.php", "a2.php", "a3.php"):
        p = os.path.join(cap_root, name)
        _st_write(p, "<?php system($_POST['cmd']); ?>")
        os.utime(p, (old_t, old_t))
    for name in ("z1.php", "z2.php"):
        _st_write(os.path.join(cap_root, name), "<?php system($_POST['cmd']); ?>")
    prev = globals().get("_R20_DIR_MAX_FILES")
    try:
        globals()["_R20_DIR_MAX_FILES"] = 3
        stats = {}
        files, _susp = webshell_scan_paths(Collector(), [cap_root], days=30, max_files=3,
                                           max_size=_R20_DIR_MAX_SIZE, prefer_recent=True,
                                           stats=stats)
        picked = [os.path.basename(x) for x in files]
        specs = {"logs": (), "roots": (("自检站点", cap_root, "自检夹具"),), "confs": (),
                 "sysdrive": "C:"}
        c2 = Collector(days=30)
        run_webshell_step(c2, {"days": 30, "r20_specs": specs}, platform="linux")
        cov = "\n".join(_r16_coverage_lines(c2))
        ok = (len(files) == 3 and "z1.php" in picked and "z2.php" in picked
              and int(stats.get("capped") or 0) == 2
              and "已按「窗口内 mtime 变动者优先」截断" in cov and "已截断" in cov)
        return ok, {"picked": picked, "capped": stats.get("capped")}
    finally:
        globals()["_R20_DIR_MAX_FILES"] = prev


