@_case("L.R22.mine.正例3-win_process_anomaly 全链路打桩：回环命中落提示且带进程身份")
def _st_r22_mine_wired(ctx):
    rows = [{"ProcessId": "4321", "Name": "vECAgent.exe",
             "ExecutablePath": r"C:\Program Files\Sangfor\vECAgent\vECAgent.exe",
             "CommandLine": "vECAgent.exe", "ParentProcessId": "4"}]
    orig = {k: globals().get(k) for k in ("wmic_csv", "win_cmd", "safe_read", "_hj_adv_sig_map")}

    def fake_wmic_csv(expr, *a, **k):
        return list(rows), "raw"

    def fake_win_cmd(cmd, timeout=0):
        head = list(cmd)[:1]
        if head == ["netstat"]:
            return _R22_NS_LOOP, ""
        if head == ["ipconfig"]:
            return ("IPv4 地址 . . . . . . . . . . . . : 192.168.1.5\r\n"
                    "IPv4 地址 . . . . . . . . . . . . : 127.0.0.1\r\n"), ""
        return "", ""

    def fake_safe_read(path, *a, **k):
        return ""

    try:
        globals()["wmic_csv"] = fake_wmic_csv
        globals()["win_cmd"] = fake_win_cmd
        globals()["safe_read"] = fake_safe_read
        globals()["_hj_adv_sig_map"] = lambda c2, paths, tag="": {
            p.lower(): ("Valid", "cn=sangfor", "") for p in (paths or [])}
        c = Collector()
        win_process_anomaly(c)
    finally:
        for k, v in orig.items():
            globals()[k] = v
    fs = [f for f in c.findings if "矿池" in (f.title or "")]
    ok = (len(fs) == 1 and fs[0].level == "提示"
          and "回环端口命中矿池端口表（需人工确认）" in fs[0].title
          and "127.0.0.1 -> 127.0.0.1:3333 (PID 4321) 矿池常用端口" in (fs[0].detail or "")
          and "进程=vECAgent.exe" in (fs[0].detail or "")
          and "签名状态=Valid" in (fs[0].detail or ""))
    return ok, {"titles": [f.title for f in c.findings][:6]}


def _r22_frag_utf8_fixture():
    """UTF-8 夹具：中文注释块 + 1 字节分隔符 + 一句话木马（让 ms-60 恰好切在汉字中间）。"""
    cn = ("\u6c49\u5b57\u6837\u672c" * 20).encode("utf-8")     # 4 字 × 3 字节 × 20 = 240 字节
    payload = b"<?php eval($_POST['x']); ?>"
    return b"/* " + cn + b"#" + payload + b" */\n"


def _r22_frag_first_hit(data):
    """按 webshell_score 的规则次序取首个命中的 (ms, me)（与产品同一判据）。"""
    for row in list(WEBSHELL_RULES) + list(WEBSHELL_RULES_EXTRA):
        m = row[0].search(data)
        if m:
            return m.start(), m.end()
    return None, None


@_case("L.R22.frag.正例1-UTF-8 中文横跨窗口起点：片段整字、无 U+FFFD、命中文本完整")
def _st_r22_frag_utf8(ctx):
    data = _r22_frag_utf8_fixture()
    ms, me = _r22_frag_first_hit(data)
    premise = (ms is not None and ms - 60 >= 3 and 0x80 <= data[ms - 60] <= 0xBF)
    old = decode_bytes(data[max(0, ms - 60):min(len(data), me + 60)])
    snip = _webshell_frag(data, ms, me)
    _score, _hits, snips = webshell_score(r"D:\www\r22utf8.php", data)
    ok = (premise and "\ufffd" in old                       # 旧切片确会切出半个字符（缺陷前提）
          and "\ufffd" not in snip and "eval($_POST" in snip
          and "\u6c49\u5b57\u6837\u672c" in snip and snips and snips[0] == snip)
    return ok, {"premise": premise, "old_has_fffd": "\ufffd" in old, "snip": snip[:90]}


@_case("L.R22.frag.正例2-GBK 中文横跨窗口起点：片段整字、无 U+FFFD、文字完整")
def _st_r22_frag_gbk(ctx):
    cn = ("\u6c49\u5b57\u6837\u672c" * 20).encode("gbk")       # 4 字 × 2 字节 × 20 = 160 字节
    data = b"//" + cn + b"##" + b"<?php system($_POST['cmd']); ?>" + b"\n"
    ms, me = _r22_frag_first_hit(data)
    premise = (ms is not None and ((ms - 60) - 2) % 2 == 1)   # 起点切在双字节字符中间
    snip = _webshell_frag(data, ms, me)
    ok = (premise and "\ufffd" not in snip and "$_POST['cmd']" in snip
          and "\u6c49\u5b57\u6837\u672c" in snip)
    return ok, {"premise": premise, "snip": snip[:90]}


@_case("L.R22.frag.负例1-不可解码字节环绕的窗口：片段仍无 U+FFFD（契约）且不抛异常")
def _st_r22_frag_binary(ctx):
    data = b"\x00\xff\xfe\x01" + b"\x80\x81\x82" + b"<?php eval($_POST['x']); ?>"
    ms, me = _r22_frag_first_hit(data)
    ms = ms if ms is not None else 0
    me = me if me is not None else len(data)
    snip = _webshell_frag(data, ms, me)
    ok = isinstance(snip, str) and "\ufffd" not in snip and "eval($_POST" in snip
    return ok, {"snip": snip[:90]}


@_case("L.R22.frag.负例2-片段实现单一定义：全文件枚举后无第二处「字节窗切片→解码」")
def _st_r22_frag_single(ctx):
    src = _r20_self_src()
    if not src:
        return True, {"skip": "读不到自身源码（仅跳过静态核查）"}
    ws = _r20_src_slice("webshell_score", src)
    old_slice = "decode_bytes(" + "data[start" + ":end])"     # 旧实现特征串（拼接防自命中）
    frag_def = "def " + "_webshell_frag("
    bounds_def = "def " + "_r22_frag_line_bounds("
    ok = ("_webshell_frag(data" in ws and old_slice not in src
          and src.count(frag_def) == 1 and src.count(bounds_def) == 1)
    return ok, {"ws_calls_frag": "_webshell_frag(data" in ws,
                "old_slice_decode_left": old_slice in src}


@_case("L.R22.frag.正例3-单点 webshell 实跑（--dir 语义）：结论明细片段无 U+FFFD 且中文完整")
def _st_r22_frag_run_mode(ctx):
    root = ctx.tmpdir()
    site = os.path.join(root, "www")
    os.makedirs(site)
    with open(os.path.join(site, "hack.php"), "wb") as f:
        f.write(_r22_frag_utf8_fixture())
    c = Collector(days=30)
    run_mode(c, "webshell", {"dir": site, "days": 30})
    detail = "\n".join((f.detail or "") for f in c.findings)
    ok = (bool(c.findings) and "\ufffd" not in detail and "片段:" in detail
          and "eval($_POST" in detail and "\u6c49\u5b57\u6837\u672c" in detail)
    return ok, {"findings": len(c.findings), "detail": detail[:120]}


