# ============================================================ M 组 | R23（Linux 网络/日志取证 · Windows 横向/痕迹 · 规则扩表）
# 依据：R23 需求书 P1~P5。每条新规则都配「造样本 ⇒ 命中 / 删样本 ⇒ 不命中」成对用例；
# 阴性样本只差触发条件（同一夹具、同一调用路径，仅去掉命中要素）。

_section("== M 组 | R23（Linux 网络/日志取证 · Windows 横向/痕迹 · 规则扩表）==")


def _r23_raw(c, key):
    """raw 输出查找（自检用）：标题含 key 的条目输出文本；找不到返回 ""。"""
    for t, _s, o in c.raw:
        if key in t:
            return o or ""
    return ""


def _r23_proc_fixture(root, tcp_text):
    """R23/P1 夹具：最小 /proc 树（net/tcp 指定内容 + net/tcp6 空）。"""
    netd = os.path.join(root, "proc", "net")
    if not os.path.isdir(netd):
        os.makedirs(netd)
    # 与内核输出一致带上表头行（linux_net_proc 按 splitlines()[1:] 跳过表头）
    header = ("  sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt"
              "   uid  timeout inode\n")
    _st_write(os.path.join(netd, "tcp"), header + tcp_text)
    _st_write(os.path.join(netd, "tcp6"), "")
    return netd


def _r23_tcp_line(lport, rip_hex, rport, state, inode, lip_hex="0100007F"):
    """R23/P1 夹具：/proc/net/tcp 一行（列序与内核一致）。"""
    return ("   0: %s:%04X %s:%04X %s 00000000:00000000 00:00000000 00000000  1000 0 %d 1 "
            "ffff8880 100 0 0 10 0" % (lip_hex, lport, rip_hex, rport, state, inode))


def _r23_secure_fixture(root, lines):
    """R23/P2 夹具：写 /var/log/secure 并返回 Collector（离线根目录模式）。"""
    _st_write(os.path.join(root, "var", "log", "secure"), "\n".join(lines) + "\n")
    return Collector(root=root, days=30)


def _r23_stub_win_process_net(c, netstat_text, nb_opts="Intel(R) Ethernet=2\n",
                              lanman="STATE : 1  STOPPED\n", server="STATE : 1  STOPPED\n"):
    """R23/P3 夹具：打桩跑 win_process_net（进程/网络/NetBIOS 三源均可控）。"""
    rows = [{"ProcessId": "4242", "Name": "cmd.exe",
             "ExecutablePath": r"C:\Windows\System32\cmd.exe",
             "CommandLine": "cmd.exe", "ParentProcessId": "4"}]
    orig = {k: globals().get(k) for k in ("wmic_csv", "win_cmd")}

    def fake_wmic_csv(expr, *a, **k):
        return list(rows), "raw"

    def fake_win_cmd(cmd, timeout=0):
        args = list(cmd)
        if args[:2] == ["netstat", "-ano"]:
            return netstat_text, ""
        if args[:3] == ["sc", "query", "LanmanServer"]:
            return lanman, ""
        if args[:3] == ["sc", "query", "Server"]:
            return server, ""
        if args[:1] == ["powershell"]:
            return nb_opts, ""
        return "", ""

    try:
        globals()["wmic_csv"] = fake_wmic_csv
        globals()["win_cmd"] = fake_win_cmd
        win_process_net(c)
    finally:
        for k, v in orig.items():
            globals()[k] = v


@_case("M.R23.netstate.正例1-/proc/net/tcp 状态全谱：按状态计数一行 + 半开/短连接明细（20 条封顶）")
def _st_r23_netstate_pos(ctx):
    root = ctx.tmpdir()
    lines = [_r23_tcp_line(0x1F90, "00000000", 0, "0A", 99),           # LISTEN 8080
             _r23_tcp_line(0x9C40, "08080808", 0x01BB, "01", 100)]     # ESTABLISHED
    lines += [_r23_tcp_line(0xA000 + i, "08080808", 0x1000 + i, "06", 200 + i)
              for i in range(25)]                                       # TIME_WAIT ×25
    lines.append(_r23_tcp_line(0xB000, "04040404", 0x0050, "03", 300))  # SYN_RECV
    _r23_proc_fixture(root, "\n".join(lines) + "\n")
    c = Collector(root=root, days=30)
    linux_net_proc(c)
    raw = _r23_raw(c, "连接状态计数")
    half = [f for f in c.findings if "半开/短连接痕迹（需人工确认）" in (f.title or "")]
    ok = ("按状态计数: ESTABLISHED=1、SYN_RECV=1、TIME_WAIT=25、LISTEN=1" in raw
          and "采样次数: 3" in raw
          and len(half) == 1 and len(half[0].evidence or []) == 20
          and "SYN_RECV" in (half[0].detail or "") and "TIME_WAIT" in (half[0].detail or ""))
    return ok, {"raw": raw[:240], "evidence_n": len(half[0].evidence or []) if half else -1}


@_case("M.R23.netstate.负例1-只有 LISTEN/ESTABLISHED：不出半开提示，状态计数与采样次数仍在报告里")
def _st_r23_netstate_neg(ctx):
    root = ctx.tmpdir()
    _r23_proc_fixture(root, "\n".join([
        _r23_tcp_line(0x1F90, "00000000", 0, "0A", 99),
        _r23_tcp_line(0x9C40, "0100007F", 0x1F90, "01", 100)]) + "\n")   # 回环连接：不触发外网提示
    c = Collector(root=root, days=30)
    linux_net_proc(c)
    raw = _r23_raw(c, "连接状态计数")
    clean = [f for f in c.findings if (f.title or "").startswith("网络连接未命中可疑特征")]
    ok = (not [f for f in c.findings if "半开/短连接" in (f.title or "")]
          and "按状态计数: ESTABLISHED=1、LISTEN=1" in raw and "采样次数: 3" in raw
          and len(clean) == 1 and "采样次数: 3" in (clean[0].detail or ""))
    return ok, {"raw": raw[:200], "clean_detail": (clean[0].detail if clean else "")[:120]}


def _r23_run_with_samples(root, samples):
    """R23/P1 夹具：以桩替换采样入口跑 linux_net_proc，返回 Collector（用例后恢复）。"""
    orig = globals().get("_net_sample_rows")
    state = {"i": 0}

    def fake(c2, _map):
        i = state["i"]
        state["i"] = i + 1
        return list(samples[i]) if i < len(samples) else []

    try:
        globals()["_net_sample_rows"] = fake
        c = Collector(root=root, days=30)
        linux_net_proc(c)
    finally:
        globals()["_net_sample_rows"] = orig
    return c


