@_case("N.R24.lpdfd.scan.正例1-伪 /proc 树端到端：三类命中各自独立成条（PID/fd/路径/判据/命令行齐全），常规句柄零条目")
def _st_r24_lpdfd_scan_case(ctx):
    proc = _st_r24_fake_proc(ctx, [
        (101, "evilbin", "evilbin --x",
         [(3, "/opt/app/x.so (deleted)"), (4, "socket:[11]"), (5, "/usr/lib/libc.so.6")]),
        (102, "cron", "cron -f",
         [(0, "/dev/null"), (6, "/tmp/run.sh"), (7, "/var/log/syslog")]),
        (103, "java", "java -jar app.jar", [(8, "memfd:code"), (9, "pipe:[4]")]),
    ])
    rows, st = _lpd_fd_scan(proc)
    c = Collector()
    _lpd_fd_report(c, rows, st)
    detail = "\n".join(f.detail or "" for f in c.findings)
    kinds = sorted(set(r[0] for r in rows))
    ok = (kinds == ["abnormal", "deleted", "tmp_exec"] and len(rows) == 3
          and all("句柄-①" in (r[3] or "") or "句柄-②" in (r[3] or "") or "句柄-③" in (r[3] or "")
                  for r in rows)
          and "PID 101(evilbin) fd=3 -> /opt/app/x.so (deleted)" in detail
          and "命令行: evilbin --x" in detail
          and st["fds_scanned"] == 8 and not st["global_hit_cap"] and not st["pid_sampled"]
          and len(c.findings) == 3
          and all(f.category == "进程与内存深度" for f in c.findings)
          and not [f for f in c.findings if "未命中" in (f.title or "")])
    return ok, {"kinds": kinds, "rows": len(rows), "fds": st["fds_scanned"],
                "findings": [f.level + "|" + f.title[:24] for f in c.findings]}


@_case("N.R24.lpdfd.limits.正例1-触限三态（进程抽样/单进程 fd 上限/全局 fd 上限）：结论与覆盖度段双声明「已截断/按 N 个进程抽样」")
def _st_r24_lpdfd_limits_case(ctx):
    proc = _st_r24_fake_proc(ctx, [
        (201, "a", "a", [(3, "/tmp/a.sh"), (4, "/tmp/b.sh"), (5, "/tmp/c.sh"), (6, "/tmp/d.sh")]),
        (202, "b", "b", [(3, "/tmp/e.sh")]),
        (203, "c", "c", [(3, "/tmp/f.sh")]),
    ])
    rows, st = _lpd_fd_scan(proc, pid_cap=1, per_proc=2, total_cap=1)
    c = Collector()
    _lpd_fd_report(c, rows, st)
    tip = [f for f in c.findings if "已截断/抽样" in (f.title or "")]
    txt = "\n".join(_lpd_fd_coverage_lines(c))
    cov_all = "\n".join(_r16_coverage_lines(c))
    ok = (st["pid_sampled"] and st["fd_capped_pids"] == 1 and st["global_hit_cap"]
          and len(tip) == 1
          and "按 1 个进程抽样" in (tip[0].detail or "")
          and "单进程 fd 上限 2" in (tip[0].detail or "")
          and "全局 fd 上限 1" in (tip[0].detail or "")
          and "已截断" in (tip[0].detail or "")
          and "按 1 个进程抽样" in txt and "已截断" in txt
          and "进程句柄面（/proc/<pid>/fd，R24/P1）" in cov_all
          and any("句柄-②" in (r[3] or "") for r in rows))
    return ok, {"st": {"pid_sampled": st["pid_sampled"], "capped": st["fd_capped_pids"],
                       "global": st["global_hit_cap"]},
                "tip": (tip[0].detail or "")[:160] if tip else "", "cov": txt[:120]}


@_case("N.R24.lpdfd.cover.正例1-无 /proc：整面跳过 + 覆盖度段声明；负例-伪 /proc 正常完成不写跳过声明")
def _st_r24_lpdfd_cover_case(ctx):
    c1 = Collector()
    _lpd_fd_surface(c1, os.path.join(ctx.tmpdir(), "no_proc_here"))
    txt1 = "\n".join(_r16_coverage_lines(c1))
    c2 = Collector()
    proc = _st_r24_fake_proc(ctx, [(301, "sshd", "/usr/sbin/sshd -D",
                                    [(3, "/usr/lib/libc.so.6"), (4, "socket:[1]")])])
    _lpd_fd_surface(c2, proc)
    txt2 = "\n".join(_r16_coverage_lines(c2))
    ok = (bool(c1.warnings) and "整面跳过" in txt1
          and "进程句柄面（/proc/<pid>/fd，R24/P1）" in txt1
          and "整面跳过" not in txt2 and not c2.warnings
          and [f for f in c2.findings if "未命中可疑句柄" in (f.title or "")]
          and not [f for f in c2.findings if "已截断" in (f.title or "")])
    return ok, {"warn": c1.warnings[:1], "skip_in_cov": "整面跳过" in txt1,
                "neg_skip": "整面跳过" in txt2, "neg_findings": len(c2.findings)}


