@_case("N.R24.javaagent.正例1-高危/中危 -javaagent 建议均含 jcmd/jmap 授权取证提示与只读声明（等级与命中面不变）")
def _st_r24_javaagent_case(ctx):
    procs = {100: {"name": "java.exe",
                   "cmd": r"java -javaagent:C:\Users\Public\agent.jar -jar app.jar"},
             200: {"name": "java.exe",
                   "cmd": r"java -javaagent:C:\Program Files\app\agent.jar -jar app.jar"}}
    c = Collector()
    _wpd_java_surface(c, procs)
    want = "如需确认内存马，可在授权下于该 JVM 上使用 jcmd / jmap 取证（本工具只读，不做 JVM attach）"
    high = [f for f in c.findings if f.level == "高危" and "-javaagent" in (f.title or "")]
    mid = [f for f in c.findings if f.level == "中危" and "-javaagent" in (f.title or "")]
    ok = (len(high) == 1 and len(mid) == 1
          and want in (high[0].advice or "") and want in (mid[0].advice or ""))
    return ok, {"high": len(high), "mid": len(mid),
                "advice_high": want in (high[0].advice or "") if high else False,
                "advice_mid": want in (mid[0].advice or "") if mid else False}


