def _st_r24_builtin_counts(ctx):
    y_rules, yp = _r13_yara_parse_text(_R14_BUILTIN_YARA_TEXT, "内置自检", origin="builtin")
    s_rules, sp = _r14_parse_builtin_sigma(_R14_BUILTIN_SIGMA_TEXT)
    names = [r.get("name") for r in y_rules]
    ids = [r.get("id") for r in s_rules]
    ok = (16 <= len(y_rules) <= 20 and 14 <= len(s_rules) <= 20
          and 30 <= len(y_rules) + len(s_rules) <= 40
          and not yp and not sp
          and len(set(names)) == len(names) and len(set(ids)) == len(ids)
          and all(r.get("origin") == "builtin" for r in y_rules + s_rules))
    return ok, {"yara": len(y_rules), "sigma": len(s_rules), "yp": yp[:3], "sp": sp[:3],
                "dup_y": len(names) - len(set(names)), "dup_s": len(ids) - len(set(ids))}


@_case("N.R24.builtin.silverfox.正例1-银狐族 11 条（6 YARA-like + 5 Sigma）逐条仍在库、family/source 未变、关键串未变")
def _st_r24_silverfox_kept(ctx):
    y_rules, _yp = _r13_yara_parse_text(_R14_BUILTIN_YARA_TEXT, "内置自检", origin="builtin")
    s_rules, _sp = _r14_parse_builtin_sigma(_R14_BUILTIN_SIGMA_TEXT)
    by_name = dict((r.get("name"), r) for r in y_rules)
    want_y = ("SF_ValleyRAT_ConfigMarkers", "SF_Fake_UpdateOrchestrator_TaskXML",
              "SF_NVSmart_SideloadPair", "SF_PhishFake_Installer_DingTalk",
              "SF_PhishFin_TaxNames", "SF_NoBlack_WinRdlv3_Tool")
    want_s = ("er-builtin-silverfox-ggaa-netsvcs", "er-builtin-silverfox-regsvr32-shlext64",
              "er-builtin-silverfox-defender-exclusion",
              "er-builtin-silverfox-updateorchestrator-taskcreate",
              "er-builtin-silverfox-updateorchestrator-taskregister")
    missing = [n for n in want_y if n not in by_name]
    fam_bad = [n for n in want_y
               if n in by_name and by_name[n].get("family") != "silverfox"]
    sf = by_name.get("SF_ValleyRAT_ConfigMarkers")
    pats = set()
    for s in (sf.get("strings") if sf else []) or []:
        for spec in s.get("pats") or []:
            pats.add(spec.get("pat"))
    ok_pat = b"|p1:" in pats and b"|bb:" in pats and b"|bh" in pats
    s_ids = set(r.get("id") for r in s_rules)
    missing_s = [n for n in want_s if n not in s_ids]
    fam_bad_s = [r.get("id") for r in s_rules
                 if r.get("id") in want_s and r.get("family") != "silverfox"]
    ok = (not missing and not fam_bad and ok_pat and not missing_s and not fam_bad_s)
    return ok, {"missing": missing, "fam_bad": fam_bad, "ok_pat": ok_pat,
                "missing_s": missing_s, "fam_bad_s": fam_bad_s}


# ============================================================ O 组 | R25（UI 档位 · 目录选择 · 白名单打开 · 处置建议导出）

_section("== O 组 | R25（UI 档位 · 目录选择 · 白名单打开 · 处置建议导出）==")


@_case("O.R25.tier.正例1-tier 归一：deep 等价 --deep（三面参数），default/fast 不加深挖键，fast 只切取数档位")
def _st_r25_tier_norm_pos(ctx):
    o_def = r21_oneclick_opts("win", {"tier": "default", "dirs": [], "days": 30})
    o_fast = r21_oneclick_opts("linux", {"tier": "fast"})
    o_deep = r21_oneclick_opts("win", {"tier": "deep", "max_targets": 5})
    f_def = r21_tier_flags({"tier": "default"})
    f_fast = r21_tier_flags({"fast": True})
    f_deep = r21_tier_flags(dict(_R21_DEEP_ON))        # 复用唯一字面量定义，不新增
    f_none = r21_tier_flags({})
    ok = ("deep" not in o_def and "max_targets" not in o_def and "target" not in o_def
          and "deep" not in o_fast and "max_targets" not in o_fast
          and o_deep.get("deep") is True and o_deep.get("max_targets") == 5
          and o_deep.get("target") is None
          and f_def["tier"] == "default" and f_none["tier"] == "default"
          and f_fast["tier"] == "fast" and f_fast["fast"] is True and f_fast["deep"] is False
          and f_deep["tier"] == "deep" and f_deep["deep"] is True and f_deep["fast"] is False)
    return ok, {"default_keys": sorted(o_def), "fast_keys": sorted(o_fast),
                "deep": dict((k, o_deep.get(k)) for k in ("deep", "target", "max_targets"))}


@_case("O.R25.tier.反例1-fast 与 deep 同给必须拒绝并报错（tier 冲突 / 旗标冲突 / 一键构造点同拒）")
def _st_r25_tier_conflict_neg(ctx):
    got = []
    for payload in (dict({"tier": "fast"}, **_R21_DEEP_ON),
                    dict({"fast": True}, **_R21_DEEP_ON),      # 复用唯一字面量定义，不新增
                    {"tier": "deep", "fast": True}):
        try:
            r21_tier_flags(payload)
            got.append(None)
        except ValueError as e:
            got.append(str(e))
    try:
        r21_oneclick_opts("win", dict({"tier": "fast"}, **_R21_DEEP_ON))
        got.append(None)
    except ValueError as e:
        got.append(str(e))
    ok = all(g and "档位冲突" in g for g in got)
    return ok, {"errors": got}


@_case("O.R25.tier.反例2-未知档位显式报错（不静默按默认档跑）")
def _st_r25_tier_unknown_neg(ctx):
    try:
        r21_tier_flags({"tier": "turbo"})
        return False, "未拒绝"
    except ValueError as e:
        return ("未知档位" in str(e)), {"error": str(e)}


@_case("O.R25.tier.反例3-单点模式档位适用性：fast/default 拒绝（固定深挖档）、deep 与 win/linux 放行")
def _st_r25_ui_guard_neg(ctx):
    got = {}
    bad = 0
    for mode, tier in (("weblog", "fast"), ("malware", "default"), ("webshell", "default")):
        try:
            r25_ui_tier_guard(mode, r21_tier_flags({"tier": tier}))
            bad += 1
        except ValueError as e:
            got[mode] = str(e)
    r25_ui_tier_guard("weblog", r21_tier_flags({"tier": "deep"}))     # 不抛
    r25_ui_tier_guard("win", r21_tier_flags({"tier": "fast"}))        # 一键模式不限制
    ok = (bad == 0 and len(got) == 3 and all("固定" in v for v in got.values()))
    return ok, {"errors": got, "bad": bad}


@_case("O.R25.ls.正例1-列已知目录：ok/path/parent/dirs/files+size 齐备（临时目录自建自列）")
def _st_r25_ls_pos(ctx):
    d = ctx.tmpdir()
    os.makedirs(os.path.join(d, "subdir"))
    _st_write(os.path.join(d, "probe.txt"), "x" * 2048)
    r = ui_list_dir(d)
    names_d = [x["name"] for x in r.get("dirs") or []]
    names_f = [x["name"] for x in r.get("files") or []]
    f0 = (r.get("files") or [{}])[0]
    ok = (r.get("ok") is True and os.path.abspath(d) == r.get("path")
          and "subdir" in names_d and "probe.txt" in names_f
          and bool(f0.get("size")) and f0.get("path") == os.path.join(d, "probe.txt")
          and bool(r.get("parent")))
    return ok, {"ok": r.get("ok"), "dirs": names_d, "files": names_f, "size": f0.get("size")}


@_case("O.R25.ls.负例1-不存在路径 / 非目录（给文件）都必须拒绝并给可读中文错误")
def _st_r25_ls_neg(ctx):
    d = ctx.tmpdir()
    f = _st_write(os.path.join(d, "afile.txt"), "x")
    r1 = ui_list_dir(os.path.join(d, "no_such_dir_r25"))
    r2 = ui_list_dir(f)
    ok = (r1.get("ok") is False and "不存在" in str(r1.get("error"))
          and r2.get("ok") is False and "不存在" in str(r2.get("error")))
    return ok, {"miss": r1, "file": r2}


@_case("O.R25.open.负例1-白名单：空 target / 其它目录 / outdir 是文件 / 无任务目录 一律拒绝")
def _st_r25_open_neg(ctx):
    d = ctx.tmpdir()
    outdir = os.path.join(d, "out"); os.makedirs(outdir)
    other = os.path.join(d, "other"); os.makedirs(other)
    afile = _st_write(os.path.join(outdir, "report.html"), "x")
    save = dict(_JOB)
    try:
        _JOB.update({"id": "r25selftest", "outdir": outdir, "mode": "win"})
        ok1, e1 = ui_open_path("")
        ok2, e2 = ui_open_path(other)
        ok3, e3 = ui_open_path(afile)
        _JOB["outdir"] = ""
        ok4, e4 = ui_open_path(outdir)
        ok5, e5 = ui_open_path(os.getcwd())      # 空 outdir 时连当前工作目录也必须拒绝
        ok = ((not ok1) and (not ok2) and (not ok3) and (not ok4) and (not ok5)
              and all("只允许打开本次任务的输出目录" in x for x in (e1, e2, e3, e4, e5)))
        return ok, {"errors": [e1, e2, e3, e4, e5]}
    finally:
        _JOB.clear(); _JOB.update(save)


def _r25_genfix_fixture(ctx, mode="win", findings=None):
    """处置建议自检夹具：临时输出目录 + findings.json（含 advice 与乱序等级）。"""
    d = ctx.tmpdir()
    out = os.path.join(d, "ER-Report-SELFTEST")
    os.makedirs(out)
    data = {"meta": {"host": "SELFTEST", "mode": "自检", "time": "2026-10-16 12:00:00"},
            "findings": findings if findings is not None else [
                {"level": "提示", "category": "信息", "title": "提示项", "detail": "d0",
                 "evidence": [], "advice": "建议D"},
                {"level": "严重", "category": "持久化", "title": "严重项", "detail": "d1\n第二行",
                 "evidence": ["ev1"], "advice": "建议A"},
                {"level": "高危", "category": "进程", "title": "高危项", "detail": "",
                 "evidence": ["ev2", "ev3"], "advice": "建议B"}]}
    write_text(os.path.join(out, "findings.json"), json.dumps(data, ensure_ascii=False))
    return out


@_case("O.R25.genfix.正例1-win：生成 处置建议.md+suggested_fixes.ps1，含 advice/只读声明、按等级排序、重复点击覆盖")
def _st_r25_genfix_pos(ctx):
    out = _r25_genfix_fixture(ctx, mode="win")
    save = dict(_JOB)
    try:
        _JOB.update({"id": "r25gen", "outdir": out, "mode": "win"})
        r1 = ui_genfix({"job": "r25gen"})
        md = safe_read(os.path.join(out, _R25_FIX_MD)) or ""
        sc = safe_read(os.path.join(out, _R25_FIX_PS1)) or ""
        r2 = ui_genfix({"job": "r25gen"})              # 重复点击：覆盖同名文件，不留副本
        entries = sorted(os.listdir(out))
        i_sev = md.find("严重项"); i_hi = md.find("高危项"); i_inf = md.find("提示项")
        ok = (r1.get("ok") is True and r2.get("ok") is True
              and r1.get("files", {}).get("script") == _R25_FIX_PS1
              and r1.get("files") == r2.get("files")
              and "建议A" in md and "建议B" in md and "建议D" in md
              and _R25_FIX_NOTE in md and _R25_FIX_NOTE in sc and "建议A" in sc
              and 0 < i_sev < i_hi < i_inf
              and _R25_FIX_MD in entries and _R25_FIX_PS1 in entries
              and len([x for x in entries if x.startswith("suggested_fixes")]) == 1
              and len([x for x in entries if x.endswith(".md") or x.endswith(".ps1")]) == 2)
        return ok, {"files": r1.get("files"), "entries": entries,
                    "order": [i_sev, i_hi, i_inf], "count": r1.get("count")}
    finally:
        _JOB.clear(); _JOB.update(save)


@_case("O.R25.genfix.正例2-Linux 模式产出 suggested_fixes.sh（脚本名随平台，.ps1 不出现）")
def _st_r25_genfix_linux_pos(ctx):
    out = _r25_genfix_fixture(ctx, mode="linux")
